const RECIPES = [
  // ---------------- RICE ----------------
  { name:"Chicken Fried Rice", cuisine:"Chinese-American", ingredients:"Chicken, rice, egg, soy sauce, peas", mood:"Quick & Comforting", difficulty:"Easy", why:"One-pan magic that turns last night's leftover rice into a brand-new meal.", mainBase:"Rice", image:"images/chicken-fried-rice.png", description:"This weeknight favorite starts with day-old rice, which fries up firmer and less sticky than fresh rice. Tender bites of chicken, scrambled egg, and sweet peas are tossed together in a hot wok with a splash of savory soy sauce, giving every spoonful a satisfying mix of textures. It's a fantastic way to use up leftovers while still feeling like a proper home-cooked meal, and it comes together in under 20 minutes flat.",
    ingredientsList:["2 cups cooked jasmine rice (day-old)","1 boneless chicken breast, diced","2 large eggs","3 tbsp soy sauce","1/2 cup frozen peas and carrots","2 tbsp vegetable oil","2 cloves garlic, minced","2 green onions, sliced"],
    steps:["Heat 1 tbsp oil in a large wok or skillet over high heat.","Add diced chicken and cook until golden and cooked through, about 5 minutes; remove and set aside.","Push rice to one side, crack in eggs on the other side, and scramble until just set.","Add garlic, peas and carrots, and cooked chicken; stir-fry everything together for 2 minutes.","Pour in soy sauce, toss well to coat, and garnish with sliced green onions before serving."] },
  { name:"Spanish Paella", cuisine:"Spanish", ingredients:"Rice, saffron, shrimp, chicken, peppers", mood:"Festive & Colorful", difficulty:"Medium", why:"A show-stopping one-pan dish perfect for weekend gatherings.", mainBase:"Rice", image:"images/spanish-paella.png", description:"Paella is Spain's beloved celebration dish, built around short-grain rice slowly simmered in a saffron-infused broth until it turns a deep golden hue. Juicy shrimp, tender chicken, and sweet bell peppers are layered on top, while the rice at the bottom develops a coveted crispy crust called socarrat. Traditionally cooked in a wide shallow pan and served straight from it, paella turns any weekend dinner into a shared, festive occasion.",
    ingredientsList:["2 cups short-grain rice (bomba or arborio)","1/2 tsp saffron threads","4 cups chicken or seafood stock","8 large shrimp, peeled","1 chicken thigh, cut into pieces","1 red bell pepper, sliced","1 onion, diced","3 cloves garlic, minced","2 tbsp olive oil"],
    steps:["Heat olive oil in a wide paella pan and brown the chicken pieces on both sides; set aside.","Sauté onion, garlic, and bell pepper in the same pan until softened.","Stir in rice, coating it in the oil, then add saffron-infused stock.","Nestle the browned chicken back into the pan and simmer without stirring for 15-18 minutes.","Add shrimp on top for the last 5 minutes of cooking, and let a crispy socarrat form on the bottom before serving."] },
  { name:"Japanese Onigiri", cuisine:"Japanese", ingredients:"Rice, nori, salmon, salt", mood:"Cozy & Simple", difficulty:"Easy", why:"Portable rice balls perfect for lunchboxes and busy mornings.", mainBase:"Rice", image:"images/japanese-onigiri.png", description:"Onigiri are hand-shaped rice balls that have been a staple of Japanese home cooking and bento boxes for generations. Warm, lightly salted rice is pressed around a savory filling of flaked salmon, then wrapped in a crisp sheet of nori seaweed for a satisfying textural contrast. They travel beautifully, taste great at room temperature, and make an easy grab-and-go breakfast or lunch for busy mornings.",
    ingredientsList:["2 cups cooked short-grain Japanese rice, warm","1 sheet nori, cut into strips","1/2 cup cooked salmon, flaked","1/2 tsp salt","water for wetting hands"],
    steps:["Wet your hands with water and rub a pinch of salt into your palms.","Scoop about 1/2 cup of warm rice into your palm and flatten slightly.","Press a spoonful of flaked salmon into the center and fold the rice around it.","Shape into a triangle or ball by pressing firmly with both hands.","Wrap a strip of nori around the base before serving."] },
  { name:"Mexican Rice Bowl", cuisine:"Mexican", ingredients:"Rice, black beans, corn, avocado, lime", mood:"Fresh & Zesty", difficulty:"Easy", why:"A vibrant bowl loaded with color and bold Tex-Mex flavor.", mainBase:"Rice", image:"images/mexican-rice-bowl.png", description:"This build-your-own style bowl layers fluffy rice with hearty black beans, sweet charred corn, and creamy avocado, all brightened up with a generous squeeze of fresh lime juice. It's naturally vegetarian, endlessly customizable with your favorite toppings like salsa or cheese, and comes together mostly from pantry staples. The combination of textures and bold Tex-Mex flavors makes it a go-to for quick, colorful weeknight dinners.",
    ingredientsList:["2 cups cooked white rice","1 can black beans, drained and rinsed","1 cup corn kernels","1 avocado, sliced","1 lime, juiced","1/2 cup salsa","1/4 cup shredded cheese","fresh cilantro"],
    steps:["Warm the black beans and corn in a small pan over medium heat.","Divide the cooked rice between bowls as the base.","Top with warm beans, corn, and sliced avocado.","Spoon salsa over the top and sprinkle with shredded cheese.","Finish with a squeeze of fresh lime juice and chopped cilantro."] },
  { name:"Chicken Biryani", cuisine:"Indian", ingredients:"Basmati rice, chicken, yogurt, spices", mood:"Warm & Aromatic", difficulty:"Medium", why:"Fragrant layers of spiced rice and tender chicken in every bite.", mainBase:"Rice", image:"images/chicken-biryani.png", description:"Biryani is a fragrant, celebratory rice dish beloved across South Asia, made by layering long-grain basmati rice with chicken marinated in yogurt and a warm blend of spices like cardamom, cinnamon, and cloves. The whole pot is slow-cooked so the rice absorbs all those aromas while staying light and fluffy. Each spoonful delivers a different balance of spice, tenderness, and fragrance, making it a dish that feels special enough for guests yet comforting enough for a family dinner.",
    ingredientsList:["2 cups basmati rice","500g chicken thighs","1 cup plain yogurt","2 onions, thinly sliced","2 tbsp biryani spice mix","1/2 tsp saffron, soaked in warm milk","3 tbsp ghee","fresh mint and cilantro"],
    steps:["Marinate chicken in yogurt and biryani spices for at least 1 hour.","Fry sliced onions in ghee until deep golden brown; set half aside for garnish.","Cook the marinated chicken with the remaining fried onions until nearly done.","Parboil the basmati rice separately until 70% cooked, then drain.","Layer the rice over the chicken, drizzle with saffron milk, cover tightly, and steam on low heat for 20 minutes before fluffing and serving."] },
  { name:"Mushroom Risotto", cuisine:"Italian", ingredients:"Arborio rice, mushrooms, parmesan, butter", mood:"Creamy & Relaxing", difficulty:"Medium", why:"Slow-stirred comfort food that feels like a warm hug.", mainBase:"Rice", image:"images/mushroom-risotto.png", description:"Risotto is a labor of love — starchy Arborio rice is toasted, then slowly bathed in warm broth one ladle at a time while you stir, coaxing out its natural creaminess without any cream at all. Earthy sautéed mushrooms add a deep, savory note, while a generous finish of butter and parmesan makes the whole dish silky and rich. The gentle, repetitive stirring process is almost meditative, making it as relaxing to cook as it is comforting to eat.",
    ingredientsList:["1.5 cups arborio rice","300g mixed mushrooms, sliced","4 cups warm vegetable broth","1/2 cup dry white wine","1 onion, finely diced","1/2 cup grated parmesan","3 tbsp butter"],
    steps:["Sauté mushrooms in a little butter until golden; set aside.","In the same pan, cook onion until translucent, then add rice and toast for 1-2 minutes.","Pour in the wine and stir until absorbed.","Add warm broth one ladle at a time, stirring often, until each addition is absorbed before adding more.","Once rice is creamy and tender, stir in mushrooms, butter, and parmesan before serving."] },
  { name:"Korean Bibimbap", cuisine:"Korean", ingredients:"Rice, vegetables, egg, gochujang", mood:"Energizing & Balanced", difficulty:"Easy", why:"A colorful mix-it-yourself bowl packed with veggies and flavor.", mainBase:"Rice", image:"images/korean-bibimbap.png", description:"Bibimbap literally means 'mixed rice,' and it lives up to its name with a beautiful arrangement of sautéed vegetables, a fried egg, and warm rice all topped with a dollop of spicy-sweet gochujang sauce. Part of the fun is mixing everything together yourself right before eating, so every bite gets a slightly different balance of color, crunch, and heat. It's a wonderfully balanced meal that feels both nourishing and exciting.",
    ingredientsList:["2 cups cooked white rice","1 carrot, julienned","1 cup spinach, blanched","1 cup bean sprouts","1 zucchini, julienned and sautéed","1 egg, fried","2 tbsp gochujang","1 tsp sesame oil"],
    steps:["Prepare each vegetable separately, seasoning lightly with sesame oil and salt.","Fry an egg sunny-side up, keeping the yolk runny.","Add warm rice to a bowl and arrange the vegetables around the edge.","Top with the fried egg and a generous dollop of gochujang in the center.","Mix everything together thoroughly just before eating."] },
  { name:"Caribbean Coconut Rice", cuisine:"Caribbean", ingredients:"Rice, coconut milk, beans, thyme", mood:"Tropical & Sunny", difficulty:"Easy", why:"Creamy coconut rice that brings island vibes to your dinner table.", mainBase:"Rice", image:"images/caribbean-coconut-rice.png", description:"This Caribbean staple swaps out plain water for rich coconut milk, giving the rice a subtly sweet, creamy backdrop that pairs beautifully with hearty beans and fragrant fresh thyme. It's traditionally served alongside grilled meats or fish, but it's satisfying enough to enjoy entirely on its own. One bite and you'll feel like you've been transported straight to a sunny island kitchen.",
    ingredientsList:["2 cups long-grain rice","1 can coconut milk","1 cup water","1 can kidney beans, drained","2 sprigs fresh thyme","1 clove garlic, minced","salt to taste"],
    steps:["Combine coconut milk, water, garlic, and thyme in a pot and bring to a simmer.","Stir in the rice and kidney beans.","Cover and cook on low heat for 18-20 minutes until rice is tender and liquid is absorbed.","Remove thyme sprigs and fluff the rice with a fork.","Season with salt to taste before serving."] },

  { name:"Teriyaki Salmon Rice Bowl", cuisine:"Japanese Fusion", ingredients:"Rice, salmon, teriyaki sauce, broccoli", mood:"Balanced & Savory", difficulty:"Easy", why:"A glossy rice bowl that feels fresh, filling, and restaurant-worthy.", mainBase:"Rice", image:"images/teriyaki-salmon-rice-bowl.png", description:"This bowl layers fluffy steamed rice with tender salmon brushed in a sweet-savory teriyaki glaze. Crisp broccoli, cucumber, and carrots add color and freshness, while sesame seeds and scallions bring a simple finishing crunch. It is satisfying enough for dinner but still clean and balanced for a weekday meal.",
    ingredientsList:["2 cups cooked white rice","2 salmon fillets","1/3 cup teriyaki sauce","1 cup broccoli florets","1/2 cucumber, sliced","1 carrot, julienned","1 tbsp sesame seeds","2 scallions, sliced"],
    steps:["Steam or warm the rice and divide it between bowls.","Sear salmon fillets in a lightly oiled pan until almost cooked through.","Brush with teriyaki sauce and cook for 1-2 minutes until glossy.","Steam broccoli until bright green and tender-crisp.","Arrange salmon, vegetables, sesame seeds, and scallions over the rice before serving."] },
  { name:"Tomato Egg Rice", cuisine:"Chinese Home Style", ingredients:"Rice, tomato, egg, scallion", mood:"Simple & Cozy", difficulty:"Easy", why:"A humble comfort bowl with soft eggs and bright tomato sauce.", mainBase:"Rice", image:"images/tomato-egg-rice.png", description:"Tomato egg rice is the kind of quick home-style meal that turns pantry basics into something deeply comforting. Juicy tomatoes cook down into a light sauce, soft scrambled eggs soak up the flavor, and warm rice catches every spoonful. It is gentle, colorful, and ready fast.",
    ingredientsList:["2 cups cooked white rice","3 ripe tomatoes, chopped","3 eggs, beaten","2 scallions, sliced","1 tsp sugar","1 tbsp soy sauce","1 tbsp neutral oil","salt to taste"],
    steps:["Scramble the beaten eggs in hot oil until just set, then remove from the pan.","Add tomatoes to the same pan and cook until juicy and softened.","Season with sugar, soy sauce, and a pinch of salt.","Return the eggs and fold gently into the tomato sauce.","Spoon over warm rice and finish with sliced scallions."] },
  { name:"Kimchi Fried Rice", cuisine:"Korean", ingredients:"Rice, kimchi, egg, scallion, sesame", mood:"Spicy & Comforting", difficulty:"Easy", why:"A punchy fried rice that turns leftovers into a bold, cozy meal.", mainBase:"Rice", image:"images/kimchi-fried-rice.webp", description:"Kimchi fried rice is a fast, flavorful way to use day-old rice and a little fermented heat. Chopped kimchi seasons the whole pan with tang, spice, and depth, while a fried egg on top makes it feel complete. It is simple, satisfying, and especially good when you want comfort food with energy.",
    ingredientsList:["2 cups day-old rice","1 cup chopped kimchi","2 eggs","2 scallions, sliced","1 tbsp gochujang, optional","1 tbsp sesame oil","1 tbsp soy sauce","1 tsp sesame seeds"],
    steps:["Heat sesame oil in a skillet and stir-fry kimchi for 2 minutes.","Add rice and break up any clumps as it fries.","Season with soy sauce and gochujang if using.","Fry eggs separately until the edges are crisp.","Top the rice with eggs, scallions, and sesame seeds before serving."] },
  { name:"Thai Pineapple Fried Rice", cuisine:"Thai", ingredients:"Rice, pineapple, shrimp, cashews, peas", mood:"Sunny & Sweet-Savory", difficulty:"Easy", why:"Pineapple and cashews make fried rice bright, crunchy, and fun.", mainBase:"Rice", image:"images/thai-pineapple-fried-rice.webp", description:"This fried rice balances sweet pineapple with savory shrimp, tender rice, and crunchy cashews. A little curry powder gives the rice a golden color, while peas and scallions keep it fresh. It feels festive but is still easy enough for a weeknight skillet meal.",
    ingredientsList:["2 cups cooked jasmine rice","1 cup pineapple chunks","200g shrimp, peeled","1/2 cup peas","1/3 cup cashews","2 eggs","1 tsp curry powder","2 tbsp soy sauce","2 scallions, sliced"],
    steps:["Scramble the eggs in a hot wok, then set aside.","Stir-fry shrimp until pink and just cooked.","Add rice, curry powder, pineapple, and peas.","Toss with soy sauce until the rice is evenly seasoned.","Fold in eggs and cashews, then finish with scallions."] },
  { name:"Garlic Butter Shrimp Rice", cuisine:"American Fusion", ingredients:"Rice, shrimp, garlic, butter, lemon", mood:"Buttery & Bright", difficulty:"Easy", why:"Juicy shrimp and garlic butter make plain rice feel special fast.", mainBase:"Rice", image:"images/garlic-butter-shrimp-rice.webp", description:"Garlic butter shrimp rice is simple but generous. Shrimp are quickly cooked with garlic, butter, lemon, and parsley, then spooned over warm rice so the buttery sauce sinks into every grain. It is a quick dinner that tastes polished without needing many ingredients.",
    ingredientsList:["2 cups cooked rice","300g shrimp, peeled","3 cloves garlic, minced","3 tbsp butter","1 lemon, juiced","2 tbsp parsley, chopped","salt and black pepper to taste"],
    steps:["Season shrimp with salt and pepper.","Melt butter in a pan and cook garlic until fragrant.","Add shrimp and cook until pink on both sides.","Squeeze in lemon juice and stir in parsley.","Serve the shrimp and buttery pan sauce over warm rice."] },
  { name:"Mediterranean Chickpea Rice", cuisine:"Mediterranean", ingredients:"Rice, chickpeas, cucumber, tomato, feta", mood:"Fresh & Nourishing", difficulty:"Easy", why:"A colorful rice bowl with bright vegetables and creamy feta.", mainBase:"Rice", image:"images/mediterranean-chickpea-rice.webp", description:"This bowl turns rice into a fresh Mediterranean-style meal with chickpeas, cucumber, tomatoes, olives, and feta. Lemon and herbs keep the flavors bright, while chickpeas make it filling enough for lunch or dinner. It is colorful, balanced, and easy to prep ahead.",
    ingredientsList:["2 cups cooked rice","1 can chickpeas, drained","1 cucumber, diced","1 cup cherry tomatoes, halved","1/2 cup feta","1/3 cup olives","2 tbsp olive oil","1 lemon, juiced","fresh parsley"],
    steps:["Fluff warm or cooled rice in a large bowl.","Add chickpeas, cucumber, tomatoes, olives, and feta.","Whisk olive oil with lemon juice, salt, and pepper.","Toss everything gently with the dressing.","Finish with fresh parsley before serving."] },
  { name:"Arroz con Pollo", cuisine:"Latin American", ingredients:"Rice, chicken, peas, peppers, saffron", mood:"Hearty & Colorful", difficulty:"Medium", why:"Chicken and golden rice cook together into a comforting one-pan meal.", mainBase:"Rice", image:"images/arroz-con-pollo.webp", description:"Arroz con pollo is a generous one-pan dish where chicken seasons the rice as it cooks. Bell peppers, peas, olives, and warm spices bring color and depth, while the rice absorbs all the savory juices. It is a family-style meal that feels both rustic and celebratory.",
    ingredientsList:["1.5 cups long-grain rice","4 chicken thighs or drumsticks","1 bell pepper, diced","1/2 cup peas","1/3 cup olives","3 cups chicken broth","1 tsp paprika","1/2 tsp turmeric or saffron","2 tbsp olive oil"],
    steps:["Brown the chicken in olive oil, then remove from the pan.","Saute bell pepper until softened.","Stir in rice, paprika, turmeric, broth, peas, and olives.","Nestle the chicken back into the pan.","Cover and simmer until the rice is tender and chicken is cooked through."] },
  { name:"Tofu Teriyaki Rice Bowl", cuisine:"Japanese Fusion", ingredients:"Rice, tofu, teriyaki sauce, broccoli", mood:"Plant-Based & Savory", difficulty:"Easy", why:"Crispy tofu and glossy sauce make a satisfying meatless rice bowl.", mainBase:"Rice", image:"images/tofu-teriyaki-rice-bowl.webp", description:"Crispy tofu cubes are coated in teriyaki sauce and served over rice with bright vegetables. The contrast of soft rice, sticky glaze, and crisp-tender broccoli makes every bite satisfying. It is an easy plant-based bowl that still feels hearty.",
    ingredientsList:["2 cups cooked rice","400g firm tofu, cubed","1/3 cup teriyaki sauce","1 cup broccoli florets","1 carrot, julienned","1 tbsp cornstarch","1 tbsp sesame oil","sesame seeds and scallions"],
    steps:["Pat tofu dry and toss with cornstarch.","Pan-fry tofu in sesame oil until golden on all sides.","Steam broccoli until tender-crisp.","Toss tofu with teriyaki sauce until glossy.","Serve over rice with vegetables, sesame seeds, and scallions."] },
  { name:"Beef Pepper Rice", cuisine:"Japanese Inspired", ingredients:"Rice, beef, corn, butter, black pepper", mood:"Sizzling & Savory", difficulty:"Easy", why:"Thin beef, corn, butter, and pepper turn rice into a bold skillet meal.", mainBase:"Rice", image:"images/beef-pepper-rice.webp", description:"Beef pepper rice is built around hot rice, thin beef slices, sweet corn, butter, and a generous hit of black pepper. As everything warms together, the butter melts into the rice and the sauce coats the beef. It is rich, quick, and deeply savory.",
    ingredientsList:["2 cups hot cooked rice","250g thin sliced beef","1/2 cup corn","2 scallions, sliced","1 tbsp butter","2 tbsp soy sauce","1 tbsp honey or sugar","black pepper to taste"],
    steps:["Mix soy sauce with honey and black pepper.","Sear beef quickly in a hot skillet until just browned.","Add rice, corn, and butter to the pan.","Pour in the sauce and toss until everything is hot and glossy.","Finish with scallions and extra black pepper."] },
  { name:"Lemon Herb Chicken Rice", cuisine:"Mediterranean Fusion", ingredients:"Rice, chicken, lemon, parsley, zucchini", mood:"Bright & Wholesome", difficulty:"Easy", why:"Lemon and herbs keep this chicken rice bowl light but satisfying.", mainBase:"Rice", image:"images/lemon-herb-chicken-rice.webp", description:"This bowl pairs fluffy rice with sliced lemon herb chicken and simple vegetables. The lemon brightens the whole dish, while parsley and olive oil bring a clean Mediterranean feel. It is the kind of dependable meal that works for lunch prep or a relaxed dinner.",
    ingredientsList:["2 cups cooked rice","2 chicken breasts","1 lemon, zested and juiced","1 zucchini, sliced","2 tbsp olive oil","2 tbsp parsley, chopped","1 clove garlic, minced","salt and black pepper to taste"],
    steps:["Season chicken with lemon zest, garlic, salt, pepper, and olive oil.","Sear or grill until cooked through, then slice.","Saute zucchini until lightly browned.","Toss rice with lemon juice and parsley.","Serve chicken and zucchini over the lemon herb rice."] },
  { name:"Persian Jeweled Rice", cuisine:"Persian Inspired", ingredients:"Basmati rice, saffron, nuts, dried fruit", mood:"Fragrant & Festive", difficulty:"Medium", why:"Saffron rice with nuts and dried fruit feels bright and celebratory.", mainBase:"Rice", image:"images/persian-jeweled-rice.webp", description:"Persian jeweled rice is fragrant, colorful, and beautiful on the table. Long-grain basmati is tinted with saffron and scattered with pistachios, almonds, orange zest, and dried fruit. Each spoonful is aromatic, slightly sweet, and full of texture.",
    ingredientsList:["2 cups basmati rice","1/4 tsp saffron threads","1/3 cup pistachios","1/3 cup almonds","1/2 cup dried cranberries or barberries","1/3 cup golden raisins","1 orange, zested","2 tbsp butter"],
    steps:["Rinse basmati rice until the water runs mostly clear.","Cook rice until fluffy, then gently fold in saffron-infused water.","Toast nuts in butter until fragrant.","Add dried fruit and orange zest to the nuts.","Scatter the jeweled topping over the rice before serving."] },
  { name:"Cajun Jambalaya Rice", cuisine:"Cajun", ingredients:"Rice, sausage, chicken, shrimp, peppers", mood:"Bold & Smoky", difficulty:"Medium", why:"A spicy one-pot rice dish packed with protein and color.", mainBase:"Rice", image:"images/cajun-jambalaya-rice.webp", description:"Jambalaya is a bold one-pot rice dish loaded with smoky sausage, chicken, shrimp, peppers, and Cajun seasoning. The rice cooks directly in the seasoned broth, soaking up layers of spice and savory flavor. It is hearty, colorful, and made for big appetites.",
    ingredientsList:["1.5 cups long-grain rice","200g smoked sausage, sliced","250g chicken, diced","200g shrimp, peeled","1 bell pepper, diced","2 celery stalks, diced","1 can diced tomatoes","3 cups broth","2 tsp Cajun seasoning"],
    steps:["Brown sausage and chicken in a large pot.","Add bell pepper and celery and cook until softened.","Stir in rice, tomatoes, broth, and Cajun seasoning.","Cover and simmer until rice is almost tender.","Add shrimp for the final few minutes until pink and cooked through."] },
  { name:"Indonesian Nasi Goreng", cuisine:"Indonesian", ingredients:"Rice, egg, kecap manis, shallot, cucumber", mood:"Sweet-Savory & Aromatic", difficulty:"Easy", why:"Dark soy glaze and crispy shallots make fried rice deeply savory.", mainBase:"Rice", image:"images/indonesian-nasi-goreng.webp", description:"Nasi goreng gets its signature flavor from sweet soy sauce, aromatics, and a fried egg on top. The rice turns deeply savory and slightly caramelized, while cucumber, tomato, and crispy shallots add freshness and crunch. It is simple but packed with personality.",
    ingredientsList:["2 cups day-old rice","2 eggs","2 tbsp kecap manis or sweet soy sauce","1 shallot, sliced","2 cloves garlic, minced","1 red chili, sliced","cucumber and tomato, to serve","crispy shallots"],
    steps:["Fry eggs sunny-side up and set aside.","Saute shallot, garlic, and chili until fragrant.","Add rice and stir-fry until hot and separated.","Season with kecap manis and toss until evenly coated.","Serve with egg, cucumber, tomato, and crispy shallots."] },
  { name:"Sushi Bake Bowl", cuisine:"Japanese-American", ingredients:"Sushi rice, salmon, avocado, cucumber, nori", mood:"Creamy & Fun", difficulty:"Easy", why:"All the cozy flavors of sushi bake in an easy rice bowl.", mainBase:"Rice", image:"images/sushi-bake-bowl.webp", description:"This bowl captures the creamy, savory comfort of sushi bake without needing to assemble a casserole. Warm sushi rice is topped with seasoned salmon, avocado, cucumber, nori, sesame seeds, and a spicy mayo drizzle. It is playful, filling, and easy to customize.",
    ingredientsList:["2 cups cooked sushi rice","250g cooked salmon, flaked","1 avocado, diced","1 cucumber, diced","2 tbsp mayonnaise","1 tsp sriracha","nori strips","sesame seeds","2 scallions, sliced"],
    steps:["Season warm sushi rice with a little rice vinegar and salt.","Mix flaked salmon with mayonnaise and sriracha.","Add rice to bowls and top with salmon, avocado, and cucumber.","Scatter nori strips, sesame seeds, and scallions on top.","Drizzle with extra spicy mayo before serving."] },
  { name:"Cilantro Lime Rice Bowl", cuisine:"Mexican Inspired", ingredients:"Rice, chicken, black beans, corn, avocado", mood:"Fresh & Energizing", difficulty:"Easy", why:"Cilantro lime rice turns simple toppings into a bright, balanced bowl.", mainBase:"Rice", image:"images/cilantro-lime-rice-bowl.webp", description:"Cilantro lime rice forms a fresh base for grilled chicken, black beans, corn salsa, and avocado. The lime keeps everything lively, while the beans and chicken make the bowl satisfying. It is flexible enough for meal prep and colorful enough to feel exciting.",
    ingredientsList:["2 cups cooked rice","1 lime, juiced","1/2 cup cilantro, chopped","1 grilled chicken breast, sliced","1 cup black beans","1 cup corn salsa","1 avocado, diced","salt to taste"],
    steps:["Toss warm rice with lime juice, cilantro, and salt.","Slice grilled chicken into strips.","Warm black beans if desired.","Arrange rice, chicken, beans, corn salsa, and avocado in a bowl.","Finish with extra lime and cilantro."] },
  { name:"Mushroom Wild Rice Pilaf", cuisine:"American", ingredients:"Wild rice, mushrooms, onion, herbs, almonds", mood:"Earthy & Cozy", difficulty:"Medium", why:"Nutty wild rice and mushrooms make a deeply savory side or main.", mainBase:"Rice", image:"images/mushroom-wild-rice-pilaf.webp", description:"Wild rice brings a nutty chew that pairs beautifully with browned mushrooms and herbs. Toasted almonds add crunch, while onion and parsley round out the pilaf. It can stand alone as a vegetarian main or sit beside roasted meats as a hearty side.",
    ingredientsList:["1.5 cups wild rice blend","300g mushrooms, sliced","1 onion, diced","3 cups vegetable broth","1/3 cup sliced almonds","2 tbsp butter or olive oil","fresh parsley","salt and black pepper to taste"],
    steps:["Cook wild rice blend in broth until tender.","Saute mushrooms and onion until browned and savory.","Toast almonds in a dry pan until fragrant.","Fold mushrooms and almonds into the cooked rice.","Season with parsley, salt, and black pepper before serving."] },
  { name:"Cuban Black Beans and Rice", cuisine:"Cuban Inspired", ingredients:"Rice, black beans, peppers, avocado, lime", mood:"Hearty & Zesty", difficulty:"Easy", why:"Saucy black beans over rice make an easy, comforting bowl.", mainBase:"Rice", image:"images/cuban-black-beans-and-rice.webp", description:"Cuban-style black beans and rice is humble, hearty, and full of flavor. Beans simmer with peppers, onion, garlic, and cumin until saucy, then get spooned over white rice with avocado and lime. It is budget-friendly comfort food with a bright finish.",
    ingredientsList:["2 cups cooked white rice","1 can black beans, drained","1 bell pepper, diced","1 onion, diced","2 cloves garlic, minced","1 tsp cumin","1 avocado, sliced","1 lime, cut into wedges","fresh cilantro"],
    steps:["Saute onion, bell pepper, and garlic until softened.","Add black beans, cumin, and a splash of water.","Simmer until the beans turn saucy and flavorful.","Spoon beans over warm rice.","Top with avocado, cilantro, and lime wedges."] },
  // ---------------- PASTA ----------------
  { name:"Classic Spaghetti Bolognese", cuisine:"Italian", ingredients:"Spaghetti, ground beef, tomato, garlic", mood:"Hearty & Familiar", difficulty:"Easy", why:"The ultimate weeknight classic that everyone in the family loves.", mainBase:"Pasta", image:"images/classic-spaghetti-bolognese.png", description:"This is the pasta dish most of us grew up on — a rich, slow-simmered sauce of ground beef, garlic, and tomatoes ladled generously over al dente spaghetti. Letting the sauce simmer a little longer deepens the flavor and helps it cling perfectly to every strand of pasta. It's endlessly forgiving, easy to double for a crowd, and reheats beautifully, making it a reliable go-to for busy weeknights.",
    ingredientsList:["350g spaghetti","400g ground beef","1 can (400g) crushed tomatoes","3 cloves garlic, minced","1 onion, diced","2 tbsp tomato paste","2 tbsp olive oil","grated parmesan, to serve"],
    steps:["Heat olive oil in a large pan and sauté onion and garlic until fragrant.","Add ground beef and cook until browned, breaking it up as it cooks.","Stir in tomato paste, then add crushed tomatoes and simmer for 25-30 minutes.","Meanwhile, cook spaghetti in salted boiling water until al dente; drain.","Toss the pasta with the sauce and top with grated parmesan before serving."] },
  { name:"Creamy Fettuccine Alfredo", cuisine:"Italian", ingredients:"Fettuccine, cream, parmesan, butter", mood:"Indulgent & Cozy", difficulty:"Easy", why:"Rich, silky pasta ready in under 20 minutes.", mainBase:"Pasta", image:"images/creamy-fettuccine-alfredo.png", description:"With just a handful of ingredients — butter, cream, and freshly grated parmesan — this dish transforms simple fettuccine into something luxuriously silky. The sauce comes together in the time it takes the pasta to boil, making it one of the fastest routes to a truly indulgent dinner. It's rich enough to feel like a treat, yet simple enough to whip up on even the busiest weeknight.",
    ingredientsList:["350g fettuccine","1 cup heavy cream","1 cup grated parmesan","4 tbsp butter","2 cloves garlic, minced","salt and black pepper to taste"],
    steps:["Cook fettuccine in salted boiling water until al dente; reserve 1/2 cup pasta water and drain.","Melt butter in a pan and sauté garlic until fragrant.","Pour in cream and simmer gently for 2-3 minutes.","Stir in parmesan until melted and smooth, adding pasta water to loosen if needed.","Toss in the drained fettuccine, season with salt and pepper, and serve immediately."] },
  { name:"Garlic Shrimp Linguine", cuisine:"Italian-American", ingredients:"Linguine, shrimp, garlic, chili flakes", mood:"Light & Zesty", difficulty:"Medium", why:"A restaurant-style dish you can make on a busy weeknight.", mainBase:"Pasta", image:"images/garlic-shrimp-linguine.png", description:"Plump shrimp are quickly seared in olive oil with plenty of garlic and a pinch of chili flakes, then tossed with linguine and a splash of the starchy pasta water to bring everything together into a light, glossy sauce. The whole dish takes barely 20 minutes from start to finish, but the bold garlicky, slightly spicy flavor tastes like something you'd order at a proper Italian restaurant.",
    ingredientsList:["350g linguine","400g shrimp, peeled and deveined","4 cloves garlic, sliced","1/2 tsp chili flakes","3 tbsp olive oil","1 lemon, juiced","fresh parsley, chopped"],
    steps:["Cook linguine in salted boiling water until al dente; reserve 1/2 cup pasta water and drain.","Heat olive oil in a pan and sauté garlic and chili flakes until fragrant.","Add shrimp and cook until pink and just cooked through, about 2-3 minutes per side.","Toss in the linguine with a splash of pasta water to create a light sauce.","Finish with lemon juice and chopped parsley before serving."] },
  { name:"Pesto Penne", cuisine:"Italian", ingredients:"Penne, basil pesto, cherry tomatoes, pine nuts", mood:"Fresh & Herby", difficulty:"Easy", why:"A no-cook sauce that tastes like summer in a bowl.", mainBase:"Pasta", image:"images/pesto-penne.png", description:"Vibrant basil pesto — bright with garlic, pine nuts, and parmesan — needs no cooking at all, so it comes together while your penne boils. Sweet burst cherry tomatoes add juicy freshness, and a scattering of toasted pine nuts brings a satisfying crunch. It's a wonderfully fast, herb-forward dinner that tastes like a little taste of an Italian summer, any time of year.",
    ingredientsList:["350g penne","1/2 cup basil pesto","1 cup cherry tomatoes, halved","2 tbsp pine nuts, toasted","grated parmesan, to serve"],
    steps:["Cook penne in salted boiling water until al dente; reserve 1/4 cup pasta water and drain.","Toss the hot pasta with basil pesto, loosening with a little pasta water if needed.","Fold in the halved cherry tomatoes.","Sprinkle with toasted pine nuts and grated parmesan.","Serve warm or at room temperature."] },
  { name:"Baked Mac and Cheese", cuisine:"American", ingredients:"Macaroni, cheddar, milk, breadcrumbs", mood:"Nostalgic & Comforting", difficulty:"Easy", why:"Bubbly, cheesy comfort food loved by kids and adults alike.", mainBase:"Pasta", image:"images/baked-mac-and-cheese.png", description:"Tender macaroni gets folded into a velvety cheddar cheese sauce, then topped with a layer of buttery breadcrumbs and baked until golden and bubbling at the edges. The contrast between the crunchy top and the creamy interior is what makes this such a beloved comfort classic. It's a guaranteed crowd-pleaser at family dinners, potlucks, and everything in between.",
    ingredientsList:["350g elbow macaroni","3 cups shredded cheddar cheese","2 cups milk","3 tbsp butter","3 tbsp flour","1/2 cup breadcrumbs"],
    steps:["Cook macaroni in salted boiling water until al dente; drain.","Melt butter in a saucepan, whisk in flour, and cook for 1 minute.","Gradually whisk in milk and cook until thickened.","Stir in cheddar cheese until melted, then fold in the cooked macaroni.","Transfer to a baking dish, top with breadcrumbs, and bake at 190°C (375°F) for 20 minutes until golden."] },
  { name:"Spaghetti Carbonara", cuisine:"Italian", ingredients:"Spaghetti, egg, pancetta, pecorino", mood:"Rich & Satisfying", difficulty:"Medium", why:"A silky, no-cream classic that's deceptively simple to make.", mainBase:"Pasta", image:"images/spaghetti-carbonara.png", description:"True carbonara gets its silky sauce not from cream, but from a careful blend of whisked eggs and salty pecorino cheese, tossed with hot pasta and crisped pancetta off the heat. The residual warmth gently cooks the eggs into a glossy, luxurious coating rather than scrambling them. It takes a bit of technique to get the timing right, but the payoff is one of Italy's most iconic and satisfying pasta dishes.",
    ingredientsList:["350g spaghetti","150g pancetta, diced","3 large eggs","1 cup grated pecorino","2 cloves garlic","black pepper, freshly cracked"],
    steps:["Cook spaghetti in salted boiling water until al dente; reserve 1/2 cup pasta water and drain.","Crisp the pancetta in a pan with garlic until golden; discard garlic.","Whisk eggs with pecorino and a generous amount of black pepper in a bowl.","Off the heat, toss the hot spaghetti with the pancetta, then quickly mix in the egg mixture, adding pasta water to create a silky sauce.","Serve immediately with extra pecorino and pepper on top."] },
  { name:"Lemon Ricotta Pasta", cuisine:"Italian", ingredients:"Pasta, ricotta, lemon zest, parmesan", mood:"Bright & Refreshing", difficulty:"Easy", why:"A light pasta dish that feels fancy but takes minutes.", mainBase:"Pasta", image:"images/lemon-ricotta-pasta.png", description:"Creamy ricotta melts into hot pasta water to create an effortlessly smooth sauce, while freshly grated lemon zest cuts through the richness with a bright, sunny lift. A shower of parmesan on top adds a savory finishing touch. It feels like a dish you'd get at a charming little trattoria, yet it comes together with barely any effort on a weeknight.",
    ingredientsList:["350g pasta (spaghetti or penne)","1 cup ricotta cheese","1 lemon, zested and juiced","1/2 cup grated parmesan","2 tbsp olive oil","fresh basil, torn"],
    steps:["Cook pasta in salted boiling water until al dente; reserve 1/2 cup pasta water and drain.","Whisk ricotta with a splash of pasta water until smooth and creamy.","Toss the hot pasta with the ricotta mixture, olive oil, lemon zest, and juice.","Fold in grated parmesan until well combined.","Garnish with fresh basil before serving."] },
  { name:"Cold Sesame Pasta Salad", cuisine:"Asian Fusion", ingredients:"Pasta, sesame sauce, cucumber, scallion", mood:"Cool & Refreshing", difficulty:"Easy", why:"The perfect make-ahead lunch for hot summer days.", mainBase:"Pasta", image:"images/cold-sesame-pasta-salad.png", description:"Chilled noodles are coated in a nutty, savory-sweet sesame dressing and tossed with crisp cucumber and sharp scallions for a refreshing crunch in every bite. Because it's served cold, it's an ideal make-ahead dish that only gets better as the flavors mingle in the fridge. It's a favorite for hot summer days, packed lunches, and potlucks alike.",
    ingredientsList:["350g spaghetti or soba noodles","3 tbsp sesame paste (or peanut butter)","2 tbsp soy sauce","1 tbsp rice vinegar","1 tsp sesame oil","1 cucumber, julienned","2 scallions, sliced","1 tbsp toasted sesame seeds"],
    steps:["Cook noodles according to package instructions, then rinse under cold water and drain well.","Whisk together sesame paste, soy sauce, rice vinegar, and sesame oil to make the dressing.","Toss the cold noodles with the dressing until evenly coated.","Add julienned cucumber and sliced scallions, tossing again to combine.","Chill for at least 30 minutes and garnish with toasted sesame seeds before serving."] },

  { name:"Creamy Mushroom Tagliatelle", cuisine:"Italian", ingredients:"Tagliatelle, mushrooms, cream, parmesan", mood:"Earthy & Comforting", difficulty:"Easy", why:"Silky pasta with deep mushroom flavor and a cozy bistro feel.", mainBase:"Pasta", image:"images/creamy-mushroom-tagliatelle.png", description:"Wide ribbons of tagliatelle are tossed in a creamy mushroom sauce that clings to every strand. Sauteed mushrooms bring earthy depth, parmesan adds savory richness, and parsley keeps the dish bright. It feels elegant but comes together with weeknight-friendly ingredients.",
    ingredientsList:["350g tagliatelle","300g mushrooms, sliced","3 cloves garlic, minced","1 cup cream","1/2 cup grated parmesan","2 tbsp butter","fresh parsley, chopped","salt and black pepper to taste"],
    steps:["Cook tagliatelle in salted boiling water until al dente; reserve 1/2 cup pasta water.","Saute mushrooms in butter until browned and tender.","Add garlic and cook briefly until fragrant.","Pour in cream, stir in parmesan, and loosen with pasta water if needed.","Toss with pasta, season, and finish with parsley."] },
  { name:"Roasted Red Pepper Pasta", cuisine:"Italian Fusion", ingredients:"Pasta, roasted red pepper, basil, parmesan", mood:"Bright & Creamy", difficulty:"Easy", why:"A colorful pasta sauce that tastes rich without feeling heavy.", mainBase:"Pasta", image:"images/roasted-red-pepper-pasta.png", description:"Roasted red peppers blend into a smooth, vibrant sauce with garlic, olive oil, and parmesan. The result is creamy, sweet, and gently smoky, coating short pasta beautifully. Fresh basil on top gives it a lively finish that keeps the whole bowl balanced.",
    ingredientsList:["350g rigatoni or penne","2 roasted red peppers","2 cloves garlic","1/2 cup grated parmesan","1/4 cup cream or pasta water","2 tbsp olive oil","fresh basil","salt and black pepper to taste"],
    steps:["Cook pasta in salted boiling water until al dente; reserve some pasta water.","Blend roasted red peppers with garlic, olive oil, parmesan, and cream or pasta water.","Warm the sauce in a skillet over medium heat.","Toss in the cooked pasta until evenly coated.","Finish with basil, black pepper, and extra parmesan."] },
  { name:"Penne Arrabbiata", cuisine:"Italian", ingredients:"Penne, tomato, garlic, chili flakes, basil", mood:"Spicy & Bold", difficulty:"Easy", why:"A punchy tomato pasta with just enough heat to wake up dinner.", mainBase:"Pasta", image:"images/penne-arrabbiata.webp", description:"Penne arrabbiata is simple, fiery, and deeply satisfying. Garlic and chili flakes bloom in olive oil before tomato sauce simmers into a bold coating for ridged penne. Fresh basil and parmesan round out the heat with a clean bistro finish.",
    ingredientsList:["350g penne","2 cups tomato sauce","3 cloves garlic, sliced","1 tsp chili flakes","2 tbsp olive oil","fresh basil","grated parmesan"],
    steps:["Cook penne in salted boiling water until al dente; reserve some pasta water.","Saute garlic and chili flakes in olive oil until fragrant.","Add tomato sauce and simmer for 10 minutes.","Toss penne with the sauce, adding pasta water as needed.","Finish with basil and parmesan before serving."] },
  { name:"Creamy Cajun Chicken Pasta", cuisine:"American", ingredients:"Penne, chicken, Cajun spice, cream, bell pepper", mood:"Spicy & Creamy", difficulty:"Easy", why:"Smoky spice and cream make a fast, satisfying pasta dinner.", mainBase:"Pasta", image:"images/creamy-cajun-chicken-pasta.webp", description:"This creamy Cajun chicken pasta brings smoky spice, tender chicken, sweet bell pepper, and a velvety parmesan cream sauce together in one pan. It is bold without being heavy and makes a weeknight dinner feel a little more restaurant-worthy.",
    ingredientsList:["350g penne","2 chicken breasts, sliced","1 tbsp Cajun seasoning","1 cup cream","1 bell pepper, sliced","1/2 cup grated parmesan","2 tbsp olive oil"],
    steps:["Season chicken with Cajun spice and sear until cooked through.","Saute bell pepper in the same pan until softened.","Pour in cream and simmer gently.","Stir in parmesan until smooth.","Toss with cooked penne and sliced chicken before serving."] },
  { name:"Chicken Pesto Pasta", cuisine:"Italian Inspired", ingredients:"Fusilli, chicken, pesto, cherry tomatoes, pine nuts", mood:"Fresh & Herby", difficulty:"Easy", why:"Bright basil pesto turns simple chicken pasta into something lively.", mainBase:"Pasta", image:"images/chicken-pesto-pasta.webp", description:"Chicken pesto pasta is fresh, fragrant, and dependable. Fusilli catches the basil pesto in every curve, while grilled chicken adds protein and cherry tomatoes bring juicy sweetness. Toasted pine nuts and parmesan finish it with a gentle crunch.",
    ingredientsList:["350g fusilli","1 grilled chicken breast, sliced","1/2 cup basil pesto","1 cup cherry tomatoes, halved","2 tbsp pine nuts","grated parmesan"],
    steps:["Cook fusilli until al dente and reserve a little pasta water.","Toss hot pasta with pesto, loosening with pasta water if needed.","Fold in sliced grilled chicken and cherry tomatoes.","Toast pine nuts briefly in a dry pan.","Serve with pine nuts and parmesan on top."] },
  { name:"Seafood Marinara Linguine", cuisine:"Italian", ingredients:"Linguine, shrimp, mussels, calamari, marinara", mood:"Briny & Elegant", difficulty:"Medium", why:"A generous seafood pasta that feels like a coastal bistro meal.", mainBase:"Pasta", image:"images/seafood-marinara-linguine.webp", description:"Seafood marinara linguine layers shrimp, mussels, and calamari into a bright tomato sauce with garlic and parsley. The pasta soaks up the briny sauce without feeling too rich, making it a polished dinner for seafood lovers.",
    ingredientsList:["350g linguine","250g shrimp","200g mussels","150g calamari rings","2 cups marinara sauce","2 cloves garlic, minced","fresh parsley"],
    steps:["Cook linguine until al dente and reserve pasta water.","Saute garlic in olive oil until fragrant.","Add marinara and bring to a gentle simmer.","Add seafood and cook until shrimp are pink and mussels open.","Toss with linguine and finish with parsley."] },
  { name:"Pasta Primavera", cuisine:"Italian-American", ingredients:"Farfalle, zucchini, tomatoes, asparagus, peas", mood:"Colorful & Fresh", difficulty:"Easy", why:"Crisp vegetables make pasta feel light, bright, and seasonal.", mainBase:"Pasta", image:"images/pasta-primavera.webp", description:"Pasta primavera keeps dinner colorful with tender-crisp vegetables, olive oil, parmesan, and bright herbs. Farfalle catches little pieces of zucchini, tomato, asparagus, and peas, creating a bowl that feels generous but still fresh.",
    ingredientsList:["350g farfalle","1 zucchini, sliced","1 cup cherry tomatoes","1 cup asparagus pieces","1/2 cup peas","2 tbsp olive oil","grated parmesan"],
    steps:["Cook farfalle until al dente.","Saute zucchini and asparagus in olive oil until just tender.","Add tomatoes and peas and cook briefly.","Toss vegetables with pasta and a splash of pasta water.","Serve with parmesan and black pepper."] },
  { name:"Spinach Artichoke Pasta", cuisine:"American", ingredients:"Rigatoni, spinach, artichokes, garlic, parmesan", mood:"Creamy & Cozy", difficulty:"Easy", why:"It has the comfort of spinach artichoke dip in pasta form.", mainBase:"Pasta", image:"images/spinach-artichoke-pasta.webp", description:"Spinach artichoke pasta turns a beloved dip flavor into a full dinner. Rigatoni is coated in a creamy garlic parmesan sauce with tender spinach and artichoke hearts. It is cozy, green, and satisfyingly savory.",
    ingredientsList:["350g rigatoni","1 cup artichoke hearts","3 cups spinach","1 cup cream cheese or cream","1/2 cup grated parmesan","2 cloves garlic, minced"],
    steps:["Cook rigatoni until al dente and reserve pasta water.","Saute garlic, then add artichoke hearts and spinach.","Stir in cream cheese or cream until smooth.","Add parmesan and loosen with pasta water.","Toss with rigatoni and season to taste."] },
  { name:"Beef Stroganoff Pasta", cuisine:"Russian Inspired", ingredients:"Egg noodles, beef, mushrooms, onion, sour cream", mood:"Savory & Comforting", difficulty:"Medium", why:"Tender beef and mushrooms make a rich, cozy pasta bowl.", mainBase:"Pasta", image:"images/beef-stroganoff-pasta.webp", description:"Beef stroganoff pasta pairs tender beef strips and browned mushrooms with a tangy sour cream sauce. Egg noodles make it hearty and familiar, while parsley keeps the finish fresh. It is comfort food with a polished dinner-table feel.",
    ingredientsList:["350g egg noodles","300g beef strips","250g mushrooms, sliced","1 onion, sliced","1 cup sour cream","1 cup beef broth","fresh parsley"],
    steps:["Cook egg noodles until tender and drain.","Sear beef strips quickly and set aside.","Saute onion and mushrooms until browned.","Add broth and simmer, then stir in sour cream off the heat.","Return beef to the pan and toss with noodles and parsley."] },
  { name:"Cacio e Pepe", cuisine:"Italian", ingredients:"Spaghetti, pecorino, black pepper", mood:"Minimal & Silky", difficulty:"Medium", why:"Three core ingredients create a beautifully glossy Roman classic.", mainBase:"Pasta", image:"images/cacio-e-pepe.webp", description:"Cacio e pepe proves how elegant simple cooking can be. Pecorino, black pepper, and starchy pasta water transform into a glossy sauce that clings to spaghetti. The key is patience, heat control, and a generous hand with pepper.",
    ingredientsList:["350g spaghetti","1 cup finely grated pecorino","2 tsp freshly cracked black pepper","salt","reserved pasta water"],
    steps:["Cook spaghetti in lightly salted water until al dente.","Toast black pepper in a dry skillet until fragrant.","Add a splash of pasta water to the skillet.","Toss pasta with pepper water, then add pecorino off the heat.","Stir until glossy, adding pasta water a little at a time."] },
  { name:"Sun-Dried Tomato Orzo", cuisine:"Mediterranean Inspired", ingredients:"Orzo, sun-dried tomatoes, spinach, cream, parmesan", mood:"Creamy & Bright", difficulty:"Easy", why:"Tiny orzo pasta turns creamy sauce into a spoonable comfort bowl.", mainBase:"Pasta", image:"images/sun-dried-tomato-orzo.webp", description:"Sun-dried tomato orzo is creamy, colorful, and quick. The orzo cooks into a tender base that carries sweet-tangy tomatoes, spinach, basil, and parmesan. It works as a cozy main or a rich side for grilled chicken or seafood.",
    ingredientsList:["350g orzo","1/2 cup sun-dried tomatoes, chopped","2 cups spinach","1/2 cup cream","1/2 cup grated parmesan","2 cloves garlic, minced","fresh basil"],
    steps:["Cook orzo until tender and reserve a little cooking water.","Saute garlic and sun-dried tomatoes until fragrant.","Add cream and parmesan, stirring until smooth.","Fold in spinach until wilted.","Toss with orzo and finish with basil."] },
  { name:"Sausage and Kale Orecchiette", cuisine:"Italian", ingredients:"Orecchiette, sausage, kale, garlic, chili flakes", mood:"Rustic & Savory", difficulty:"Easy", why:"The little pasta cups catch sausage, greens, and parmesan perfectly.", mainBase:"Pasta", image:"images/sausage-kale-orecchiette.webp", description:"Sausage and kale orecchiette is rustic, hearty, and balanced. The pasta's little cup shape catches browned sausage, garlicky greens, chili flakes, and parmesan in every bite. It is a cozy one-pan style pasta with plenty of texture.",
    ingredientsList:["350g orecchiette","250g Italian sausage","3 cups chopped kale","2 cloves garlic, minced","1/2 tsp chili flakes","grated parmesan"],
    steps:["Cook orecchiette until al dente and reserve pasta water.","Brown sausage in a skillet, breaking it into small pieces.","Add garlic and chili flakes and cook briefly.","Stir in kale until wilted.","Toss with pasta, pasta water, and parmesan."] },
  { name:"Lasagna Roll-Ups", cuisine:"Italian-American", ingredients:"Lasagna sheets, ricotta, spinach, marinara, mozzarella", mood:"Cheesy & Shareable", difficulty:"Medium", why:"Individual rolls make lasagna easier to serve and fun to plate.", mainBase:"Pasta", image:"images/lasagna-roll-ups.webp", description:"Lasagna roll-ups turn classic lasagna into tidy, generous portions. Each pasta sheet is filled with ricotta and spinach, rolled into marinara, topped with mozzarella, and baked until bubbling. They are comforting, cheerful, and easy to share.",
    ingredientsList:["10 lasagna sheets","1.5 cups ricotta","2 cups spinach, chopped","2 cups marinara sauce","1 cup mozzarella","1 egg","fresh basil"],
    steps:["Cook lasagna sheets until pliable and drain.","Mix ricotta, spinach, egg, and a pinch of salt.","Spread filling on each sheet and roll tightly.","Place rolls in marinara, top with mozzarella, and bake until bubbly.","Garnish with basil before serving."] },
  { name:"Greek Orzo Pasta", cuisine:"Greek Inspired", ingredients:"Orzo, feta, olives, cucumber, tomatoes", mood:"Fresh & Tangy", difficulty:"Easy", why:"A bright pasta bowl with crunchy vegetables and salty feta.", mainBase:"Pasta", image:"images/greek-orzo-pasta.webp", description:"Greek orzo pasta is fresh, tangy, and colorful. Tender orzo is tossed with cucumber, cherry tomatoes, olives, feta, herbs, lemon, and olive oil. It is lovely chilled for lunch or served at room temperature beside grilled mains.",
    ingredientsList:["350g orzo","1 cup cherry tomatoes, halved","1 cucumber, diced","1/2 cup feta cubes","1/3 cup olives","1 lemon, juiced","2 tbsp olive oil","fresh parsley"],
    steps:["Cook orzo until tender, then rinse briefly and drain.","Toss orzo with lemon juice and olive oil.","Fold in tomatoes, cucumber, olives, and feta.","Season with salt, pepper, and parsley.","Serve chilled or at room temperature."] },
  { name:"Truffle Mushroom Gnocchi", cuisine:"Italian Inspired", ingredients:"Gnocchi, mushrooms, cream, parmesan, truffle oil", mood:"Earthy & Luxurious", difficulty:"Easy", why:"Soft gnocchi and mushrooms create a cozy restaurant-style bowl.", mainBase:"Pasta", image:"images/truffle-mushroom-gnocchi.webp", description:"Truffle mushroom gnocchi feels plush without being difficult. Pillowy gnocchi are folded through creamy mushrooms, parmesan, parsley, and a tiny drizzle of truffle oil. The result is earthy, aromatic, and deeply comforting.",
    ingredientsList:["500g gnocchi","300g mushrooms, sliced","1/2 cup cream","1/2 cup grated parmesan","1 tsp truffle oil","2 tbsp butter","fresh parsley"],
    steps:["Cook gnocchi until they float, then drain.","Saute mushrooms in butter until browned.","Add cream and simmer gently.","Stir in parmesan and toss with gnocchi.","Finish with truffle oil and parsley."] },
  { name:"Roasted Vegetable Lasagna", cuisine:"Italian", ingredients:"Lasagna sheets, roasted vegetables, marinara, ricotta", mood:"Layered & Hearty", difficulty:"Medium", why:"Roasted vegetables bring sweetness and depth to classic lasagna.", mainBase:"Pasta", image:"images/roasted-vegetable-lasagna.webp", description:"Roasted vegetable lasagna is rich, colorful, and satisfying. Layers of pasta, marinara, ricotta, mozzarella, zucchini, eggplant, and peppers bake into a bubbling tray with sweet roasted flavor in every slice.",
    ingredientsList:["9 lasagna sheets","2 cups roasted vegetables","2 cups marinara sauce","1.5 cups ricotta","1 cup mozzarella","1/2 cup parmesan","fresh basil"],
    steps:["Cook lasagna sheets until just pliable.","Spread marinara in a baking dish.","Layer pasta, ricotta, roasted vegetables, mozzarella, and sauce.","Repeat layers and finish with parmesan.","Bake until bubbling and golden, then rest before slicing."] },
  { name:"Lemon Asparagus Pasta", cuisine:"Italian Inspired", ingredients:"Linguine, asparagus, lemon, parmesan, garlic", mood:"Bright & Springy", difficulty:"Easy", why:"Lemon and asparagus make pasta feel fresh, clean, and lively.", mainBase:"Pasta", image:"images/lemon-asparagus-pasta.webp", description:"Lemon asparagus pasta is light, fragrant, and cheerful. Linguine is tossed with crisp asparagus, garlic olive oil, lemon zest, parmesan, and parsley. It is quick enough for lunch but polished enough for a relaxed dinner.",
    ingredientsList:["350g linguine","1 bunch asparagus, cut into pieces","1 lemon, zested and juiced","1/2 cup grated parmesan","2 tbsp olive oil","2 cloves garlic, minced","fresh parsley"],
    steps:["Cook linguine until al dente, adding asparagus during the last 2 minutes.","Reserve pasta water, then drain pasta and asparagus.","Saute garlic in olive oil until fragrant.","Toss pasta with garlic oil, lemon zest, lemon juice, and parmesan.","Loosen with pasta water and finish with parsley."] },
  // ---------------- BREAD ----------------
  { name:"Avocado Toast", cuisine:"American", ingredients:"Sourdough bread, avocado, egg, chili flakes", mood:"Fresh & Energizing", difficulty:"Easy", why:"A trendy breakfast that's ready in just 5 minutes.", mainBase:"Bread", image:"images/avocado-toast.png", description:"Thick slices of crusty sourdough are toasted until golden, then piled high with mashed avocado seasoned simply with salt, lime, and a pinch of chili flakes for gentle heat. A perfectly cooked egg on top adds protein and a rich, runny finish that ties the whole thing together. It looks impressive with almost no effort, making it the ultimate quick breakfast for busy mornings.",
    ingredientsList:["2 slices sourdough bread","1 ripe avocado","1 egg","1/2 lime, juiced","1/4 tsp chili flakes","salt to taste"],
    steps:["Toast the sourdough slices until golden and crisp.","Mash the avocado with lime juice and a pinch of salt.","Fry or poach the egg to your preference.","Spread the mashed avocado generously over the toast.","Top with the egg and sprinkle with chili flakes before serving."] },
  { name:"Garlic Bread", cuisine:"Italian-American", ingredients:"Baguette, butter, garlic, parsley", mood:"Warm & Buttery", difficulty:"Easy", why:"The perfect crispy side for any pasta night.", mainBase:"Bread", image:"images/garlic-bread.png", description:"Slices of baguette are brushed with a fragrant mix of melted butter, minced garlic, and fresh parsley, then toasted until the edges turn deeply golden and crisp. The garlicky aroma alone is enough to make everyone gather in the kitchen before dinner is even served. It's the classic finishing touch to any pasta night, perfect for mopping up extra sauce.",
    ingredientsList:["1 baguette, halved lengthwise","4 tbsp butter, softened","4 cloves garlic, minced","2 tbsp fresh parsley, chopped"],
    steps:["Preheat the oven to 200°C (400°F).","Mix softened butter with minced garlic and chopped parsley.","Spread the garlic butter evenly over the cut sides of the baguette.","Bake for 8-10 minutes until the edges turn golden and crisp.","Slice and serve warm."] },
  { name:"Grilled Cheese Sandwich", cuisine:"American", ingredients:"Bread, cheddar, butter", mood:"Nostalgic & Comforting", difficulty:"Easy", why:"A classic comfort food that never goes out of style.", mainBase:"Bread", image:"images/grilled-cheese-sandwich.png", description:"There's something timeless about the combination of buttery, golden-crisp bread and a gooey center of melted cheddar cheese. Cooked low and slow in a pan, the outside develops a satisfying crunch while the inside turns perfectly stretchy and melty. It's the kind of nostalgic, no-fuss comfort food that never fails to hit the spot, whatever the occasion.",
    ingredientsList:["2 slices white or sandwich bread","2 slices cheddar cheese","2 tbsp butter, softened"],
    steps:["Butter one side of each bread slice.","Place cheese between the slices with the buttered sides facing out.","Cook in a skillet over medium-low heat for 3-4 minutes per side.","Press gently with a spatula until the cheese melts and the bread turns golden.","Slice diagonally and serve hot."] },
  { name:"French Toast", cuisine:"French-American", ingredients:"Bread, egg, milk, cinnamon", mood:"Sweet & Cozy", difficulty:"Easy", why:"A weekend breakfast treat the whole family will ask for again.", mainBase:"Bread", image:"images/french-toast.png", description:"Thick slices of bread are soaked in a cinnamon-spiced custard of eggs and milk, then pan-fried until the outside turns golden and slightly crisp while the inside stays soft and custardy. It's a wonderful way to use up slightly stale bread, transforming it into a warm, sweet weekend treat. Served with a drizzle of syrup, it's the kind of breakfast that gets requested again and again.",
    ingredientsList:["4 thick slices bread (slightly stale)","2 eggs","1/2 cup milk","1/2 tsp cinnamon","1 tbsp butter, for frying","maple syrup, to serve"],
    steps:["Whisk together eggs, milk, and cinnamon in a shallow dish.","Dip each bread slice into the mixture, soaking both sides briefly.","Melt butter in a skillet over medium heat.","Fry the soaked bread for 2-3 minutes per side until golden.","Serve warm with a drizzle of maple syrup."] },
  { name:"Bruschetta", cuisine:"Italian", ingredients:"Baguette, tomato, basil, olive oil", mood:"Light & Summery", difficulty:"Easy", why:"A fresh, colorful appetizer that's ready in minutes.", mainBase:"Bread", image:"images/bruschetta.png", description:"Crisp toasted baguette slices are topped with a simple, vibrant mix of diced ripe tomatoes, fresh basil, and a generous drizzle of good olive oil. The combination of crunchy bread and juicy, herby topping makes this a light, refreshing starter that requires almost no cooking. It's an easy way to bring a taste of Italian summer to any table in just a few minutes.",
    ingredientsList:["1 baguette, sliced","3 ripe tomatoes, diced","handful of fresh basil, chopped","2 tbsp olive oil","1 clove garlic","salt and pepper to taste"],
    steps:["Toast the baguette slices until golden and crisp.","Rub each toasted slice lightly with the cut side of a garlic clove.","Mix diced tomatoes, basil, and olive oil in a bowl; season with salt and pepper.","Spoon the tomato mixture generously onto each toast.","Serve immediately while the bread is still crisp."] },
  { name:"Banana Bread", cuisine:"American", ingredients:"Flour, banana, sugar, walnuts", mood:"Sweet & Homely", difficulty:"Easy", why:"The best way to use up overripe bananas.", mainBase:"Bread", image:"images/banana-bread.png", description:"Overripe, spotty bananas are mashed and folded into a simple batter along with crunchy walnuts, creating a loaf that's naturally sweet, moist, and full of flavor. It fills the whole kitchen with a warm, homey aroma while it bakes, making it feel like an instant act of comfort. Sliced and served plain or with a little butter, it's just as good for breakfast as it is for an afternoon snack.",
    ingredientsList:["3 overripe bananas, mashed","1 3/4 cups flour","3/4 cup sugar","1/3 cup melted butter","2 eggs","1 tsp baking soda","1/2 cup chopped walnuts"],
    steps:["Preheat the oven to 175°C (350°F) and grease a loaf pan.","Mix mashed bananas with melted butter, sugar, and eggs.","Stir in flour and baking soda until just combined.","Fold in the chopped walnuts.","Pour into the loaf pan and bake for 55-60 minutes until a toothpick comes out clean."] },
  { name:"Naan Pizza", cuisine:"Indian Fusion", ingredients:"Naan bread, tomato sauce, cheese, toppings", mood:"Fun & Quick", difficulty:"Easy", why:"A speedy pizza night hack using naan as the crust.", mainBase:"Bread", image:"images/naan-pizza.png", description:"Soft, pillowy naan bread makes a surprisingly great shortcut pizza crust — no dough-making or rising time required. Simply spread on some tomato sauce, scatter over your favorite cheese and toppings, and bake until melty and slightly crisp at the edges. It's a fun, fast way to satisfy a pizza craving on a busy weeknight, and endlessly customizable for picky eaters.",
    ingredientsList:["2 pieces naan bread","1/2 cup tomato sauce","1 cup shredded mozzarella","toppings of choice (pepperoni, peppers, olives)"],
    steps:["Preheat the oven to 220°C (425°F).","Place naan bread on a baking tray and spread tomato sauce evenly over each piece.","Sprinkle shredded mozzarella over the sauce.","Add your favorite toppings.","Bake for 8-10 minutes until the cheese is melted and bubbly."] },
  { name:"Egg Sandwich", cuisine:"American", ingredients:"Bread, egg, mayo, lettuce", mood:"Simple & Filling", difficulty:"Easy", why:"A protein-packed sandwich perfect for busy mornings.", mainBase:"Bread", image:"images/egg-sandwich.png", description:"Soft-cooked eggs are gently folded with a touch of creamy mayo and piled between slices of soft bread with a layer of crisp lettuce for crunch. It's a simple, satisfying sandwich that comes together in minutes but keeps you full for hours thanks to the protein-rich filling. Perfect wrapped up for a grab-and-go breakfast or a quick lunchbox addition.",
    ingredientsList:["4 slices soft bread","3 eggs, hard-boiled","2 tbsp mayonnaise","a few lettuce leaves","salt and pepper to taste"],
    steps:["Boil the eggs until hard-boiled, then peel and chop them.","Mix chopped eggs with mayonnaise, salt, and pepper.","Lay out the bread slices and top two of them with lettuce leaves.","Spoon the egg mixture evenly over the lettuce.","Top with the remaining bread slices, cut in half, and serve."] },

  { name:"Shakshuka Flatbread", cuisine:"Middle Eastern Fusion", ingredients:"Flatbread, tomato, egg, peppers, feta", mood:"Brunchy & Bold", difficulty:"Easy", why:"A fun flatbread twist on saucy shakshuka flavors.", mainBase:"Bread", image:"images/shakshuka-flatbread.png", description:"This flatbread turns the warm tomato-pepper flavors of shakshuka into a crisp, shareable meal. A soft egg sits in the center, feta adds salty creaminess, and fresh herbs brighten the rich sauce. It is perfect for brunch, lunch, or a quick dinner with a salad.",
    ingredientsList:["2 flatbreads","1 cup tomato pepper sauce","2 eggs","1/3 cup crumbled feta","1 tbsp olive oil","fresh parsley or cilantro","1/2 tsp cumin","pinch of chili flakes"],
    steps:["Preheat the oven to 220C (425F).","Spread tomato pepper sauce over each flatbread and sprinkle with cumin.","Crack an egg onto the center of each flatbread.","Bake for 8-10 minutes until the flatbread is crisp and the egg is just set.","Top with feta, herbs, chili flakes, and a drizzle of olive oil."] },
  { name:"Turkey Club Sandwich", cuisine:"American", ingredients:"Bread, turkey, bacon, lettuce, tomato", mood:"Classic & Filling", difficulty:"Easy", why:"A stacked sandwich with crisp toast and satisfying layers.", mainBase:"Bread", image:"images/turkey-club-sandwich.png", description:"The turkey club is a deli classic for good reason: toasted bread, tender turkey, crisp lettuce, juicy tomato, and smoky bacon all stack into one satisfying bite. A thin layer of mayo keeps everything creamy without weighing it down. Cut diagonally, it is lunchbox-friendly and instantly familiar.",
    ingredientsList:["3 slices sandwich bread, toasted","120g sliced turkey","2 strips cooked bacon","2 lettuce leaves","1 tomato, sliced","2 tbsp mayonnaise","salt and black pepper to taste"],
    steps:["Toast the bread until golden and crisp.","Spread mayonnaise lightly over each slice.","Layer turkey, lettuce, tomato, and bacon between the slices.","Season tomato with a pinch of salt and pepper.","Cut the sandwich diagonally and serve immediately."] },
  { name:"Tomato Basil Bruschetta", cuisine:"Italian", ingredients:"Baguette, tomato, basil, garlic, balsamic", mood:"Fresh & Crisp", difficulty:"Easy", why:"Juicy tomatoes and crunchy toast make a bright starter or snack.", mainBase:"Bread", image:"images/tomato-basil-bruschetta.webp", description:"Tomato basil bruschetta is all about contrast: crisp toasted bread, juicy tomatoes, fragrant basil, and a little balsamic sweetness. It is simple, colorful, and perfect when you want something fresh but still satisfying.",
    ingredientsList:["1 small baguette, sliced","2 cups diced tomatoes","2 cloves garlic, minced","1/2 cup fresh basil, chopped","2 tbsp olive oil","1 tbsp balsamic glaze","salt and black pepper to taste"],
    steps:["Toast baguette slices until golden and crisp.","Mix tomatoes, garlic, basil, olive oil, salt, and pepper.","Spoon the tomato mixture over the toast.","Drizzle lightly with balsamic glaze.","Serve immediately while the bread is still crisp."] },
  { name:"Caprese Panini", cuisine:"Italian", ingredients:"Ciabatta, mozzarella, tomato, basil pesto", mood:"Melty & Fresh", difficulty:"Easy", why:"Classic caprese flavors become warm, crisp, and satisfying.", mainBase:"Bread", image:"images/caprese-panini.webp", description:"This caprese panini presses mozzarella, tomato, and basil pesto between crisp ciabatta until the cheese turns soft and melty. The outside gets golden while the inside stays fresh and bright, making it a quick cafe-style meal.",
    ingredientsList:["2 ciabatta rolls","200g fresh mozzarella, sliced","2 tomatoes, sliced","3 tbsp basil pesto","1 tbsp olive oil","fresh basil leaves"],
    steps:["Split ciabatta rolls and spread pesto on the cut sides.","Layer mozzarella, tomato, and basil inside.","Brush the outside lightly with olive oil.","Grill or press until the bread is crisp and the cheese melts.","Slice and serve warm."] },
  { name:"Smoked Salmon Bagel", cuisine:"American", ingredients:"Bagel, smoked salmon, cream cheese, capers", mood:"Elegant & Brunchy", difficulty:"Easy", why:"A polished brunch classic with creamy, salty, and fresh flavors.", mainBase:"Bread", image:"images/smoked-salmon-bagel.webp", description:"Smoked salmon bagel brings together tangy cream cheese, silky salmon, capers, red onion, dill, and lemon on a toasted bagel. It feels special enough for brunch but takes only a few minutes to assemble.",
    ingredientsList:["2 everything bagels","4 tbsp cream cheese","120g smoked salmon","2 tbsp capers","1/4 red onion, thinly sliced","fresh dill","lemon wedges"],
    steps:["Toast the bagels until lightly crisp.","Spread cream cheese generously on each half.","Layer smoked salmon over the cream cheese.","Top with capers, red onion, and dill.","Serve with lemon wedges."] },
  { name:"Chicken Shawarma Pita", cuisine:"Middle Eastern Inspired", ingredients:"Pita, chicken, cucumber, tomato, tahini", mood:"Spiced & Fresh", difficulty:"Medium", why:"Warm pita wraps savory chicken and crisp vegetables in every bite.", mainBase:"Bread", image:"images/chicken-shawarma-pita.webp", description:"Chicken shawarma pita is warm, spiced, and fresh at the same time. Juicy chicken strips are tucked into soft pita with cucumber, tomato, lettuce, pickled onion, and tahini sauce for a handheld meal full of texture.",
    ingredientsList:["2 large pita breads","300g chicken strips","1 tsp cumin","1 tsp paprika","1 cucumber, diced","1 tomato, diced","lettuce leaves","2 tbsp tahini sauce"],
    steps:["Season chicken with cumin, paprika, salt, and pepper.","Cook chicken in a hot skillet until browned and cooked through.","Warm pita breads briefly.","Fill pita with lettuce, chicken, cucumber, and tomato.","Drizzle with tahini sauce before serving."] },
  { name:"Hummus Veggie Wrap", cuisine:"Mediterranean Inspired", ingredients:"Tortilla, hummus, roasted peppers, cucumber, spinach", mood:"Fresh & Healthy", difficulty:"Easy", why:"Creamy hummus and crunchy vegetables make lunch feel effortless.", mainBase:"Bread", image:"images/hummus-veggie-wrap.webp", description:"This hummus veggie wrap is colorful, creamy, and easy to pack. Hummus anchors crisp cucumber, roasted peppers, carrots, spinach, and feta inside a soft tortilla, giving every bite a good balance of freshness and comfort.",
    ingredientsList:["2 large tortillas","1/2 cup hummus","1 roasted red pepper, sliced","1 cucumber, cut into sticks","1 carrot, shredded","2 cups spinach","1/3 cup feta crumbles"],
    steps:["Spread hummus over each tortilla.","Layer spinach, roasted pepper, cucumber, carrot, and feta.","Fold in the sides and roll tightly.","Slice each wrap in half.","Serve right away or chill for lunch."] },
  { name:"Cinnamon Raisin Toast", cuisine:"American", ingredients:"Raisin bread, butter, cinnamon, honey", mood:"Cozy & Sweet", difficulty:"Easy", why:"A warm, buttery breakfast with bakery-style comfort.", mainBase:"Bread", image:"images/cinnamon-raisin-toast.webp", description:"Cinnamon raisin toast turns a simple slice of bread into a cozy breakfast. Toasted raisin bread gets a melting layer of cinnamon butter and honey, creating warm spice, sweetness, and crisp edges with almost no effort.",
    ingredientsList:["4 slices raisin bread","3 tbsp butter, softened","1 tsp cinnamon","1 tbsp honey","pinch of salt"],
    steps:["Toast raisin bread until golden.","Mix softened butter with cinnamon, honey, and a pinch of salt.","Spread cinnamon butter over the hot toast.","Drizzle with a little extra honey if desired.","Serve warm."] },
  { name:"Ricotta Honey Toast", cuisine:"Italian Inspired", ingredients:"Sourdough, ricotta, honey, figs, pistachios", mood:"Creamy & Elegant", difficulty:"Easy", why:"Creamy ricotta, fruit, and honey make toast feel refined.", mainBase:"Bread", image:"images/ricotta-honey-toast.webp", description:"Ricotta honey toast is simple but quietly elegant. Thick sourdough is toasted and topped with creamy ricotta, figs, pistachios, lemon zest, and honey for a balance of richness, fruit, crunch, and brightness.",
    ingredientsList:["2 thick slices sourdough","1/2 cup ricotta","2 figs, quartered","2 tbsp pistachios, chopped","1 tbsp honey","1 tsp lemon zest","black pepper to taste"],
    steps:["Toast sourdough until crisp at the edges.","Spread ricotta generously over each slice.","Top with figs and pistachios.","Drizzle with honey.","Finish with lemon zest and a little black pepper."] },
  { name:"Mushroom Swiss Melt", cuisine:"American", ingredients:"Rye bread, mushrooms, Swiss cheese, onion", mood:"Savory & Melty", difficulty:"Easy", why:"Earthy mushrooms and melted cheese make a deeply comforting sandwich.", mainBase:"Bread", image:"images/mushroom-swiss-melt.webp", description:"This mushroom Swiss melt is rich, savory, and wonderfully crisp. Sauteed mushrooms and caramelized onions sit under melted Swiss cheese between toasted rye slices, creating a vegetarian sandwich that feels hearty and bistro-ready.",
    ingredientsList:["4 slices rye bread","250g mushrooms, sliced","1 onion, sliced","4 slices Swiss cheese","2 tbsp butter","1 tsp Dijon mustard","salt and black pepper to taste"],
    steps:["Saute mushrooms and onion in butter until browned.","Spread Dijon on the bread slices.","Layer mushrooms, onions, and Swiss cheese between bread.","Toast in a skillet until both sides are golden.","Slice and serve while the cheese is melted."] },
  { name:"Mediterranean Pita Pockets", cuisine:"Mediterranean", ingredients:"Pita, falafel, cucumber, tomato, tzatziki", mood:"Fresh & Filling", difficulty:"Easy", why:"Soft pita pockets make crisp vegetables and falafel easy to love.", mainBase:"Bread", image:"images/mediterranean-pita-pockets.webp", description:"Mediterranean pita pockets are quick, colorful, and satisfying. Warm pita halves hold falafel, cucumber, tomato, lettuce, onion, herbs, and a cooling tzatziki sauce for a fresh handheld meal.",
    ingredientsList:["2 pita breads, halved","6 falafel balls","1 cucumber, sliced","1 tomato, chopped","lettuce leaves","1/4 red onion, sliced","1/2 cup tzatziki","fresh parsley"],
    steps:["Warm pita halves until soft.","Heat falafel according to package directions or pan-fry until crisp.","Fill pita pockets with lettuce, falafel, cucumber, tomato, and onion.","Spoon tzatziki over the filling.","Garnish with parsley and serve."] },
  { name:"Rosemary Focaccia Sandwich", cuisine:"Italian", ingredients:"Focaccia, prosciutto, mozzarella, arugula, peppers", mood:"Rustic & Savory", difficulty:"Easy", why:"Herby focaccia turns simple fillings into a generous bistro sandwich.", mainBase:"Bread", image:"images/rosemary-focaccia-sandwich.webp", description:"Rosemary focaccia sandwich layers salty prosciutto, creamy mozzarella, roasted peppers, and peppery arugula inside tender, olive-oil-rich bread. It is rustic, fragrant, and easy to slice for lunch or a casual dinner.",
    ingredientsList:["1 rosemary focaccia slab","120g prosciutto","200g fresh mozzarella","1/2 cup roasted peppers","1 cup arugula","1 tbsp olive oil","black pepper"],
    steps:["Slice focaccia horizontally.","Layer mozzarella, roasted peppers, prosciutto, and arugula.","Drizzle with olive oil and season with black pepper.","Close the sandwich and press gently.","Cut into portions and serve."] },
  { name:"Croque Monsieur", cuisine:"French", ingredients:"Bread, ham, gruyere, bechamel", mood:"Golden & Indulgent", difficulty:"Medium", why:"A classic French cafe sandwich with bubbly cheese and creamy sauce.", mainBase:"Bread", image:"images/croque-monsieur.webp", description:"Croque monsieur is a deeply satisfying French cafe classic. Ham and gruyere are layered between bread, topped with bechamel and more cheese, then baked or broiled until golden, bubbling, and crisp around the edges.",
    ingredientsList:["4 slices sandwich bread","4 slices ham","1 cup grated gruyere","1/2 cup bechamel sauce","1 tbsp Dijon mustard","1 tbsp butter"],
    steps:["Spread Dijon on the bread slices.","Layer ham and gruyere between the slices.","Butter the outside and toast lightly in a pan.","Spread bechamel on top and sprinkle with more gruyere.","Broil until bubbling and golden."] },
  { name:"Pesto Mozzarella Ciabatta", cuisine:"Italian Inspired", ingredients:"Ciabatta, pesto, mozzarella, roasted tomatoes, arugula", mood:"Fresh & Savory", difficulty:"Easy", why:"Soft mozzarella and pesto make a bright, satisfying sandwich.", mainBase:"Bread", image:"images/pesto-mozzarella-ciabatta.webp", description:"Pesto mozzarella ciabatta is fresh, creamy, and full of basil aroma. Crisp ciabatta holds pesto, mozzarella, roasted tomatoes, and arugula for a sandwich that tastes like a sunny Italian lunch.",
    ingredientsList:["2 ciabatta rolls","4 tbsp basil pesto","200g fresh mozzarella","1/2 cup roasted tomatoes","1 cup arugula","1 tbsp olive oil"],
    steps:["Split and lightly toast the ciabatta rolls.","Spread pesto on both cut sides.","Layer mozzarella, roasted tomatoes, and arugula.","Drizzle with olive oil.","Close, slice, and serve."] },
  { name:"Breakfast Bagel Sandwich", cuisine:"American", ingredients:"Bagel, egg, bacon, cheddar, avocado", mood:"Hearty & Energizing", difficulty:"Easy", why:"A full breakfast tucked into one warm, satisfying bagel.", mainBase:"Bread", image:"images/breakfast-bagel-sandwich.webp", description:"Breakfast bagel sandwich stacks fluffy egg, crisp bacon, cheddar, and avocado inside a toasted bagel. It is filling, cheerful, and perfect when you want a brunch-style breakfast without a long prep list.",
    ingredientsList:["2 sesame bagels","3 eggs, scrambled","4 slices bacon","2 slices cheddar","1 avocado, sliced","1 tbsp butter","salt and black pepper to taste"],
    steps:["Toast bagels until lightly crisp.","Cook bacon until crisp and drain.","Scramble eggs gently with butter, salt, and pepper.","Layer cheddar, eggs, bacon, and avocado on each bagel.","Close sandwiches and serve warm."] },
  { name:"Pulled Pork Sliders", cuisine:"American", ingredients:"Brioche buns, pulled pork, coleslaw, pickles", mood:"Saucy & Shareable", difficulty:"Easy", why:"Mini buns make smoky pulled pork easy to serve and fun to eat.", mainBase:"Bread", image:"images/pulled-pork-sliders.webp", description:"Pulled pork sliders are saucy, soft, and crowd-friendly. Tender pork is tucked into mini brioche buns with coleslaw, pickles, and barbecue sauce for a sweet, tangy, and smoky bite.",
    ingredientsList:["6 slider buns","2 cups cooked pulled pork","1/2 cup barbecue sauce","1 cup coleslaw","pickle slices","1 tbsp butter"],
    steps:["Warm pulled pork with barbecue sauce.","Toast slider buns lightly with butter.","Pile pulled pork onto each bun.","Top with coleslaw and pickles.","Close buns and serve warm."] },
  { name:"Spinach Feta Flatbread", cuisine:"Mediterranean Inspired", ingredients:"Flatbread, spinach, feta, olives, roasted peppers", mood:"Bright & Savory", difficulty:"Easy", why:"A crisp flatbread with salty cheese, greens, and Mediterranean color.", mainBase:"Bread", image:"images/spinach-feta-flatbread.webp", description:"Spinach feta flatbread is crisp, colorful, and quick to bake. Warm flatbread is topped with spinach, feta, roasted peppers, olives, and herbs, giving you pizza-like comfort with a fresher Mediterranean feel.",
    ingredientsList:["2 flatbreads","2 cups spinach","1/2 cup feta crumbles","1/2 cup roasted red peppers","1/3 cup olives, sliced","1 tbsp olive oil","dried oregano"],
    steps:["Preheat oven to 220C (425F).","Brush flatbreads with olive oil.","Top with spinach, feta, roasted peppers, olives, and oregano.","Bake for 8-10 minutes until edges are crisp.","Slice and serve warm."] },
  // ---------------- NOODLES ----------------
  { name:"Pad Thai", cuisine:"Thai", ingredients:"Rice noodles, shrimp, egg, peanuts, tamarind", mood:"Tangy & Exciting", difficulty:"Medium", why:"Sweet, sour, and savory noodles that taste like street food magic.", mainBase:"Noodles", image:"images/pad-thai.png", description:"Pad Thai is a beloved Thai street food classic built around a bold balance of sweet, sour, and savory flavors from tangy tamarind, fish sauce, and a touch of sugar. Chewy rice noodles are stir-fried quickly with shrimp and scrambled egg, then finished with crushed peanuts and a squeeze of lime for extra brightness. The whole dish comes together fast over high heat, capturing that irresistible smoky flavor found at Bangkok's busiest food stalls.",
    ingredientsList:["200g flat rice noodles","200g shrimp, peeled","2 eggs","3 tbsp tamarind paste","2 tbsp fish sauce","2 tbsp sugar","1/4 cup crushed peanuts","1 lime, cut into wedges","bean sprouts, for garnish"],
    steps:["Soak rice noodles in warm water until softened; drain.","Heat oil in a wok and stir-fry shrimp until pink; push to one side.","Crack eggs into the wok and scramble briefly.","Add drained noodles, tamarind paste, fish sauce, and sugar, tossing everything together over high heat.","Serve topped with crushed peanuts, bean sprouts, and a lime wedge."] },
  { name:"Beef Ramen", cuisine:"Japanese", ingredients:"Ramen noodles, beef, broth, egg, scallion", mood:"Warm & Hearty", difficulty:"Medium", why:"A steaming bowl that instantly feels like comfort in a bowl.", mainBase:"Noodles", image:"images/beef-ramen.png", description:"A deeply savory broth, simmered until rich and full-bodied, forms the soul of this hearty ramen bowl. Tender slices of beef, springy noodles, and a soft-boiled egg with a jammy yolk are layered on top, along with fresh scallions for a pop of color and bite. It's the kind of steaming, slurpable bowl that instantly warms you up on a cold or exhausting day.",
    ingredientsList:["2 portions ramen noodles","4 cups beef or pork broth","200g thinly sliced beef","2 soft-boiled eggs, halved","2 scallions, sliced","2 tbsp soy sauce"],
    steps:["Bring the broth to a simmer and season with soy sauce.","Sear the sliced beef quickly in a hot pan until just cooked.","Cook the ramen noodles according to package instructions; drain.","Divide noodles between bowls and ladle hot broth over the top.","Top with seared beef, a halved soft-boiled egg, and sliced scallions before serving."] },
  { name:"Dan Dan Noodles", cuisine:"Chinese", ingredients:"Noodles, pork, chili oil, sesame paste", mood:"Bold & Spicy", difficulty:"Medium", why:"Spicy, nutty noodles that pack serious flavor in every bite.", mainBase:"Noodles", image:"images/dan-dan-noodles.png", description:"Originating from Sichuan cuisine, these noodles are tossed in a bold sauce built from nutty sesame paste, fiery chili oil, and savory minced pork, creating layers of heat and richness in every bite. The numbing spice from Sichuan peppercorns gives it a distinctive tingling kick that keeps you coming back for more. It's an intensely flavorful dish for anyone who loves noodles with a serious kick.",
    ingredientsList:["250g wheat noodles","150g ground pork","2 tbsp sesame paste","2 tbsp chili oil","1 tsp Sichuan peppercorns, ground","2 tbsp soy sauce","2 scallions, chopped"],
    steps:["Cook noodles in boiling water according to package instructions; drain.","Stir-fry ground pork in a hot pan until browned and crispy.","Whisk together sesame paste, chili oil, soy sauce, and ground Sichuan peppercorns in each serving bowl.","Add the cooked noodles to the bowls and toss with the sauce.","Top with the crispy pork and chopped scallions before serving."] },
  { name:"Chicken Chow Mein", cuisine:"Chinese", ingredients:"Noodles, chicken, cabbage, soy sauce", mood:"Quick & Savory", difficulty:"Easy", why:"A takeout favorite you can make faster (and healthier) at home.", mainBase:"Noodles", image:"images/chicken-chow-mein.png", description:"Springy noodles are stir-fried in a hot wok with tender strips of chicken and crisp cabbage, all coated in a glossy, savory soy-based sauce. The high heat gives the noodles a slightly smoky edge that's hard to replicate any other way. It's a familiar takeout favorite that's actually quicker, fresher, and healthier to make yourself at home.",
    ingredientsList:["250g chow mein noodles","1 chicken breast, sliced thin","2 cups shredded cabbage","1 carrot, julienned","3 tbsp soy sauce","2 tbsp vegetable oil"],
    steps:["Cook the noodles according to package instructions; drain and set aside.","Heat oil in a wok and stir-fry the chicken until cooked through.","Add cabbage and carrot, stir-frying until just tender-crisp.","Add the cooked noodles and soy sauce, tossing everything together over high heat.","Serve hot straight from the wok."] },
  { name:"Vietnamese Pho", cuisine:"Vietnamese", ingredients:"Rice noodles, beef, broth, herbs", mood:"Soothing & Aromatic", difficulty:"Medium", why:"A fragrant noodle soup that warms you from the inside out.", mainBase:"Noodles", image:"images/vietnamese-pho.png", description:"Pho's magic lies in its broth — beef bones and warm spices like star anise and cinnamon are simmered for hours until deeply fragrant and clear. Silky rice noodles and thin slices of beef are bathed in the hot broth, then finished tableside with fresh herbs, bean sprouts, and a squeeze of lime. Each bowl is a soothing, aromatic experience that feels like a warm hug from the inside out.",
    ingredientsList:["200g flat rice noodles","6 cups beef broth","2 star anise","1 cinnamon stick","200g beef sirloin, thinly sliced","fresh herbs (basil, cilantro)","bean sprouts and lime, to serve"],
    steps:["Simmer beef broth with star anise and cinnamon stick for at least 30 minutes to infuse the flavors.","Soak rice noodles in hot water until softened; drain and divide into bowls.","Strain the fragrant broth and bring back to a rolling simmer.","Arrange thin raw beef slices over the noodles, then ladle the hot broth on top to cook the beef.","Serve with fresh herbs, bean sprouts, and lime wedges on the side."] },
  { name:"Korean Japchae", cuisine:"Korean", ingredients:"Glass noodles, vegetables, beef, soy sauce", mood:"Colorful & Savory", difficulty:"Medium", why:"Glossy noodles tossed with veggies for a festive, crowd-pleasing dish.", mainBase:"Noodles", image:"images/korean-japchae.png", description:"Chewy, glass-like sweet potato noodles are stir-fried with a rainbow of colorful vegetables and tender beef, all glazed in a savory-sweet soy sauce dressing. Each ingredient is traditionally cooked separately before being combined, which keeps every element vibrant and distinct in flavor and texture. It's a festive, crowd-pleasing dish often served at Korean celebrations and family gatherings.",
    ingredientsList:["200g sweet potato glass noodles","150g beef, thinly sliced","1 carrot, julienned","1 cup spinach","1 onion, sliced","4 tbsp soy sauce","2 tbsp sugar","1 tbsp sesame oil"],
    steps:["Cook glass noodles according to package instructions; drain and cut into shorter lengths.","Sauté the beef separately until cooked, then set aside.","Sauté the carrot, onion, and spinach separately until just tender.","Combine noodles, beef, and vegetables in a large bowl with soy sauce, sugar, and sesame oil.","Toss everything together well and serve warm or at room temperature."] },
  { name:"Singapore Noodles", cuisine:"Singaporean", ingredients:"Vermicelli, curry powder, shrimp, egg", mood:"Spicy & Fragrant", difficulty:"Easy", why:"Curry-spiced noodles that are quick to make and full of flavor.", mainBase:"Noodles", image:"images/singapore-noodles.png", description:"Thin rice vermicelli noodles are stir-fried with a generous dusting of curry powder, giving them a warm golden color and fragrant spiced flavor. Juicy shrimp and scrambled egg add heartiness, while a quick toss over high heat keeps the noodles light and never mushy. It's a fast, aromatic dish that punches well above its short cooking time.",
    ingredientsList:["200g rice vermicelli noodles","150g shrimp, peeled","2 eggs","2 tbsp curry powder","1 red bell pepper, sliced","2 tbsp soy sauce","2 tbsp vegetable oil"],
    steps:["Soak vermicelli noodles in warm water until softened; drain.","Heat oil in a wok and scramble the eggs briefly; remove and set aside.","Stir-fry shrimp and bell pepper until the shrimp turns pink.","Add the noodles, curry powder, and soy sauce, tossing everything together over high heat.","Fold the scrambled eggs back in and serve immediately."] },
  { name:"Udon Stir Fry", cuisine:"Japanese", ingredients:"Udon noodles, vegetables, soy sauce", mood:"Chewy & Satisfying", difficulty:"Easy", why:"Thick, chewy noodles tossed in a glossy savory glaze.", mainBase:"Noodles", image:"images/udon-stir-fry.png", description:"Thick, chewy udon noodles are stir-fried with crisp seasonal vegetables in a glossy, savory soy-based sauce that clings to every strand. Their satisfying bounce makes each bite feel substantial and comforting, even though the dish itself is quick and simple to prepare. It's an easy weeknight option when you want something warm, hearty, and packed with umami flavor.",
    ingredientsList:["2 portions fresh udon noodles","1 cup broccoli florets","1 carrot, sliced","1 red bell pepper, sliced","3 tbsp soy sauce","1 tbsp oyster sauce","2 tbsp vegetable oil"],
    steps:["Loosen the udon noodles under warm water and drain well.","Heat oil in a wok and stir-fry broccoli, carrot, and bell pepper until tender-crisp.","Add the udon noodles to the wok along with soy sauce and oyster sauce.","Toss everything together over high heat until the noodles are well coated and heated through.","Serve immediately while hot."] },

  { name:"Garlic Chili Oil Noodles", cuisine:"Chinese Inspired", ingredients:"Noodles, garlic, chili oil, scallion", mood:"Bold & Quick", difficulty:"Easy", why:"A fast noodle bowl with big garlicky heat and glossy sauce.", mainBase:"Noodles", image:"images/garlic-chili-oil-noodles.png", description:"These noodles are all about speed and flavor. Hot oil blooms garlic, chili flakes, and scallions into a fragrant sauce that coats each noodle with savory heat. A splash of soy sauce and vinegar balances the richness, making it a quick pantry meal with serious personality.",
    ingredientsList:["250g wheat noodles","3 cloves garlic, minced","2 tbsp chili oil","1 tbsp soy sauce","1 tsp rice vinegar","2 scallions, sliced","1 tbsp sesame seeds","1 tsp sugar"],
    steps:["Cook noodles according to package directions and drain.","Place garlic, scallions, sesame seeds, and chili flakes or chili oil in a heatproof bowl.","Heat neutral oil until shimmering and pour it over the aromatics.","Stir in soy sauce, vinegar, and sugar.","Toss with hot noodles until glossy and serve right away."] },
  { name:"Laksa Noodle Soup", cuisine:"Southeast Asian", ingredients:"Rice noodles, coconut milk, shrimp, curry paste", mood:"Fragrant & Warming", difficulty:"Medium", why:"Creamy coconut curry broth makes every spoonful feel vibrant.", mainBase:"Noodles", image:"images/laksa-noodle-soup.png", description:"Laksa brings together rice noodles, coconut milk, curry paste, and bright herbs in one aromatic bowl. The broth is creamy and spicy, while shrimp, tofu puffs, and bean sprouts add texture. It is a lively noodle soup for days when you want comfort with a little spark.",
    ingredientsList:["250g rice noodles","2 tbsp laksa or red curry paste","1 can coconut milk","3 cups chicken or vegetable broth","250g shrimp, peeled","1 cup bean sprouts","tofu puffs, optional","lime and herbs, to serve"],
    steps:["Soak or cook rice noodles according to package directions.","Fry curry paste in a pot with a little oil until fragrant.","Add coconut milk and broth, then simmer for 8-10 minutes.","Add shrimp and cook until pink.","Serve broth over noodles with bean sprouts, tofu puffs, lime, and herbs."] },
  { name:"Shoyu Ramen", cuisine:"Japanese", ingredients:"Ramen noodles, soy broth, chashu, egg, scallion", mood:"Savory & Comforting", difficulty:"Medium", why:"Clear soy broth and classic toppings make a balanced ramen bowl.", mainBase:"Noodles", image:"images/shoyu-ramen.webp", description:"Shoyu ramen is a classic Japanese noodle bowl built around a clear, savory soy-based broth. Springy noodles, tender chashu, a jammy egg, bamboo shoots, scallions, and nori create a comforting bowl with clean, deep flavor.",
    ingredientsList:["2 portions ramen noodles","4 cups chicken or dashi broth","3 tbsp soy sauce","4 slices chashu pork","2 soft-boiled eggs","1/2 cup bamboo shoots","2 scallions, sliced","nori sheets"],
    steps:["Warm broth with soy sauce until gently simmering.","Cook ramen noodles according to package directions.","Divide noodles between bowls and ladle broth over them.","Top with chashu, eggs, bamboo shoots, scallions, and nori.","Serve immediately while hot."] },
  { name:"Cold Soba Noodle Salad", cuisine:"Japanese Inspired", ingredients:"Soba, cucumber, edamame, radish, sesame", mood:"Cool & Refreshing", difficulty:"Easy", why:"Chilled soba and crisp vegetables make a light but satisfying bowl.", mainBase:"Noodles", image:"images/cold-soba-noodle-salad.webp", description:"Cold soba noodle salad is refreshing, nutty, and easy to prep ahead. Buckwheat noodles are tossed with cucumber ribbons, edamame, radish, scallions, sesame seeds, and a light soy-sesame dressing for a clean lunch or side.",
    ingredientsList:["250g soba noodles","1 cucumber, ribboned","1 cup edamame","4 radishes, sliced","2 scallions, sliced","2 tbsp sesame seeds","2 tbsp soy sauce","1 tbsp rice vinegar","1 tbsp sesame oil"],
    steps:["Cook soba noodles, then rinse under cold water and drain well.","Whisk soy sauce, rice vinegar, and sesame oil.","Toss noodles with cucumber, edamame, radish, and scallions.","Add dressing and toss again.","Finish with sesame seeds before serving."] },
  { name:"Beef Chow Fun", cuisine:"Cantonese", ingredients:"Wide rice noodles, beef, bean sprouts, scallions", mood:"Smoky & Savory", difficulty:"Medium", why:"Wide noodles and wok-charred beef make a deeply satisfying stir-fry.", mainBase:"Noodles", image:"images/beef-chow-fun.webp", description:"Beef chow fun is all about silky wide rice noodles, tender beef, crisp bean sprouts, and smoky wok flavor. A dark soy glaze coats everything lightly, giving the dish its signature savory depth without making it heavy.",
    ingredientsList:["400g fresh wide rice noodles","250g beef slices","2 cups bean sprouts","3 scallions, cut into pieces","2 tbsp soy sauce","1 tbsp dark soy sauce","1 tbsp oyster sauce","2 tbsp oil"],
    steps:["Separate fresh rice noodles gently.","Sear beef quickly in a hot wok and set aside.","Stir-fry noodles with soy sauces and oyster sauce.","Add bean sprouts, scallions, and beef back to the wok.","Toss over high heat until glossy and lightly charred."] },
  { name:"Taiwanese Beef Noodle Soup", cuisine:"Taiwanese", ingredients:"Wheat noodles, braised beef, bok choy, chili oil", mood:"Rich & Warming", difficulty:"Medium", why:"Braised beef and deep broth make a hearty noodle classic.", mainBase:"Noodles", image:"images/taiwanese-beef-noodle-soup.webp", description:"Taiwanese beef noodle soup brings tender braised beef, thick wheat noodles, bok choy, scallions, and chili oil into a fragrant dark broth. It is bold, warming, and deeply comforting without needing many garnishes.",
    ingredientsList:["2 portions wheat noodles","400g braised beef chunks","4 cups beef broth","2 tbsp soy sauce","1 tbsp chili bean paste","2 heads bok choy","2 scallions, sliced","chili oil"],
    steps:["Simmer beef broth with soy sauce and chili bean paste.","Cook noodles until tender.","Blanch bok choy briefly.","Divide noodles into bowls and add beef and bok choy.","Ladle hot broth over the top and finish with scallions and chili oil."] },
  { name:"Peanut Sesame Noodles", cuisine:"Asian Fusion", ingredients:"Noodles, peanut butter, sesame, cucumber, chili crisp", mood:"Creamy & Nutty", difficulty:"Easy", why:"A creamy sesame sauce turns simple noodles into a craveable bowl.", mainBase:"Noodles", image:"images/peanut-sesame-noodles.webp", description:"Peanut sesame noodles are creamy, nutty, and just spicy enough. Chewy noodles are tossed in a peanut-sesame sauce with cucumber, carrots, scallions, peanuts, and chili crisp, making them great warm or chilled.",
    ingredientsList:["300g noodles","3 tbsp peanut butter","1 tbsp sesame paste or tahini","2 tbsp soy sauce","1 tbsp rice vinegar","1 cucumber, julienned","1 carrot, julienned","2 scallions, sliced","crushed peanuts","chili crisp"],
    steps:["Cook noodles, then rinse or drain depending on whether serving cold or warm.","Whisk peanut butter, sesame paste, soy sauce, vinegar, and a splash of water.","Toss noodles with the sauce until coated.","Add cucumber, carrot, and scallions.","Top with crushed peanuts and chili crisp."] },
  { name:"Yaki Udon", cuisine:"Japanese", ingredients:"Udon, chicken, cabbage, carrots, mushrooms", mood:"Chewy & Savory", difficulty:"Easy", why:"Thick udon noodles make a fast stir-fry extra satisfying.", mainBase:"Noodles", image:"images/yaki-udon.webp", description:"Yaki udon is a quick stir-fry built around thick, chewy udon noodles. Chicken, cabbage, carrots, mushrooms, scallions, and a glossy soy-based sauce make it hearty, colorful, and easy enough for a weeknight.",
    ingredientsList:["2 portions udon noodles","250g chicken strips","2 cups cabbage, sliced","1 carrot, julienned","1 cup mushrooms, sliced","2 scallions, sliced","2 tbsp soy sauce","1 tbsp oyster sauce","1 tbsp mirin"],
    steps:["Loosen udon noodles according to package directions.","Stir-fry chicken until cooked through.","Add cabbage, carrot, and mushrooms and cook until tender-crisp.","Add udon, soy sauce, oyster sauce, and mirin.","Toss until glossy and finish with scallions."] },
  { name:"Tom Yum Noodle Soup", cuisine:"Thai", ingredients:"Rice noodles, shrimp, mushrooms, tomato, lime", mood:"Spicy & Zesty", difficulty:"Medium", why:"Hot, sour broth and shrimp make a lively noodle soup.", mainBase:"Noodles", image:"images/tom-yum-noodle-soup.webp", description:"Tom yum noodle soup adds rice noodles to the Thai hot-and-sour classic. Shrimp, mushrooms, tomatoes, lime, cilantro, and chili oil swim in a bright red-orange broth that feels bold but refreshing.",
    ingredientsList:["200g rice noodles","250g shrimp","4 cups broth","1 cup mushrooms, sliced","1 cup cherry tomatoes","2 tbsp tom yum paste","1 lime, juiced","fresh cilantro","chili oil"],
    steps:["Simmer broth with tom yum paste.","Add mushrooms and tomatoes and cook until softened.","Add shrimp and simmer until pink.","Cook rice noodles separately and divide into bowls.","Ladle soup over noodles and finish with lime, cilantro, and chili oil."] },
  { name:"Char Kway Teow", cuisine:"Malaysian", ingredients:"Flat rice noodles, shrimp, sausage, egg, bean sprouts", mood:"Smoky & Bold", difficulty:"Medium", why:"Dark soy glaze and wok heat create a rich street-food noodle plate.", mainBase:"Noodles", image:"images/char-kway-teow.webp", description:"Char kway teow is a smoky Malaysian stir-fry with flat rice noodles, shrimp, Chinese sausage, egg, bean sprouts, garlic chives, and dark soy glaze. High heat gives the noodles their signature charred edges and savory depth.",
    ingredientsList:["400g flat rice noodles","200g shrimp","1 Chinese sausage, sliced","2 eggs","2 cups bean sprouts","1 cup garlic chives","2 tbsp dark soy sauce","1 tbsp soy sauce","2 tbsp oil"],
    steps:["Heat oil in a wok until very hot.","Stir-fry shrimp and sausage briefly.","Add noodles and sauces, tossing quickly.","Push noodles aside and scramble eggs in the wok.","Add bean sprouts and chives, then toss until smoky and glossy."] },
  { name:"Spicy Miso Udon", cuisine:"Japanese Inspired", ingredients:"Udon, miso, pork, corn, bok choy", mood:"Creamy & Spicy", difficulty:"Medium", why:"Miso broth, thick noodles, and chili oil make a cozy bowl.", mainBase:"Noodles", image:"images/spicy-miso-udon.webp", description:"Spicy miso udon is creamy, rich, and warming. Thick udon noodles sit in a red miso broth with ground pork, corn, bok choy, scallions, chili oil, and a soft egg for a bold comfort bowl.",
    ingredientsList:["2 portions udon noodles","250g ground pork","4 cups broth","3 tbsp miso paste","1 tbsp chili paste","1 cup corn","2 heads bok choy","2 soft-boiled eggs","scallions"],
    steps:["Brown ground pork in a pot.","Add broth, miso paste, and chili paste and simmer gently.","Cook udon noodles and bok choy until tender.","Divide noodles into bowls and ladle broth over them.","Top with pork, corn, egg, bok choy, and scallions."] },
  { name:"Thai Drunken Noodles", cuisine:"Thai", ingredients:"Wide rice noodles, chicken, basil, bell pepper, chili", mood:"Spicy & Aromatic", difficulty:"Medium", why:"Thai basil and chili make these noodles bold and fragrant.", mainBase:"Noodles", image:"images/thai-drunken-noodles.webp", description:"Thai drunken noodles, or pad kee mao, are glossy, spicy, and full of basil aroma. Wide rice noodles are stir-fried with chicken, bell peppers, onion, chili, and a savory sauce until the edges pick up a little char.",
    ingredientsList:["400g wide rice noodles","250g chicken strips","1 bell pepper, sliced","1 onion, sliced","2 cloves garlic, minced","1 red chili, sliced","1 cup Thai basil","2 tbsp soy sauce","1 tbsp oyster sauce"],
    steps:["Stir-fry garlic and chili in hot oil.","Add chicken and cook until browned.","Add bell pepper and onion and cook briefly.","Toss in noodles and sauces over high heat.","Fold in Thai basil just before serving."] },
  { name:"Shanghai Scallion Oil Noodles", cuisine:"Chinese", ingredients:"Wheat noodles, scallions, soy sauce, sesame", mood:"Simple & Aromatic", difficulty:"Easy", why:"Fried scallion oil gives plain noodles deep savory fragrance.", mainBase:"Noodles", image:"images/shanghai-scallion-oil-noodles.webp", description:"Shanghai scallion oil noodles are wonderfully simple. Scallions are slowly fried until dark and fragrant, then mixed with soy sauce and tossed through thin wheat noodles for a glossy, deeply aromatic bowl.",
    ingredientsList:["300g thin wheat noodles","6 scallions, cut into strips","3 tbsp neutral oil","2 tbsp soy sauce","1 tbsp dark soy sauce","1 tsp sugar","sesame seeds"],
    steps:["Fry scallions slowly in oil until browned and crisp.","Stir soy sauces and sugar into the scallion oil.","Cook noodles until tender and drain.","Toss noodles with scallion oil sauce.","Top with fried scallions and sesame seeds."] },
  { name:"Burmese Coconut Noodles", cuisine:"Burmese Inspired", ingredients:"Egg noodles, coconut milk, chicken, lime, crispy noodles", mood:"Creamy & Fragrant", difficulty:"Medium", why:"Coconut curry broth and crunchy toppings make every bite layered.", mainBase:"Noodles", image:"images/burmese-coconut-noodles.webp", description:"Burmese coconut noodles are inspired by ohn no khao swe, a creamy chicken coconut curry noodle soup. Tender noodles, shredded chicken, lime, cilantro, chili oil, and crispy noodles make it rich, bright, and textured.",
    ingredientsList:["300g egg noodles","2 cups coconut milk","2 cups chicken broth","250g shredded cooked chicken","1 tbsp curry powder","1 onion, diced","1 lime","fresh cilantro","crispy noodles","chili oil"],
    steps:["Saute onion with curry powder until fragrant.","Add coconut milk and chicken broth and simmer.","Stir in shredded chicken until warmed through.","Cook egg noodles and divide into bowls.","Ladle soup over noodles and top with lime, cilantro, crispy noodles, and chili oil."] },
  { name:"Kimchi Ramen", cuisine:"Korean Inspired", ingredients:"Ramen, kimchi, pork belly, egg, scallions", mood:"Spicy & Tangy", difficulty:"Easy", why:"Kimchi adds tangy heat to a cozy ramen bowl.", mainBase:"Noodles", image:"images/kimchi-ramen.webp", description:"Kimchi ramen is spicy, tangy, and deeply cozy. Curly noodles simmer in a red broth with kimchi, pork belly, scallions, sesame, and a soft egg, creating a fast bowl with lots of flavor.",
    ingredientsList:["2 portions ramen noodles","1 cup kimchi","4 cups broth","150g pork belly slices","2 soft-boiled eggs","2 scallions, sliced","1 tbsp gochujang","sesame seeds"],
    steps:["Brown pork belly slices in a pot.","Add kimchi, broth, and gochujang and simmer.","Cook ramen noodles in the broth until tender.","Divide into bowls and top with eggs and scallions.","Finish with sesame seeds."] },
  { name:"Lemongrass Chicken Vermicelli", cuisine:"Vietnamese Inspired", ingredients:"Rice vermicelli, lemongrass chicken, herbs, peanuts", mood:"Fresh & Zesty", difficulty:"Medium", why:"Grilled chicken and herbs make a light, colorful noodle bowl.", mainBase:"Noodles", image:"images/lemongrass-chicken-vermicelli.webp", description:"Lemongrass chicken vermicelli is fresh, bright, and satisfying. Rice noodles are topped with grilled lemongrass chicken, lettuce, cucumber, carrots, herbs, peanuts, lime, and nuoc cham for a balanced bowl.",
    ingredientsList:["200g rice vermicelli","300g chicken thighs","1 stalk lemongrass, minced","2 tbsp fish sauce or soy sauce","1 tbsp sugar","1 cucumber, julienned","1 carrot, julienned","lettuce and fresh herbs","crushed peanuts","nuoc cham sauce"],
    steps:["Marinate chicken with lemongrass, fish sauce or soy sauce, and sugar.","Grill or pan-sear chicken until cooked through.","Cook vermicelli noodles and rinse under cool water.","Arrange noodles with vegetables, herbs, and sliced chicken.","Top with peanuts and serve with nuoc cham."] },
  { name:"Wonton Noodle Soup", cuisine:"Cantonese", ingredients:"Egg noodles, wontons, bok choy, scallions", mood:"Light & Comforting", difficulty:"Medium", why:"Clear broth, springy noodles, and tender wontons feel soothing.", mainBase:"Noodles", image:"images/wonton-noodle-soup.webp", description:"Wonton noodle soup is light, clear, and comforting. Thin egg noodles sit in golden broth with tender shrimp-pork wontons, bok choy, scallions, and a little sesame oil for a clean but satisfying bowl.",
    ingredientsList:["2 portions thin egg noodles","10 wontons","4 cups chicken broth","2 heads bok choy","2 scallions, sliced","1 tsp sesame oil","white pepper"],
    steps:["Bring broth to a gentle simmer.","Cook wontons until they float and are cooked through.","Blanch bok choy in the broth.","Cook egg noodles separately and divide into bowls.","Add wontons and bok choy, ladle broth over top, and finish with scallions and sesame oil."] },
  // ---------------- POTATO ----------------
  { name:"Classic Mashed Potatoes", cuisine:"American", ingredients:"Potato, butter, milk, garlic", mood:"Cozy & Familiar", difficulty:"Easy", why:"Creamy comfort food that pairs with almost anything.", mainBase:"Potato", image:"images/classic-mashed-potatoes.png", description:"Potatoes are boiled until fork-tender, then whipped with plenty of butter, warm milk, and a touch of garlic until impossibly smooth and creamy. The key to the fluffiest texture is not over-mixing, which keeps the potatoes light rather than gluey. This is the ultimate cozy side dish that pairs effortlessly with everything from roast chicken to a simple weeknight meatloaf.",
    ingredientsList:["1kg potatoes, peeled and chopped","1/2 cup warm milk","4 tbsp butter","1 clove garlic, minced","salt to taste"],
    steps:["Boil the potatoes in salted water until fork-tender, about 15-20 minutes; drain well.","Warm the milk with the minced garlic in a small pan.","Mash the potatoes while still hot until mostly smooth.","Stir in the butter and warm garlic milk gradually.","Season with salt to taste and serve warm."] },
  { name:"Loaded Baked Potato", cuisine:"American", ingredients:"Potato, cheese, bacon, sour cream", mood:"Hearty & Indulgent", difficulty:"Easy", why:"A filling meal-in-one that's endlessly customizable.", mainBase:"Potato", image:"images/loaded-baked-potato.png", description:"A whole potato is baked until the skin turns crisp and the inside becomes soft and fluffy, then split open and piled high with melted cheese, crispy bacon bits, and a generous dollop of cool sour cream. It's satisfying enough to be a meal on its own, yet flexible enough to customize with whatever toppings you have on hand. Perfect for busy nights when you want something hearty with minimal effort.",
    ingredientsList:["4 large russet potatoes","1 cup shredded cheddar cheese","4 strips bacon, cooked and crumbled","1/2 cup sour cream","2 scallions, sliced"],
    steps:["Preheat the oven to 220°C (425°F) and pierce each potato a few times with a fork.","Bake the potatoes directly on the oven rack for 45-60 minutes until the skin is crisp and the inside is tender.","Slice each potato open lengthwise and fluff the inside with a fork.","Top with shredded cheese while hot so it melts, then add crumbled bacon.","Finish with a dollop of sour cream and sliced scallions before serving."] },
  { name:"Spanish Tortilla", cuisine:"Spanish", ingredients:"Potato, egg, onion", mood:"Simple & Rustic", difficulty:"Medium", why:"A humble potato omelette that's a beloved Spanish staple.", mainBase:"Potato", image:"images/spanish-tortilla.png", description:"Thinly sliced potatoes and onions are slowly cooked in olive oil until soft and slightly caramelized, then bound together with beaten eggs and cooked into a thick, satisfying omelette. It's traditionally flipped whole in the pan, a small kitchen ritual that Spanish home cooks take pride in mastering. Delicious warm, at room temperature, or even cold the next day, it's a humble but beloved staple of Spanish cuisine.",
    ingredientsList:["4 medium potatoes, thinly sliced","1 onion, thinly sliced","6 eggs","1/2 cup olive oil","salt to taste"],
    steps:["Heat olive oil in a pan and slowly cook the potatoes and onion over low heat until soft, about 20 minutes.","Drain the potatoes and onion, reserving the oil, and let cool slightly.","Whisk the eggs in a large bowl and fold in the potatoes and onion.","Pour a little reserved oil into a non-stick pan, add the mixture, and cook over medium-low heat until the bottom sets.","Flip the tortilla using a plate and cook the other side until golden and just set in the center."] },
  { name:"Potato Curry", cuisine:"Indian", ingredients:"Potato, tomato, spices", mood:"Warm & Spiced", difficulty:"Easy", why:"A budget-friendly curry that's big on comfort and flavor.", mainBase:"Potato", image:"images/potato-curry.png", description:"Chunks of potato are simmered in a warmly spiced tomato-based sauce until they turn tender and soak up all the flavor of cumin, turmeric, and coriander. It's an incredibly budget-friendly dish that still delivers deep, comforting spice and richness. Served with rice or warm bread, it's proof that simple, humble ingredients can make a truly satisfying curry.",
    ingredientsList:["4 potatoes, cubed","2 tomatoes, chopped","1 onion, diced","1 tsp cumin","1 tsp turmeric","1 tsp ground coriander","2 tbsp oil","fresh cilantro, to garnish"],
    steps:["Heat oil in a pot and sauté the onion until soft.","Add cumin, turmeric, and coriander, stirring until fragrant.","Stir in the chopped tomatoes and cook until they break down.","Add the cubed potatoes along with 1 cup of water, cover, and simmer for 20 minutes until tender.","Garnish with fresh cilantro and serve with rice or bread."] },
  { name:"Crispy Roasted Potatoes", cuisine:"British", ingredients:"Potato, olive oil, rosemary", mood:"Crispy & Satisfying", difficulty:"Easy", why:"The perfect crunchy side for any Sunday roast dinner.", mainBase:"Potato", image:"images/crispy-roasted-potatoes.png", description:"Potato chunks are parboiled, then roughed up slightly before roasting in hot olive oil, which creates a wonderfully crispy, golden exterior while keeping the inside soft and fluffy. Fresh rosemary adds a fragrant, earthy note that pairs beautifully with the crunch. They're the classic finishing touch to a proper Sunday roast dinner, and disappear from the table fast.",
    ingredientsList:["1kg potatoes, cut into chunks","4 tbsp olive oil","2 sprigs fresh rosemary","salt to taste"],
    steps:["Parboil the potato chunks in salted water for 8-10 minutes; drain well.","Shake the colander to rough up the edges of the potatoes.","Toss the potatoes with olive oil and rosemary on a roasting tray.","Roast at 220°C (425°F) for 35-40 minutes, turning halfway, until golden and crisp.","Season with salt and serve hot."] },
  { name:"Potato Leek Soup", cuisine:"French", ingredients:"Potato, leek, cream, broth", mood:"Soothing & Silky", difficulty:"Easy", why:"A velvety soup that's perfect for chilly evenings.", mainBase:"Potato", image:"images/potato-leek-soup.png", description:"Sweet, mild leeks are gently sautéed before simmering with potatoes and broth until everything turns soft enough to blend into a silky, velvety soup. A splash of cream at the end rounds out the flavor and gives it a luxuriously smooth finish. It's the kind of soothing, elegant soup that feels equally at home on a chilly weeknight or as the starter to a special dinner.",
    ingredientsList:["3 leeks, sliced (white and light green parts)","4 potatoes, chopped","4 cups vegetable broth","1/2 cup cream","2 tbsp butter"],
    steps:["Melt butter in a pot and sauté the leeks until soft, about 5 minutes.","Add the chopped potatoes and vegetable broth, and bring to a simmer.","Cook for 20 minutes until the potatoes are very tender.","Blend the soup until smooth using an immersion blender.","Stir in the cream, season to taste, and serve warm."] },
  { name:"Hash Browns", cuisine:"American", ingredients:"Potato, onion, oil", mood:"Crispy & Quick", difficulty:"Easy", why:"A breakfast classic that's ready in minutes.", mainBase:"Potato", image:"images/hash-browns.png", description:"Shredded potatoes are pressed thin and fried in hot oil until the edges turn deeply golden and shatteringly crisp, while the center stays tender. A touch of finely diced onion adds extra flavor and a subtle sweetness as it caramelizes alongside the potato. They're a breakfast classic that comes together in minutes and pairs perfectly with eggs of any style.",
    ingredientsList:["3 potatoes, peeled and shredded","1/4 onion, finely diced","3 tbsp oil","salt and pepper to taste"],
    steps:["Squeeze the shredded potatoes to remove excess moisture.","Mix the potatoes with diced onion, salt, and pepper.","Heat oil in a skillet over medium-high heat.","Press the potato mixture into thin patties in the skillet and fry for 4-5 minutes per side until golden and crisp.","Drain briefly on paper towels and serve hot."] },
  { name:"Potato Gnocchi", cuisine:"Italian", ingredients:"Potato, flour, egg", mood:"Pillowy & Comforting", difficulty:"Medium", why:"Soft potato dumplings that feel like a warm hug on a plate.", mainBase:"Potato", image:"images/potato-gnocchi.png", description:"Soft mashed potatoes are gently worked with flour and egg into a tender dough, then rolled and cut into small pillowy dumplings that cook in just a minute or two of boiling water. The key is a light touch — overworking the dough makes them dense instead of fluffy. Tossed simply in butter and sage or a rich tomato sauce, gnocchi feels like a warm, comforting hug on a plate.",
    ingredientsList:["1kg potatoes","2 cups flour","1 egg","salt to taste","butter and sage, to serve"],
    steps:["Boil the potatoes whole with skins on until tender; drain and let cool slightly.","Peel and mash the potatoes while still warm until smooth.","Mix in the egg and flour gradually to form a soft dough.","Roll the dough into ropes and cut into small pillow-shaped pieces.","Boil the gnocchi in batches until they float to the surface, then toss with butter and sage."] },

  { name:"Sweet Potato Tacos", cuisine:"Mexican Inspired", ingredients:"Sweet potato, tortillas, black beans, avocado", mood:"Colorful & Fresh", difficulty:"Easy", why:"Roasted sweet potatoes make these tacos hearty and naturally sweet.", mainBase:"Potato", image:"images/sweet-potato-tacos.png", description:"Roasted sweet potato cubes bring caramelized sweetness to these bright, satisfying tacos. Black beans add substance, avocado adds creaminess, and lime crema ties everything together. They are colorful, flexible, and easy to make vegetarian without feeling light.",
    ingredientsList:["2 sweet potatoes, diced","8 small corn tortillas","1 can black beans, drained","1 avocado, diced","1/4 cup lime crema or yogurt","1 tsp smoked paprika","fresh cilantro","lime wedges"],
    steps:["Toss sweet potatoes with oil, smoked paprika, and salt.","Roast at 220C (425F) for 20-25 minutes until tender and browned.","Warm tortillas in a dry skillet.","Fill each tortilla with black beans, sweet potatoes, and avocado.","Drizzle with lime crema and finish with cilantro and lime."] },
  { name:"Potato Gratin", cuisine:"French", ingredients:"Potato, cream, cheese, thyme", mood:"Golden & Elegant", difficulty:"Medium", why:"Thin potato layers bake into a creamy, bubbling side dish.", mainBase:"Potato", image:"images/potato-gratin.png", description:"Potato gratin turns thinly sliced potatoes into a golden, creamy bake with tender layers and a browned top. A little cheese and thyme add depth without overpowering the potatoes. It works as a cozy main with salad or as a polished side for a special dinner.",
    ingredientsList:["1kg potatoes, thinly sliced","1.5 cups cream","1 cup grated gruyere or cheddar","2 cloves garlic, minced","1 tsp fresh thyme","1 tbsp butter","salt and black pepper to taste"],
    steps:["Preheat the oven to 190C (375F) and butter a baking dish.","Layer sliced potatoes with garlic, thyme, salt, pepper, and cheese.","Pour cream evenly over the layers.","Bake covered for 35 minutes, then uncover and bake 20 minutes more.","Rest for 10 minutes before serving so the layers set."] },
  { name:"Patatas Bravas", cuisine:"Spanish", ingredients:"Potatoes, tomato sauce, aioli, smoked paprika", mood:"Crispy & Bold", difficulty:"Easy", why:"Crispy potatoes, smoky sauce, and creamy aioli make perfect tapas.", mainBase:"Potato", image:"images/patatas-bravas.webp", description:"Patatas bravas is a Spanish tapas favorite built around crisp potato cubes, smoky tomato sauce, and a cool garlic aioli drizzle. It is punchy, shareable, and excellent when you want potatoes with a little attitude.",
    ingredientsList:["700g potatoes, cubed","2 tbsp olive oil","1 cup tomato sauce","1 tsp smoked paprika","1/2 tsp chili flakes","1/3 cup aioli","fresh parsley","salt to taste"],
    steps:["Roast or fry potato cubes until crisp and golden.","Simmer tomato sauce with smoked paprika and chili flakes.","Season potatoes with salt while hot.","Spoon bravas sauce over the potatoes.","Drizzle with aioli and finish with parsley."] },
  { name:"Aloo Paratha", cuisine:"Indian", ingredients:"Potatoes, flatbread, cumin, cilantro, yogurt", mood:"Spiced & Comforting", difficulty:"Medium", why:"Spiced potato filling turns flatbread into a satisfying meal.", mainBase:"Potato", image:"images/aloo-paratha.webp", description:"Aloo paratha wraps spiced mashed potatoes inside a golden pan-cooked flatbread. The filling is fragrant with cumin, chili, and cilantro, while yogurt and pickle on the side make each bite balanced and comforting.",
    ingredientsList:["2 cups mashed potatoes","2 cups whole wheat flour","1 tsp cumin","1/2 tsp garam masala","1 green chili, minced","1/2 cup cilantro, chopped","yogurt and pickle, to serve","ghee or oil"],
    steps:["Mix mashed potatoes with spices, chili, cilantro, and salt.","Make a soft dough with flour, water, and a pinch of salt.","Stuff dough portions with potato filling and roll gently.","Cook on a hot skillet with ghee until browned on both sides.","Serve with yogurt and pickle."] },
  { name:"German Potato Salad", cuisine:"German", ingredients:"Potatoes, bacon, red onion, mustard vinaigrette", mood:"Tangy & Savory", difficulty:"Easy", why:"Warm potatoes soak up mustard dressing for deep, cozy flavor.", mainBase:"Potato", image:"images/german-potato-salad.webp", description:"German potato salad is warm, tangy, and savory. Tender potato slices are tossed with crisp bacon, red onion, parsley, and a mustard vinaigrette that soaks into every piece without feeling heavy.",
    ingredientsList:["700g waxy potatoes","4 slices bacon, chopped","1/2 red onion, sliced","2 tbsp apple cider vinegar","1 tbsp Dijon mustard","2 tbsp olive oil","fresh parsley","salt and black pepper"],
    steps:["Boil potatoes until tender, then slice while warm.","Cook bacon until crisp and reserve some drippings.","Whisk vinegar, mustard, olive oil, and bacon drippings.","Toss potatoes with dressing, bacon, and red onion.","Finish with parsley and black pepper."] },
  { name:"Potato Pancakes", cuisine:"Eastern European", ingredients:"Potatoes, onion, egg, sour cream, chives", mood:"Crispy & Cozy", difficulty:"Easy", why:"Shredded potatoes fry into crisp edges and tender centers.", mainBase:"Potato", image:"images/potato-pancakes.webp", description:"Potato pancakes are crisp, golden, and deeply comforting. Shredded potatoes and onion are bound with egg, fried until crunchy at the edges, and served with sour cream, chives, or applesauce.",
    ingredientsList:["4 potatoes, grated","1 small onion, grated","1 egg","3 tbsp flour","1/2 tsp salt","oil for frying","sour cream","chives"],
    steps:["Squeeze excess moisture from grated potatoes and onion.","Mix with egg, flour, and salt.","Spoon small patties into hot oil.","Fry until golden and crisp on both sides.","Drain and serve with sour cream and chives."] },
  { name:"Shepherd's Pie", cuisine:"British Inspired", ingredients:"Mashed potatoes, ground beef, peas, carrots", mood:"Hearty & Homestyle", difficulty:"Medium", why:"Fluffy mashed potato topping turns savory filling into comfort food.", mainBase:"Potato", image:"images/shepherds-pie.webp", description:"Shepherd's pie layers savory beef and vegetables under a blanket of mashed potatoes, then bakes until the top is browned and crisp at the peaks. It is hearty, family-friendly, and perfect for a cozy dinner.",
    ingredientsList:["3 cups mashed potatoes","400g ground beef or lamb","1 onion, diced","1 carrot, diced","1 cup peas","1 cup beef broth","1 tbsp tomato paste","1 tbsp Worcestershire sauce"],
    steps:["Cook onion, carrot, and ground meat until browned.","Stir in tomato paste, broth, Worcestershire sauce, and peas.","Simmer until the filling thickens.","Spread filling in a baking dish and top with mashed potatoes.","Bake until golden and bubbling."] },
  { name:"Duchess Potatoes", cuisine:"French", ingredients:"Mashed potatoes, egg yolk, butter, parmesan", mood:"Elegant & Buttery", difficulty:"Medium", why:"Piped potato rosettes make a simple side feel special.", mainBase:"Potato", image:"images/duchess-potatoes.webp", description:"Duchess potatoes turn mashed potatoes into elegant golden rosettes. Egg yolk and butter help the ridges bake crisp while the centers stay soft and creamy, making them a beautiful side for special dinners.",
    ingredientsList:["700g potatoes, mashed","3 tbsp butter","2 egg yolks","1/4 cup parmesan","1/2 tsp salt","black pepper","fresh parsley"],
    steps:["Mash hot potatoes with butter, parmesan, salt, and pepper.","Cool slightly, then mix in egg yolks.","Pipe the mixture into rosettes on a baking sheet.","Bake at 200C (400F) until golden at the ridges.","Garnish with parsley before serving."] },
  { name:"Greek Lemon Potatoes", cuisine:"Greek", ingredients:"Potatoes, lemon, garlic, oregano, olive oil", mood:"Bright & Roasty", difficulty:"Easy", why:"Lemon and oregano give roasted potatoes a fresh Mediterranean lift.", mainBase:"Potato", image:"images/greek-lemon-potatoes.webp", description:"Greek lemon potatoes are tender inside, golden outside, and soaked with bright lemon-garlic flavor. Oregano, olive oil, and parsley keep them simple but deeply aromatic.",
    ingredientsList:["800g potatoes, cut into wedges","1 lemon, juiced and sliced","3 cloves garlic, minced","3 tbsp olive oil","1 tsp dried oregano","1/2 cup broth","fresh parsley","salt and black pepper"],
    steps:["Toss potatoes with lemon juice, garlic, olive oil, oregano, salt, and pepper.","Place in a baking dish with broth and lemon slices.","Roast at 210C (410F) until tender.","Turn potatoes and roast until edges are golden.","Finish with parsley before serving."] },
  { name:"Potato Pierogi", cuisine:"Polish", ingredients:"Potato, cheese, dumpling dough, onion, sour cream", mood:"Tender & Savory", difficulty:"Medium", why:"Potato-cheese dumplings are cozy, satisfying, and pan-seared golden.", mainBase:"Potato", image:"images/potato-pierogi.webp", description:"Potato pierogi are soft dumplings filled with mashed potato and cheese, then pan-seared with caramelized onions. A spoonful of sour cream and chives makes them rich, tangy, and deeply comforting.",
    ingredientsList:["2 cups mashed potatoes","1 cup farmer cheese or cheddar","24 dumpling wrappers or pierogi dough rounds","1 onion, sliced","2 tbsp butter","sour cream","chives"],
    steps:["Mix mashed potatoes with cheese and seasoning.","Fill dough rounds and seal into half-moons.","Boil pierogi until they float.","Pan-sear with butter and onions until golden.","Serve with sour cream and chives."] },
  { name:"Sweet Potato Black Bean Bowl", cuisine:"Mexican Inspired", ingredients:"Sweet potato, black beans, avocado, corn salsa", mood:"Colorful & Nourishing", difficulty:"Easy", why:"Roasted sweet potato and beans make a bright, filling bowl.", mainBase:"Potato", image:"images/sweet-potato-black-bean-bowl.webp", description:"This sweet potato black bean bowl is colorful, filling, and full of contrast. Roasted sweet potatoes meet black beans, avocado, corn salsa, cilantro, lime, and a creamy chipotle drizzle for a fresh but hearty meal.",
    ingredientsList:["2 sweet potatoes, cubed","1 can black beans, drained","1 avocado, sliced","1 cup corn salsa","1 lime","fresh cilantro","2 tbsp chipotle mayo or yogurt sauce","1 tbsp olive oil"],
    steps:["Roast sweet potato cubes with olive oil and salt until browned.","Warm black beans gently.","Arrange sweet potatoes, beans, avocado, and corn salsa in bowls.","Drizzle with chipotle sauce.","Finish with lime and cilantro."] },
  { name:"Potato Croquettes", cuisine:"French Inspired", ingredients:"Mashed potatoes, breadcrumbs, cheese, herbs", mood:"Crispy & Creamy", difficulty:"Medium", why:"Golden breadcrumb shells hide soft, creamy potato centers.", mainBase:"Potato", image:"images/potato-croquettes.webp", description:"Potato croquettes are crisp outside and creamy inside. Mashed potatoes are mixed with cheese and herbs, shaped, breaded, and fried until golden, making them a satisfying snack or side.",
    ingredientsList:["3 cups mashed potatoes","1/2 cup grated cheese","1 egg","1 cup breadcrumbs","2 tbsp flour","fresh parsley","oil for frying","dipping sauce"],
    steps:["Mix mashed potatoes with cheese, parsley, and seasoning.","Shape into small logs or balls.","Coat in flour, egg, and breadcrumbs.","Fry until golden and crisp.","Serve with dipping sauce."] },
  { name:"Hasselback Potatoes", cuisine:"Swedish Inspired", ingredients:"Potatoes, garlic butter, parmesan, parsley", mood:"Crisp & Buttery", difficulty:"Medium", why:"Thin slices create crisp ridges while the inside stays tender.", mainBase:"Potato", image:"images/hasselback-potatoes.webp", description:"Hasselback potatoes are sliced thin without cutting all the way through, then roasted with garlic herb butter until the edges fan out and turn crisp. Parmesan and parsley make them feel polished but approachable.",
    ingredientsList:["6 medium potatoes","4 tbsp butter, melted","2 cloves garlic, minced","1/3 cup parmesan","fresh parsley","salt and black pepper"],
    steps:["Slice potatoes thinly without cutting through the base.","Brush with garlic butter and season well.","Roast at 210C (410F) until tender and fanned open.","Brush with more butter and sprinkle with parmesan.","Bake until crisp and finish with parsley."] },
  { name:"Potato Frittata", cuisine:"Italian Inspired", ingredients:"Potatoes, eggs, spinach, onion, herbs", mood:"Golden & Brunchy", difficulty:"Easy", why:"Tender potatoes make a simple frittata hearty enough for brunch.", mainBase:"Potato", image:"images/potato-frittata.webp", description:"Potato frittata is a hearty skillet dish with sliced potatoes, eggs, spinach, onions, and herbs. It is golden on top, tender inside, and just as good warm as it is at room temperature.",
    ingredientsList:["2 potatoes, thinly sliced","6 eggs","2 cups spinach","1 onion, sliced","1/3 cup milk","1/2 cup grated cheese","2 tbsp olive oil","fresh herbs"],
    steps:["Cook potatoes and onion in olive oil until tender.","Add spinach and wilt briefly.","Whisk eggs with milk, cheese, salt, and pepper.","Pour eggs into the skillet and cook until edges set.","Bake or broil until the center is set and golden."] },
  { name:"Sweet Potato Chili", cuisine:"American Southwest", ingredients:"Sweet potato, black beans, tomato, corn, chili spices", mood:"Hearty & Warming", difficulty:"Easy", why:"Sweet potatoes make chili naturally rich, colorful, and filling.", mainBase:"Potato", image:"images/sweet-potato-chili.webp", description:"Sweet potato chili is hearty, gently sweet, and smoky. Tender sweet potato cubes simmer with tomatoes, black beans, peppers, corn, and chili spices, then get finished with avocado, cilantro, and sour cream.",
    ingredientsList:["2 sweet potatoes, cubed","1 can black beans","1 can diced tomatoes","1 bell pepper, diced","1 cup corn","1 onion, diced","1 tbsp chili powder","1 tsp cumin","avocado and cilantro"],
    steps:["Saute onion and bell pepper until softened.","Add sweet potatoes, tomatoes, beans, corn, and spices.","Simmer until sweet potatoes are tender.","Adjust seasoning with salt and lime if desired.","Top with avocado, cilantro, and sour cream."] },
  { name:"Bombay Aloo", cuisine:"Indian", ingredients:"Potatoes, turmeric, cumin, mustard seeds, curry leaves", mood:"Spiced & Golden", difficulty:"Easy", why:"Simple potatoes become fragrant with warm Indian spices.", mainBase:"Potato", image:"images/bombay-aloo.webp", description:"Bombay aloo is a golden spiced potato dish with turmeric, cumin, mustard seeds, curry leaves, and cilantro. The potatoes are tender inside with lightly crisp edges, making them excellent as a side or a vegetarian main with rice or flatbread.",
    ingredientsList:["700g potatoes, cubed and parboiled","1 tsp turmeric","1 tsp cumin seeds","1 tsp mustard seeds","8 curry leaves","1 onion, diced","2 tbsp oil","fresh cilantro"],
    steps:["Heat oil and bloom cumin seeds, mustard seeds, and curry leaves.","Add onion and cook until softened.","Add parboiled potatoes, turmeric, salt, and a splash of water.","Cook until potatoes are golden and coated in spices.","Finish with cilantro."] },
  { name:"Breakfast Potato Skillet", cuisine:"American", ingredients:"Potatoes, eggs, sausage, peppers, onions", mood:"Hearty & Energizing", difficulty:"Easy", why:"Crispy potatoes and eggs make a full brunch in one pan.", mainBase:"Potato", image:"images/breakfast-potato-skillet.webp", description:"Breakfast potato skillet is a hearty one-pan brunch with crispy potatoes, peppers, onions, sausage, scallions, and sunny eggs. It is colorful, filling, and easy to bring straight to the table.",
    ingredientsList:["700g potatoes, diced","2 eggs","200g sausage, sliced","1 bell pepper, diced","1 onion, diced","2 scallions, sliced","2 tbsp oil","salt and black pepper"],
    steps:["Cook potatoes in oil until browned and tender.","Add sausage, bell pepper, and onion and cook until caramelized.","Make two wells and crack in the eggs.","Cover until eggs are set to your liking.","Finish with scallions and black pepper."] },
  // ---------------- SOUP ----------------
  { name:"Chicken Noodle Soup", cuisine:"American", ingredients:"Chicken, noodles, carrot, celery", mood:"Soothing & Healing", difficulty:"Easy", why:"The ultimate cure for a cold day, or an actual cold.", mainBase:"Soup", image:"images/chicken-noodle-soup.png", description:"A gentle, golden broth is simmered with tender pieces of chicken, sweet carrots, and crisp celery until every ingredient melds into one comforting bowl. Soft egg noodles soak up the savory broth, making each spoonful feel like an edible hug. It's the timeless dish people reach for whether they're feeling under the weather or just craving something simple and soothing.",
    ingredientsList:["2 chicken breasts","6 cups chicken broth","2 carrots, sliced","2 celery stalks, sliced","1 onion, diced","1.5 cups egg noodles"],
    steps:["Bring the chicken broth to a boil and add the chicken breasts.","Simmer for 15-20 minutes until the chicken is cooked through, then remove and shred.","Add carrots, celery, and onion to the broth and simmer until tender.","Add the egg noodles and cook until al dente.","Return the shredded chicken to the pot, season to taste, and serve hot."] },
  { name:"Tomato Basil Soup", cuisine:"Italian-American", ingredients:"Tomato, basil, cream", mood:"Cozy & Classic", difficulty:"Easy", why:"Pairs perfectly with a grilled cheese sandwich.", mainBase:"Soup", image:"images/tomato-basil-soup.png", description:"Ripe tomatoes are simmered down and blended until velvety smooth, then finished with fresh basil and a touch of cream for extra richness and a gentle sweetness. The bright, tangy tomato flavor shines through even with the creamy texture. It's the quintessential cozy soup, best enjoyed with a crispy grilled cheese sandwich for dipping.",
    ingredientsList:["1kg ripe tomatoes, chopped (or 2 cans whole tomatoes)","1 onion, diced","2 cloves garlic","1/2 cup cream","handful of fresh basil","2 cups vegetable broth"],
    steps:["Sauté onion and garlic in a pot until softened.","Add tomatoes and vegetable broth, then simmer for 20 minutes.","Blend the soup until smooth using an immersion blender.","Stir in the cream and fresh basil, and simmer for another 5 minutes.","Season to taste and serve hot with grilled cheese on the side."] },
  { name:"Minestrone", cuisine:"Italian", ingredients:"Vegetables, beans, pasta, broth", mood:"Hearty & Wholesome", difficulty:"Easy", why:"A veggie-packed soup that's a meal in itself.", mainBase:"Soup", image:"images/minestrone.png", description:"This rustic Italian soup is loaded with whatever vegetables you have on hand, along with hearty beans and small pasta shapes simmered in a rich, tomato-based broth. It's a flexible, waste-nothing kind of recipe that changes slightly every time you make it, yet always turns out satisfying. Wholesome and filling enough to be a complete meal, it's a great way to sneak in extra vegetables.",
    ingredientsList:["1 onion, diced","2 carrots, diced","2 celery stalks, diced","1 can diced tomatoes","1 can white beans, drained","1 cup small pasta shapes","4 cups vegetable broth"],
    steps:["Sauté onion, carrot, and celery in a large pot until softened.","Add the diced tomatoes and vegetable broth, and bring to a simmer.","Stir in the white beans and simmer for 15 minutes.","Add the pasta and cook until al dente.","Season to taste and serve hot with a drizzle of olive oil."] },
  { name:"Miso Soup", cuisine:"Japanese", ingredients:"Miso paste, tofu, seaweed", mood:"Light & Nourishing", difficulty:"Easy", why:"A quick, comforting soup that's ready in 10 minutes.", mainBase:"Soup", image:"images/miso-soup.png", description:"A light dashi broth is gently whisked with savory miso paste, then simmered with soft cubes of tofu and delicate seaweed for a simple, nourishing bowl. It's meant to be made quickly and eaten right away, so the miso keeps its delicate flavor and doesn't turn bitter from overcooking. This humble, comforting soup is a staple of Japanese meals for good reason.",
    ingredientsList:["4 cups dashi broth","3 tbsp miso paste","1/2 block tofu, cubed","2 tbsp dried wakame seaweed","1 scallion, sliced"],
    steps:["Bring the dashi broth to a gentle simmer.","Ladle a little hot broth into a bowl and whisk in the miso paste until smooth.","Return the miso mixture to the pot along with the cubed tofu and seaweed.","Warm through gently without letting it boil.","Garnish with sliced scallion and serve immediately."] },
  { name:"Corn Chowder", cuisine:"American", ingredients:"Corn, potato, cream", mood:"Sweet & Creamy", difficulty:"Easy", why:"A creamy bowl that celebrates sweet summer corn.", mainBase:"Soup", image:"images/corn-chowder.png", description:"Sweet corn kernels are simmered with tender chunks of potato in a rich, creamy broth that highlights corn's natural sweetness. Blending a portion of the soup before stirring it back in gives the chowder its signature thick, velvety body while still leaving plenty of texture. It's the ultimate way to celebrate corn at its sweetest, whether that's peak summer or any time you're craving comfort.",
    ingredientsList:["3 cups corn kernels (fresh or frozen)","2 potatoes, diced","1 onion, diced","1 cup cream","3 cups vegetable broth"],
    steps:["Sauté the onion in a pot until softened.","Add the diced potatoes, corn, and vegetable broth, and simmer until the potatoes are tender.","Blend about a third of the soup until smooth, then stir it back into the pot.","Stir in the cream and heat through gently.","Season to taste and serve warm."] },
  { name:"Lentil Soup", cuisine:"Middle Eastern", ingredients:"Lentils, cumin, carrot", mood:"Warm & Nutritious", difficulty:"Easy", why:"A protein-packed soup that's budget-friendly and filling.", mainBase:"Soup", image:"images/lentil-soup.png", description:"Earthy lentils are simmered with sweet carrots and a warm blend of cumin and other spices until they break down into a thick, hearty, nutritious soup. Lentils cook quickly and require no soaking, making this an easy weeknight option that's also incredibly budget-friendly. Packed with plant-based protein, it's a filling meal that doesn't skimp on flavor or nourishment.",
    ingredientsList:["1.5 cups red lentils, rinsed","2 carrots, diced","1 onion, diced","1 tsp ground cumin","5 cups vegetable broth","1 tbsp olive oil"],
    steps:["Heat olive oil in a pot and sauté the onion and carrot until softened.","Stir in the cumin and cook until fragrant.","Add the lentils and vegetable broth, and bring to a boil.","Reduce heat and simmer for 20-25 minutes until the lentils are soft and the soup has thickened.","Blend partially for a creamier texture if desired, season to taste, and serve hot."] },
  { name:"French Onion Soup", cuisine:"French", ingredients:"Onion, broth, cheese, bread", mood:"Rich & Comforting", difficulty:"Medium", why:"Caramelized onions and melted cheese in every spoonful.", mainBase:"Soup", image:"images/french-onion-soup.png", description:"Onions are cooked low and slow until they turn deeply caramelized and almost jammy, forming the rich, sweet backbone of this classic French soup. A slice of toasted bread and a generous layer of melted cheese are broiled right on top, creating a bubbly, golden crust you have to break through with your spoon. It's an indulgent, restaurant-worthy dish that's well worth the slower cooking time.",
    ingredientsList:["4 large onions, thinly sliced","6 cups beef broth","3 tbsp butter","4 slices baguette, toasted","1.5 cups grated gruyère cheese"],
    steps:["Melt butter in a large pot and cook the onions over low heat for 30-40 minutes, stirring occasionally, until deeply caramelized.","Pour in the beef broth and simmer for 15-20 minutes.","Ladle the soup into oven-safe bowls and top each with a slice of toasted baguette.","Sprinkle generously with grated gruyère cheese.","Broil until the cheese is melted and bubbly, then serve immediately."] },
  { name:"Butternut Squash Soup", cuisine:"American", ingredients:"Squash, cream, nutmeg", mood:"Cozy & Autumnal", difficulty:"Easy", why:"A silky soup that tastes like fall in a bowl.", mainBase:"Soup", image:"images/butternut-squash-soup.png", description:"Roasted butternut squash is blended until silky smooth, then gently spiced with warm nutmeg and finished with a touch of cream for extra body. Roasting the squash first deepens its natural sweetness and adds a subtle caramelized flavor you can't get from boiling alone. This velvety soup captures the essence of autumn in a single comforting bowl.",
    ingredientsList:["1 large butternut squash, cubed","1 onion, diced","1/4 tsp nutmeg","1/2 cup cream","4 cups vegetable broth","2 tbsp olive oil"],
    steps:["Toss the squash cubes with olive oil and roast at 200°C (400°F) for 30 minutes until tender and caramelized.","Sauté the onion in a pot until softened.","Add the roasted squash and vegetable broth, and simmer for 10 minutes.","Blend until smooth, then stir in the nutmeg and cream.","Warm through gently, season to taste, and serve."] },

  { name:"Thai Coconut Soup", cuisine:"Thai", ingredients:"Coconut milk, chicken, mushroom, lime", mood:"Creamy & Fragrant", difficulty:"Easy", why:"A soothing coconut broth with bright lime and gentle heat.", mainBase:"Soup", image:"images/thai-coconut-soup.png", description:"Thai coconut soup is creamy, aromatic, and surprisingly quick. Coconut milk softens the heat of chili while lime, herbs, and mushrooms keep the broth fresh. Tender chicken pieces make it filling enough for dinner without losing its light, fragrant character.",
    ingredientsList:["1 can coconut milk","3 cups chicken broth","250g chicken breast, sliced","1 cup mushrooms, sliced","1 stalk lemongrass, bruised","1 lime, juiced","1 tbsp fish sauce or soy sauce","cilantro and chili oil, to serve"],
    steps:["Simmer coconut milk, broth, and lemongrass for 8 minutes.","Add chicken and mushrooms and cook until the chicken is done.","Season with fish sauce or soy sauce and lime juice.","Remove the lemongrass before serving.","Top with cilantro and a few drops of chili oil."] },
  { name:"Roasted Red Pepper Soup", cuisine:"Mediterranean", ingredients:"Roasted red pepper, tomato, basil, cream", mood:"Velvety & Bright", difficulty:"Easy", why:"A smooth red-orange soup with sweet roasted pepper flavor.", mainBase:"Soup", image:"images/roasted-red-pepper-soup.png", description:"Roasted red peppers blend with tomato and garlic into a smooth, colorful soup that tastes both sweet and savory. A small swirl of cream rounds out the acidity, while basil adds freshness. It is simple, cheerful, and perfect with toasted bread.",
    ingredientsList:["3 roasted red peppers","1 can crushed tomatoes","2 cups vegetable broth","2 cloves garlic","1 small onion, diced","1/4 cup cream","fresh basil","2 tbsp olive oil"],
    steps:["Saute onion and garlic in olive oil until soft.","Add roasted peppers, crushed tomatoes, and broth.","Simmer for 15 minutes to let the flavors blend.","Blend until smooth, then stir in cream.","Serve with basil, black pepper, and toasted bread."] },
  { name:"Clam Chowder", cuisine:"American", ingredients:"Clams, potato, celery, cream", mood:"Creamy & Coastal", difficulty:"Medium", why:"A cozy seafood soup with rich, savory depth.", mainBase:"Soup", image:"images/clam-chowder.webp", description:"Tender clams, diced potatoes, celery, and onion simmer into a creamy chowder that feels both coastal and deeply comforting. Bacon adds a smoky backbone while the potatoes give the broth body without making it heavy. It is the kind of bowl that tastes best with crusty bread and a quiet evening.",
    ingredientsList:["500g clams or clam meat","2 potatoes, diced","3 slices bacon, chopped","1 onion, diced","2 celery stalks, diced","2 cups milk or cream","2 cups seafood or chicken broth","fresh chives"],
    steps:["Cook bacon in a soup pot until crisp, then set aside a little for garnish.","Saute onion and celery in the bacon fat until softened.","Add potatoes and broth, then simmer until the potatoes are tender.","Stir in clams and milk or cream, warming gently without boiling hard.","Season to taste and finish with bacon and chives."] },
  { name:"Mushroom Barley Soup", cuisine:"Eastern European", ingredients:"Mushroom, barley, carrot, broth", mood:"Earthy & Hearty", difficulty:"Easy", why:"Chewy barley and mushrooms make it filling without feeling heavy.", mainBase:"Soup", image:"images/mushroom-barley-soup.webp", description:"Sliced mushrooms are browned until deeply savory, then simmered with pearl barley, carrots, celery, and broth. The barley turns tender and slightly chewy, giving the soup a satisfying texture that makes it feel like a full meal. It is earthy, humble, and wonderfully restorative.",
    ingredientsList:["300g mushrooms, sliced","1 cup pearl barley","1 carrot, diced","1 celery stalk, diced","1 onion, diced","5 cups vegetable broth","2 tbsp olive oil","fresh parsley"],
    steps:["Brown the mushrooms in olive oil until their moisture cooks off.","Add onion, carrot, and celery and cook until softened.","Stir in barley and broth, then bring to a simmer.","Cook for 35-40 minutes until the barley is tender.","Season well and finish with chopped parsley."] },
  { name:"Avgolemono Soup", cuisine:"Greek", ingredients:"Chicken, rice, egg, lemon", mood:"Bright & Comforting", difficulty:"Medium", why:"Lemon and egg turn simple broth into something silky and special.", mainBase:"Soup", image:"images/avgolemono-soup.webp", description:"Avgolemono turns chicken broth, rice, eggs, and lemon into a silky Greek soup that tastes both comforting and bright. The egg mixture is gently tempered so it thickens the broth without scrambling. Each spoonful is creamy without cream, with fresh lemon lifting the whole bowl.",
    ingredientsList:["2 cups cooked chicken, shredded","1/2 cup rice","5 cups chicken broth","2 eggs","2 lemons, juiced","fresh dill","black pepper"],
    steps:["Simmer rice in chicken broth until tender.","Stir in shredded chicken and warm through.","Whisk eggs and lemon juice in a bowl until smooth.","Slowly whisk hot broth into the egg mixture to temper it.","Return the mixture to the pot on low heat, stir until silky, and finish with dill."] },
  { name:"Sundubu Jjigae", cuisine:"Korean", ingredients:"Soft tofu, seafood, egg, chili broth", mood:"Spicy & Warming", difficulty:"Medium", why:"Soft tofu and spicy broth make every spoonful bold and soothing.", mainBase:"Soup", image:"images/sundubu-jjigae.webp", description:"This Korean soft tofu stew is bold, bubbling, and packed with savory chili warmth. Silken tofu slips into a red broth with seafood, scallions, sesame oil, and an egg cracked in at the end. It is fiery enough to wake up dinner but still deeply comforting.",
    ingredientsList:["300g silken tofu","150g seafood mix","1 egg","3 cups broth","1 tbsp gochugaru","1 tbsp soy sauce","2 scallions","1 tsp sesame oil"],
    steps:["Toast gochugaru briefly in sesame oil in a small pot.","Add broth and soy sauce, then bring to a lively simmer.","Add seafood and cook until just done.","Spoon in silken tofu in large pieces and simmer gently.","Crack in the egg, scatter scallions over the top, and serve bubbling hot."] },
  { name:"Split Pea Soup", cuisine:"American", ingredients:"Split peas, carrot, ham, broth", mood:"Cozy & Rustic", difficulty:"Easy", why:"A budget-friendly classic that turns simple pantry staples into comfort.", mainBase:"Soup", image:"images/split-pea-soup.webp", description:"Split peas simmer down into a thick, velvety soup with carrots, celery, onion, and a smoky hint of ham. The peas naturally thicken the broth, so the finished bowl feels hearty with very little fuss. A few croutons or fresh herbs on top add just the right contrast.",
    ingredientsList:["1.5 cups split peas","1 carrot, diced","1 celery stalk, diced","1 onion, diced","150g ham, optional","5 cups broth","1 bay leaf","fresh parsley"],
    steps:["Rinse split peas and add them to a pot with broth and bay leaf.","Add carrot, celery, onion, and ham if using.","Simmer for 45-60 minutes until the peas break down.","Stir often near the end so the soup does not stick.","Remove the bay leaf, season to taste, and finish with parsley."] },
  { name:"Carrot Ginger Soup", cuisine:"Modern Bistro", ingredients:"Carrot, ginger, coconut milk, broth", mood:"Silky & Bright", difficulty:"Easy", why:"Sweet carrots and fresh ginger make it sunny and warming.", mainBase:"Soup", image:"images/carrot-ginger-soup.webp", description:"Carrots are simmered until tender with fresh ginger, onion, and broth, then blended into a smooth orange soup. Coconut milk adds a soft, creamy finish while ginger keeps each spoonful lively. It is clean, colorful, and light enough for lunch while still feeling cozy.",
    ingredientsList:["700g carrots, sliced","1 onion, diced","2 tbsp fresh ginger, grated","4 cups vegetable broth","1/2 cup coconut milk","pumpkin seeds","2 tbsp olive oil"],
    steps:["Saute onion and ginger in olive oil until fragrant.","Add carrots and broth, then simmer until the carrots are very tender.","Blend until completely smooth.","Stir in coconut milk and warm gently.","Top with pumpkin seeds and a small drizzle of olive oil."] },
  { name:"Broccoli Cheddar Soup", cuisine:"American", ingredients:"Broccoli, cheddar, milk, broth", mood:"Creamy & Familiar", difficulty:"Easy", why:"A cheesy comfort bowl that still brings plenty of green.", mainBase:"Soup", image:"images/broccoli-cheddar-soup.webp", description:"Broccoli cheddar soup balances creamy richness with plenty of tender green florets. A simple roux gives the broth body, while shredded cheddar melts in at the end for a smooth, savory finish. It is familiar, generous, and perfect with toasted bread.",
    ingredientsList:["4 cups broccoli florets","1 carrot, shredded","1 onion, diced","3 cups broth","1 cup milk","1.5 cups cheddar, shredded","2 tbsp butter","2 tbsp flour"],
    steps:["Melt butter and cook onion until soft.","Stir in flour and cook for 1 minute.","Whisk in broth and milk until smooth.","Add broccoli and carrot, then simmer until tender.","Lower the heat, stir in cheddar, and season to taste."] },
  { name:"Cioppino Seafood Stew", cuisine:"Italian-American", ingredients:"Seafood, tomato, fennel, herbs", mood:"Bold & Coastal", difficulty:"Medium", why:"A dramatic seafood stew that still cooks surprisingly fast.", mainBase:"Soup", image:"images/cioppino-seafood-stew.webp", description:"Cioppino is a tomato-rich seafood stew loaded with mussels, shrimp, and tender white fish. Garlic, fennel, and herbs build a fragrant base before the seafood cooks quickly in the simmering broth. It feels special enough for guests but stays relaxed and rustic at the table.",
    ingredientsList:["300g mussels","250g shrimp","250g white fish","1 can crushed tomatoes","3 cups seafood broth","1 fennel bulb or onion, sliced","3 cloves garlic","fresh parsley"],
    steps:["Saute fennel or onion with garlic until fragrant.","Add crushed tomatoes and seafood broth, then simmer for 15 minutes.","Add white fish and shrimp and cook until almost done.","Add mussels, cover, and cook until they open.","Discard unopened mussels and finish with parsley."] },
  { name:"Harira Soup", cuisine:"Moroccan", ingredients:"Chickpeas, lentils, tomato, cumin", mood:"Spiced & Nourishing", difficulty:"Easy", why:"Chickpeas, lentils, and warm spices make it deeply satisfying.", mainBase:"Soup", image:"images/harira-soup.webp", description:"Harira is a Moroccan tomato soup filled with chickpeas, lentils, vegetables, and warm spices. Cumin and cinnamon give the broth depth while cilantro and lemon keep it fresh. It is hearty without being heavy, making it a nourishing bowl for any season.",
    ingredientsList:["1 can chickpeas","1/2 cup lentils","1 can diced tomatoes","1 onion, diced","1 celery stalk, diced","1 tsp cumin","1/2 tsp cinnamon","fresh cilantro","lemon wedges"],
    steps:["Saute onion and celery until softened.","Add cumin and cinnamon and cook until fragrant.","Stir in tomatoes, lentils, chickpeas, and enough water or broth to cover.","Simmer until the lentils are tender.","Finish with cilantro and lemon juice."] },
  { name:"White Bean Kale Soup", cuisine:"Mediterranean", ingredients:"White beans, kale, carrot, rosemary", mood:"Clean & Restorative", difficulty:"Easy", why:"Beans make it creamy and filling while kale keeps it fresh.", mainBase:"Soup", image:"images/white-bean-kale-soup.webp", description:"White beans and kale simmer in a savory broth with carrots, garlic, rosemary, and olive oil. Some of the beans soften into the broth, giving it a gentle creaminess without needing cream. It is simple, nourishing, and exactly the kind of soup that feels good to eat.",
    ingredientsList:["2 cans cannellini beans","3 cups kale, chopped","1 carrot, diced","1 onion, diced","2 cloves garlic","5 cups broth","1 tsp rosemary","olive oil"],
    steps:["Saute onion, carrot, and garlic in olive oil until softened.","Add beans, rosemary, and broth, then simmer for 15 minutes.","Mash a small portion of the beans to thicken the broth.","Stir in kale and cook until tender.","Season with salt, pepper, and a final drizzle of olive oil."] },
  { name:"Pumpkin Coconut Soup", cuisine:"Thai-Inspired", ingredients:"Pumpkin, coconut milk, curry, seeds", mood:"Silky & Aromatic", difficulty:"Easy", why:"Pumpkin sweetness, coconut creaminess, and gentle spice work beautifully together.", mainBase:"Soup", image:"images/pumpkin-coconut-soup.webp", description:"Pumpkin or squash blends into a golden soup with coconut milk, garlic, onion, and a touch of curry. The result is smooth, fragrant, and lightly sweet, with toasted seeds adding crunch. A few drops of chili oil make it feel warm and restaurant-polished without much effort.",
    ingredientsList:["700g pumpkin or squash, cubed","1 can coconut milk","1 onion, diced","2 cloves garlic","1 tbsp curry paste or curry powder","4 cups broth","pumpkin seeds","chili oil"],
    steps:["Saute onion and garlic until soft.","Stir in curry paste or powder and cook briefly.","Add pumpkin and broth, then simmer until tender.","Blend until smooth and stir in coconut milk.","Serve with pumpkin seeds and a little chili oil."] },
  { name:"Matzo Ball Soup", cuisine:"Jewish", ingredients:"Matzo balls, chicken broth, carrot, dill", mood:"Tender & Nostalgic", difficulty:"Medium", why:"Fluffy matzo balls turn clear broth into a beloved comfort meal.", mainBase:"Soup", image:"images/matzo-ball-soup.webp", description:"Golden chicken broth holds tender matzo balls, sliced carrots, celery, and plenty of fresh dill. The broth stays clear and soothing while the matzo balls make the bowl feel generous. It is classic comfort food with a clean, gentle flavor.",
    ingredientsList:["8 matzo balls","6 cups chicken broth","2 carrots, sliced","2 celery stalks, sliced","2 cups shredded chicken, optional","fresh dill","black pepper"],
    steps:["Bring chicken broth to a simmer with carrots and celery.","Cook until the vegetables are tender.","Add prepared matzo balls and warm them through gently.","Stir in shredded chicken if using.","Finish with dill and black pepper before serving."] },
  { name:"Beef Barley Soup", cuisine:"American", ingredients:"Beef, barley, carrot, celery", mood:"Hearty & Savory", difficulty:"Medium", why:"Slow-simmered beef and chewy barley make it deeply satisfying.", mainBase:"Soup", image:"images/beef-barley-soup.webp", description:"Beef barley soup is built on browned beef, vegetables, and broth simmered until the meat turns tender. Pearl barley adds a chewy, nutty texture that makes the bowl especially filling. It is robust, savory, and ideal for cooler days.",
    ingredientsList:["400g beef chuck, cubed","3/4 cup barley","1 carrot, diced","1 celery stalk, diced","1 onion, diced","5 cups beef broth","1 tbsp tomato paste","fresh parsley"],
    steps:["Brown beef cubes in a heavy pot, then remove briefly.","Saute onion, carrot, and celery until softened.","Stir in tomato paste, beef, broth, and barley.","Simmer for 60-75 minutes until the beef and barley are tender.","Season to taste and finish with parsley."] },
  { name:"Sopa de Fideo", cuisine:"Mexican", ingredients:"Fideo noodles, tomato, broth, lime", mood:"Simple & Cheerful", difficulty:"Easy", why:"Toasted noodles in tomato broth make a quick, comforting bowl.", mainBase:"Soup", image:"images/sopa-de-fideo.webp", description:"Sopa de fideo starts by toasting short noodles until golden, then simmering them in a bright tomato broth. The noodles absorb the savory flavor as they soften, creating a quick and cozy soup. Avocado, cilantro, and lime make the finish fresh and colorful.",
    ingredientsList:["200g fideo or broken vermicelli","1 can tomatoes","1/2 onion","2 cloves garlic","4 cups chicken broth","1 avocado, sliced","fresh cilantro","lime wedges"],
    steps:["Toast fideo noodles in a little oil until lightly golden.","Blend tomatoes, onion, and garlic until smooth.","Pour the tomato mixture into the pot and simmer briefly.","Add broth and cook until the noodles are tender.","Serve with avocado, cilantro, and lime."] },
  { name:"Creamy Asparagus Soup", cuisine:"French-Inspired", ingredients:"Asparagus, leek, cream, herbs", mood:"Elegant & Fresh", difficulty:"Easy", why:"A light green soup that feels polished but cooks quickly.", mainBase:"Soup", image:"images/creamy-asparagus-soup.webp", description:"Fresh asparagus and leek simmer into a pale green soup that tastes delicate, clean, and springlike. A splash of cream rounds the edges while lemon keeps it from feeling heavy. It is elegant enough for a starter and simple enough for a weekday lunch.",
    ingredientsList:["2 bunches asparagus","1 leek or onion, sliced","3 cups broth","1/2 cup cream","2 tbsp butter","lemon juice","fresh herbs"],
    steps:["Trim asparagus and reserve a few tips for garnish.","Cook leek or onion in butter until soft.","Add asparagus and broth, then simmer until tender.","Blend until smooth and stir in cream.","Season with lemon juice and garnish with asparagus tips and herbs."] },
  // ---------------- SALAD / BOWL ----------------
  { name:"Greek Salad", cuisine:"Greek", ingredients:"Cucumber, tomato, feta, olives, olive oil", mood:"Fresh & Light", difficulty:"Easy", why:"A crisp, no-cook salad ready in under 10 minutes.", mainBase:"Salad", image:"images/greek-salad.png", description:"Crisp cucumber, juicy tomatoes, and briny Kalamata olives are tossed together with thick slabs of tangy feta cheese and a generous drizzle of good olive oil. No lettuce needed here — the vegetables themselves are the star, kept simple so their fresh flavors truly shine through. It's a refreshing, no-cook salad that comes together in minutes and tastes even better with a squeeze of lemon.",
    ingredientsList:["2 cucumbers, chopped","3 tomatoes, chopped","200g feta cheese, sliced","1/2 cup Kalamata olives","1/4 red onion, thinly sliced","3 tbsp olive oil","1 tsp dried oregano"],
    steps:["Combine cucumber, tomato, red onion, and olives in a large bowl.","Top with the sliced feta cheese.","Drizzle generously with olive oil.","Sprinkle with dried oregano.","Toss gently just before serving to keep the feta intact."] },
  { name:"Chicken Caesar Salad", cuisine:"American", ingredients:"Romaine, chicken, parmesan, croutons", mood:"Satisfying & Classic", difficulty:"Easy", why:"A protein-packed salad that actually keeps you full.", mainBase:"Salad", image:"images/chicken-caesar-salad.png", description:"Crisp romaine lettuce is tossed in a creamy, garlicky Caesar dressing, then topped with juicy grilled chicken, shaved parmesan, and crunchy croutons for contrast. Unlike lighter salads, the protein and satisfying crunch make this one hearty enough to keep you full well past lunchtime. It's a timeless classic that proves salads don't have to feel like a compromise.",
    ingredientsList:["1 head romaine lettuce, chopped","2 chicken breasts, grilled and sliced","1/2 cup shaved parmesan","1 cup croutons","1/2 cup Caesar dressing"],
    steps:["Season and grill the chicken breasts until cooked through; let rest, then slice.","Toss the chopped romaine with Caesar dressing in a large bowl.","Add the croutons and toss again lightly.","Top with the sliced grilled chicken.","Finish with shaved parmesan before serving."] },
  { name:"Buddha Bowl", cuisine:"American Fusion", ingredients:"Quinoa, chickpeas, avocado, kale", mood:"Nourishing & Balanced", difficulty:"Easy", why:"A colorful, customizable bowl that's as healthy as it is pretty.", mainBase:"Salad", image:"images/buddha-bowl.png", description:"Fluffy quinoa forms the base for this nourishing bowl, topped with crispy roasted chickpeas, creamy avocado slices, and hearty massaged kale. Every component is chosen for both nutrition and color, making the final bowl as beautiful to look at as it is satisfying to eat. It's endlessly customizable, so you can swap in whatever grains, greens, or proteins you have on hand.",
    ingredientsList:["1 cup quinoa, cooked","1 can chickpeas, drained","1 avocado, sliced","2 cups kale, massaged with olive oil","2 tbsp olive oil","1 tsp paprika"],
    steps:["Toss chickpeas with olive oil and paprika, then roast at 200°C (400°F) for 20 minutes until crispy.","Massage the kale with a little olive oil and a pinch of salt until softened.","Divide the cooked quinoa between bowls as the base.","Arrange the kale, roasted chickpeas, and sliced avocado on top.","Drizzle with your favorite dressing before serving."] },
  { name:"Poke Bowl", cuisine:"Hawaiian", ingredients:"Rice, ahi tuna, avocado, soy sauce", mood:"Fresh & Vibrant", difficulty:"Easy", why:"A restaurant-style bowl you can build at home in minutes.", mainBase:"Salad", image:"images/poke-bowl.png", description:"Cubes of fresh ahi tuna are marinated briefly in soy sauce and sesame oil, then served over a bed of warm rice with creamy avocado and your favorite crunchy toppings. The dish celebrates the natural quality of the fish, so freshness matters more than complicated technique. It's a vibrant, restaurant-style bowl that's surprisingly simple to recreate in your own kitchen.",
    ingredientsList:["300g sushi-grade ahi tuna, cubed","2 cups cooked rice","1 avocado, diced","3 tbsp soy sauce","1 tsp sesame oil","1 tbsp sesame seeds","1 scallion, sliced"],
    steps:["Combine soy sauce and sesame oil in a bowl.","Add the cubed tuna and marinate for 10-15 minutes in the fridge.","Divide the warm rice between bowls.","Top with the marinated tuna and diced avocado.","Garnish with sesame seeds and sliced scallion before serving."] },
  { name:"Cobb Salad", cuisine:"American", ingredients:"Lettuce, egg, bacon, avocado, blue cheese", mood:"Hearty & Filling", difficulty:"Easy", why:"A protein-loaded salad that doubles as a full meal.", mainBase:"Salad", image:"images/cobb-salad.png", description:"Neat rows of hard-boiled egg, crispy bacon, creamy avocado, and tangy blue cheese are arranged over a bed of crisp lettuce, creating a salad that's as visually striking as it is filling. Each element brings its own distinct flavor and texture, so every forkful tastes a little different. It's hearty enough to serve as a complete meal rather than just a side.",
    ingredientsList:["1 head lettuce, chopped","3 eggs, hard-boiled and sliced","4 strips bacon, cooked and crumbled","1 avocado, sliced","1/2 cup crumbled blue cheese","2 tomatoes, diced"],
    steps:["Arrange the chopped lettuce as the base on a large platter.","Arrange rows of sliced egg, crumbled bacon, diced tomato, sliced avocado, and blue cheese on top.","Keep each ingredient in its own neat row for the classic Cobb presentation.","Drizzle with your favorite vinaigrette.","Toss just before serving, or serve as is for presentation."] },
  { name:"Quinoa Power Bowl", cuisine:"American", ingredients:"Quinoa, roasted vegetables, tahini", mood:"Energizing & Wholesome", difficulty:"Easy", why:"A meal-prep favorite that's just as good the next day.", mainBase:"Salad", image:"images/quinoa-power-bowl.png", description:"Protein-rich quinoa is paired with a colorful medley of roasted seasonal vegetables, then finished with a creamy, nutty tahini drizzle that ties everything together. Because it holds up so well in the fridge, it's a favorite for meal prepping ahead of a busy week. Wholesome, energizing, and satisfying, it tastes just as good cold the next day as it does freshly made.",
    ingredientsList:["1 cup quinoa, cooked","1 zucchini, chopped","1 red bell pepper, chopped","1 cup cherry tomatoes","3 tbsp tahini","1 lemon, juiced","2 tbsp olive oil"],
    steps:["Toss the zucchini, bell pepper, and cherry tomatoes with olive oil.","Roast at 200°C (400°F) for 20-25 minutes until tender and slightly caramelized.","Whisk together tahini, lemon juice, and a splash of water to make the dressing.","Divide the cooked quinoa between bowls and top with the roasted vegetables.","Drizzle with the tahini dressing before serving."] },
  { name:"Caprese Salad", cuisine:"Italian", ingredients:"Tomato, mozzarella, basil, balsamic", mood:"Light & Elegant", difficulty:"Easy", why:"A simple 4-ingredient salad that always looks impressive.", mainBase:"Salad", image:"images/caprese-salad.png", description:"Thick slices of ripe tomato and fresh mozzarella are layered together with fragrant basil leaves, then finished with a drizzle of sweet-tangy balsamic glaze and good olive oil. With only four main ingredients, the quality of each one really matters, so this is the perfect dish to make when tomatoes are at their peak. It's simple, elegant, and always looks impressive on the table.",
    ingredientsList:["3 large ripe tomatoes, sliced","250g fresh mozzarella, sliced","handful of fresh basil leaves","2 tbsp balsamic glaze","2 tbsp olive oil","salt and pepper to taste"],
    steps:["Arrange alternating slices of tomato and mozzarella on a platter.","Tuck fresh basil leaves between the slices.","Drizzle with olive oil and balsamic glaze.","Season with salt and freshly cracked pepper.","Serve immediately at room temperature for the best flavor."] },
  { name:"Asian Chicken Salad Bowl", cuisine:"Asian Fusion", ingredients:"Cabbage, chicken, sesame dressing, almonds", mood:"Crunchy & Zesty", difficulty:"Easy", why:"A crunchy, flavor-packed salad that's a lunchbox favorite.", mainBase:"Salad", image:"images/asian-chicken-salad-bowl.png", description:"Crisp shredded cabbage and tender chicken are tossed together in a nutty, tangy sesame dressing, then topped with toasted almonds for extra crunch. The dressing is bold enough to stand up to the crisp vegetables without wilting them, so it holds up beautifully even after a few hours in a packed lunch. It's a zesty, flavor-packed salad that makes eating your veggies genuinely exciting.",
    ingredientsList:["4 cups shredded cabbage","2 cooked chicken breasts, shredded","1/4 cup sliced almonds, toasted","3 tbsp sesame dressing","1 carrot, julienned","2 scallions, sliced"],
    steps:["Combine shredded cabbage, carrot, and scallions in a large bowl.","Add the shredded chicken on top.","Drizzle with sesame dressing and toss well to coat.","Sprinkle with toasted almonds.","Serve immediately, or pack for a lunchbox that holds up for hours."] },

  { name:"Mediterranean Couscous Salad", cuisine:"Mediterranean", ingredients:"Couscous, cucumber, tomato, chickpeas, feta", mood:"Fresh & Filling", difficulty:"Easy", why:"A bright grain salad that works for lunch, dinner, or meal prep.", mainBase:"Salad", image:"images/mediterranean-couscous-salad.png", description:"Pearl couscous gives this salad a tender, satisfying base, while cucumber, tomatoes, chickpeas, feta, and olives bring freshness and color. Lemon dressing keeps it lively and clean. It holds up well in the fridge, making it a strong choice for meal prep.",
    ingredientsList:["2 cups cooked pearl couscous","1 cup cucumber, diced","1 cup cherry tomatoes, halved","1 can chickpeas, drained","1/2 cup crumbled feta","1/3 cup olives","2 tbsp olive oil","1 lemon, juiced"],
    steps:["Cook couscous according to package directions and cool slightly.","Combine couscous with cucumber, tomatoes, chickpeas, feta, and olives.","Whisk olive oil with lemon juice, salt, and pepper.","Toss the salad with the dressing until evenly coated.","Chill briefly or serve at room temperature with extra herbs."] },
  { name:"Thai Mango Salad", cuisine:"Thai", ingredients:"Mango, carrot, cucumber, herbs, peanuts", mood:"Crisp & Zesty", difficulty:"Easy", why:"A crunchy salad with sweet mango, lime, herbs, and peanuts.", mainBase:"Salad", image:"images/thai-mango-salad.png", description:"Thai mango salad is crisp, bright, and full of contrast. Julienned mango, carrot, and cucumber are tossed with herbs, peanuts, lime, and a light chili dressing. It is refreshing enough for hot days and bold enough to stand beside grilled mains.",
    ingredientsList:["2 firm mangoes, julienned","1 carrot, julienned","1 cucumber, julienned","1/3 cup roasted peanuts, chopped","fresh cilantro and mint","1 lime, juiced","1 tbsp fish sauce or soy sauce","1 tsp sugar"],
    steps:["Whisk lime juice, fish sauce or soy sauce, sugar, and chili to make the dressing.","Combine mango, carrot, cucumber, and herbs in a large bowl.","Pour over the dressing and toss gently.","Add chopped peanuts just before serving.","Taste and adjust with more lime if needed."] },
  { name:"Watermelon Feta Salad", cuisine:"Mediterranean", ingredients:"Watermelon, feta, cucumber, mint", mood:"Juicy & Refreshing", difficulty:"Easy", why:"Sweet watermelon, salty feta, and mint make a bright summer bowl.", mainBase:"Salad", image:"images/watermelon-feta-salad.webp", description:"Watermelon feta salad is crisp, juicy, and built for warm days. Sweet watermelon cubes meet salty feta, cool cucumber, mint, and a simple lime dressing for a salad that tastes clean and lively. It is fast to assemble and looks beautiful with almost no effort.",
    ingredientsList:["4 cups watermelon, cubed","1 cucumber, ribboned or sliced","1/2 cup feta, crumbled","1/4 cup fresh mint","1 lime, juiced","2 tbsp olive oil","black pepper"],
    steps:["Combine watermelon and cucumber in a large bowl.","Whisk lime juice with olive oil and a pinch of salt.","Drizzle the dressing over the salad and toss gently.","Scatter feta and mint over the top.","Finish with black pepper and serve chilled."] },
  { name:"Roasted Beet Goat Cheese Salad", cuisine:"Modern Bistro", ingredients:"Beet, goat cheese, arugula, walnut", mood:"Earthy & Elegant", difficulty:"Easy", why:"Roasted beets and creamy goat cheese feel restaurant-ready.", mainBase:"Salad", image:"images/roasted-beet-goat-cheese-salad.webp", description:"Roasted beets bring earthy sweetness to peppery arugula, creamy goat cheese, toasted walnuts, and a glossy balsamic drizzle. Orange segments add brightness so the salad feels balanced instead of heavy. It is colorful, polished, and satisfying as a starter or light lunch.",
    ingredientsList:["4 roasted beets, cut into wedges","4 cups arugula","1/2 cup goat cheese","1/3 cup walnuts, toasted","1 orange, segmented","2 tbsp balsamic glaze","2 tbsp olive oil"],
    steps:["Arrange arugula on a large plate or shallow bowl.","Add roasted beet wedges and orange segments.","Scatter goat cheese and walnuts over the top.","Drizzle with olive oil and balsamic glaze.","Season with salt and pepper before serving."] },
  { name:"Kale Apple Walnut Salad", cuisine:"American", ingredients:"Kale, apple, walnut, cranberry", mood:"Crunchy & Wholesome", difficulty:"Easy", why:"Massaged kale turns tender while apples and walnuts add crunch.", mainBase:"Salad", image:"images/kale-apple-walnut-salad.webp", description:"This kale salad is hearty enough for meal prep but still fresh and bright. Massaging the kale with lemon dressing softens the leaves, while apple slices, walnuts, cranberries, and shaved parmesan add layers of sweet, salty, and crunchy texture. It holds up beautifully in the fridge.",
    ingredientsList:["1 bunch kale, chopped","1 apple, thinly sliced","1/3 cup walnuts, toasted","1/4 cup dried cranberries","1/3 cup shaved parmesan","1 lemon, juiced","3 tbsp olive oil"],
    steps:["Whisk lemon juice, olive oil, salt, and pepper.","Massage the dressing into chopped kale until the leaves soften.","Add apple slices, walnuts, and cranberries.","Toss gently to combine.","Finish with shaved parmesan before serving."] },
  { name:"Southwest Black Bean Salad", cuisine:"Tex-Mex", ingredients:"Black beans, corn, avocado, romaine", mood:"Zesty & Colorful", difficulty:"Easy", why:"Beans, corn, avocado, and lime make it filling and bright.", mainBase:"Salad", image:"images/southwest-black-bean-salad.webp", description:"Black beans, roasted corn, avocado, tomatoes, and romaine come together in a colorful salad with a cilantro lime dressing. Tortilla strips add crunch and make the bowl feel fun without weighing it down. It is quick, flexible, and hearty enough for lunch.",
    ingredientsList:["1 can black beans, drained","1 cup corn kernels","1 avocado, diced","2 cups romaine, chopped","1 cup cherry tomatoes, halved","1/4 red onion, diced","cilantro lime dressing","tortilla strips"],
    steps:["Combine romaine, black beans, corn, tomatoes, and red onion in a bowl.","Add diced avocado just before serving.","Drizzle with cilantro lime dressing.","Toss gently so the avocado stays intact.","Top with tortilla strips for crunch."] },
  { name:"Falafel Salad Bowl", cuisine:"Middle Eastern", ingredients:"Falafel, hummus, cucumber, tahini", mood:"Crispy & Nourishing", difficulty:"Medium", why:"Crispy falafel and creamy hummus make salad feel like a full meal.", mainBase:"Salad", image:"images/falafel-salad-bowl.webp", description:"Crispy falafel turns a simple salad into a generous, satisfying bowl. Hummus, cucumber, tomato, pickled onion, herbs, and tahini bring creaminess, crunch, and brightness in every bite. It is fresh, filling, and easy to customize with whatever greens you have.",
    ingredientsList:["6 falafel balls","2 cups romaine, chopped","1/2 cup hummus","1 cucumber, diced","1 tomato, diced","1/4 cup pickled red onion","2 tbsp tahini","fresh parsley"],
    steps:["Spread hummus along one side of a shallow bowl.","Add romaine, cucumber, tomato, and pickled onion.","Place warm falafel on top.","Drizzle with tahini.","Finish with parsley and serve immediately."] },
  { name:"Taco Salad Bowl", cuisine:"Mexican-American", ingredients:"Beef, romaine, beans, tortilla chips", mood:"Bold & Satisfying", difficulty:"Easy", why:"All the taco-night flavors in a crisp, colorful bowl.", mainBase:"Salad", image:"images/taco-salad-bowl.webp", description:"Taco salad turns seasoned beef, crisp romaine, beans, corn, avocado, cheese, and tortilla chips into a lively dinner bowl. The contrast of warm beef and cool vegetables makes it especially satisfying. It is casual, colorful, and perfect when you want taco flavors with extra crunch.",
    ingredientsList:["250g ground beef","1 tbsp taco seasoning","3 cups romaine, chopped","1/2 cup black beans","1/2 cup corn","1 avocado, diced","1/2 cup shredded cheese","tortilla chips"],
    steps:["Cook ground beef with taco seasoning until browned.","Arrange romaine in a large bowl.","Add beans, corn, avocado, cheese, and tomatoes if using.","Spoon warm beef over the salad.","Top with tortilla chips and your favorite dressing or salsa."] },
  { name:"Grilled Halloumi Salad", cuisine:"Mediterranean", ingredients:"Halloumi, arugula, cucumber, tomato", mood:"Salty & Bright", difficulty:"Easy", why:"Golden halloumi adds warm, savory contrast to crisp greens.", mainBase:"Salad", image:"images/grilled-halloumi-salad.webp", description:"Grilled halloumi gives this salad a warm, salty, golden centerpiece. Arugula, cucumber, tomatoes, olives, lemon, and herbs keep the bowl fresh and sharp around the rich cheese. It is simple but feels special, especially served while the halloumi is still warm.",
    ingredientsList:["200g halloumi, sliced","3 cups arugula","1 cucumber, sliced","1 cup cherry tomatoes, halved","1/3 cup olives","1 lemon, juiced","2 tbsp olive oil","fresh herbs"],
    steps:["Grill or sear halloumi slices until golden on both sides.","Combine arugula, cucumber, tomatoes, and olives in a bowl.","Whisk lemon juice with olive oil, salt, and pepper.","Toss the salad with the dressing.","Top with warm halloumi and herbs."] },
  { name:"Pearl Barley Harvest Salad", cuisine:"American", ingredients:"Barley, squash, kale, pomegranate", mood:"Nutty & Autumnal", difficulty:"Easy", why:"Chewy barley and roasted squash make a cozy grain salad.", mainBase:"Salad", image:"images/pearl-barley-harvest-salad.webp", description:"Pearl barley gives this harvest salad a chewy, nutty base that pairs beautifully with roasted squash, kale, pomegranate, pecans, and feta. A lightly sweet vinaigrette ties the warm and fresh elements together. It is colorful, sturdy, and great for meal prep.",
    ingredientsList:["2 cups cooked pearl barley","2 cups roasted squash cubes","2 cups kale, chopped","1/3 cup pomegranate seeds","1/3 cup pecans","1/2 cup feta","2 tbsp olive oil","1 tbsp maple syrup"],
    steps:["Cook barley until tender, then cool slightly.","Massage kale with olive oil and a pinch of salt.","Add barley, roasted squash, pomegranate, pecans, and feta.","Whisk olive oil with maple syrup and vinegar or lemon juice.","Toss everything together and serve warm or chilled."] },
  { name:"Vietnamese Vermicelli Salad Bowl", cuisine:"Vietnamese", ingredients:"Vermicelli, chicken, cucumber, herbs", mood:"Fresh & Fragrant", difficulty:"Medium", why:"Cool noodles, herbs, and grilled chicken make a bright meal bowl.", mainBase:"Salad", image:"images/vietnamese-vermicelli-salad-bowl.webp", description:"This Vietnamese-inspired bowl layers cool rice vermicelli with grilled lemongrass chicken, cucumber, carrots, herbs, peanuts, lime, and a light dressing. It is fresh, fragrant, and full of texture without feeling heavy. The contrast of warm chicken and cool noodles makes every bite lively.",
    ingredientsList:["200g rice vermicelli","2 chicken breasts, grilled and sliced","1 cucumber, julienned","1 carrot, julienned","fresh mint and cilantro","1/4 cup peanuts, crushed","1 lime","nuoc cham or light dressing"],
    steps:["Cook vermicelli according to package directions, then rinse cool.","Arrange noodles in bowls with cucumber, carrot, and herbs.","Top with sliced grilled chicken.","Drizzle with nuoc cham or a light lime dressing.","Finish with crushed peanuts and lime."] },
  { name:"Tabbouleh Salad", cuisine:"Lebanese", ingredients:"Parsley, bulgur, tomato, lemon", mood:"Herby & Bright", difficulty:"Easy", why:"Parsley, lemon, and tomato make it clean and refreshing.", mainBase:"Salad", image:"images/tabbouleh-salad.webp", description:"Tabbouleh is a parsley-forward salad with bulgur, tomato, cucumber, mint, lemon, and olive oil. The herbs are the main event, making the salad taste intensely fresh and bright. It is excellent as a side, a mezze plate component, or a light lunch with hummus.",
    ingredientsList:["2 cups parsley, finely chopped","1/2 cup cooked bulgur","2 tomatoes, diced","1 cucumber, diced","1/4 cup mint, chopped","2 lemons, juiced","3 tbsp olive oil"],
    steps:["Combine parsley, bulgur, tomatoes, cucumber, and mint.","Whisk lemon juice with olive oil, salt, and pepper.","Pour the dressing over the salad.","Toss thoroughly so the herbs are evenly coated.","Rest for 10 minutes before serving."] },
  { name:"Tuna Nicoise Salad", cuisine:"French", ingredients:"Tuna, egg, green beans, potato", mood:"Classic & Balanced", difficulty:"Medium", why:"Seared tuna, eggs, olives, and potatoes make it elegant and filling.", mainBase:"Salad", image:"images/tuna-nicoise-salad.webp", description:"Tuna Nicoise is a composed French salad with seared tuna, green beans, baby potatoes, boiled eggs, tomatoes, olives, and crisp lettuce. Every element brings a different texture and flavor, so it feels complete without being heavy. A lemony vinaigrette keeps the whole plate bright.",
    ingredientsList:["250g tuna steak","2 boiled eggs, quartered","1 cup green beans, blanched","1 cup baby potatoes, cooked","1 cup cherry tomatoes","1/3 cup olives","4 cups lettuce","lemon vinaigrette"],
    steps:["Season and sear the tuna, then slice it.","Arrange lettuce on a large plate or bowl.","Add green beans, potatoes, eggs, tomatoes, and olives.","Place tuna slices on top.","Drizzle with lemon vinaigrette before serving."] },
  { name:"Sesame Tofu Salad Bowl", cuisine:"Asian Fusion", ingredients:"Tofu, edamame, greens, sesame", mood:"Plant-Powered & Crunchy", difficulty:"Easy", why:"Crispy tofu and sesame dressing make a satisfying meatless bowl.", mainBase:"Salad", image:"images/sesame-tofu-salad-bowl.webp", description:"Crispy tofu cubes sit over greens, cucumber, carrots, edamame, radish, and a sesame ginger dressing. The tofu adds warm, savory texture while the vegetables keep the bowl crisp and colorful. It is a satisfying plant-based lunch that still feels light.",
    ingredientsList:["300g firm tofu, cubed","3 cups mixed greens","1 cucumber, sliced","1 carrot, shredded","1 cup edamame","4 radishes, sliced","sesame ginger dressing","1 tbsp sesame seeds"],
    steps:["Pat tofu dry and pan-fry until golden and crisp.","Arrange greens, cucumber, carrot, edamame, and radish in bowls.","Add warm tofu cubes on top.","Drizzle with sesame ginger dressing.","Finish with sesame seeds."] },
  { name:"Waldorf Chicken Salad", cuisine:"American", ingredients:"Chicken, apple, celery, grape, walnut", mood:"Creamy & Crisp", difficulty:"Easy", why:"Fruit, walnuts, and chicken make a creamy salad with real crunch.", mainBase:"Salad", image:"images/waldorf-chicken-salad.webp", description:"Waldorf chicken salad combines tender chicken with crisp apples, celery, grapes, walnuts, and a light creamy dressing. The fruit keeps it fresh while the walnuts add rich crunch. Serve it in lettuce cups, over greens, or as a make-ahead lunch.",
    ingredientsList:["2 cups cooked chicken, diced","1 apple, diced","2 celery stalks, diced","1 cup grapes, halved","1/3 cup walnuts","1/3 cup Greek yogurt or mayo","1 tbsp lemon juice","lettuce leaves"],
    steps:["Combine chicken, apple, celery, grapes, and walnuts.","Mix yogurt or mayo with lemon juice, salt, and pepper.","Fold the dressing into the chicken mixture.","Chill briefly so the flavors settle.","Serve in lettuce cups or over greens."] },
  { name:"Roasted Cauliflower Chickpea Salad", cuisine:"Mediterranean", ingredients:"Cauliflower, chickpeas, arugula, tahini", mood:"Roasty & Nutty", difficulty:"Easy", why:"Roasted vegetables and tahini make a hearty plant-based salad.", mainBase:"Salad", image:"images/roasted-cauliflower-chickpea-salad.webp", description:"Roasted cauliflower and chickpeas bring golden edges and nutty flavor to a bed of arugula. Tahini lemon dressing, parsley, pomegranate, and almonds add creaminess, freshness, and crunch. It is a hearty plant-based salad that works warm or at room temperature.",
    ingredientsList:["1 head cauliflower, florets","1 can chickpeas, drained","3 cups arugula","2 tbsp tahini","1 lemon, juiced","1/4 cup pomegranate seeds","1/4 cup almonds","fresh parsley"],
    steps:["Roast cauliflower and chickpeas at 200C (400F) until golden.","Whisk tahini with lemon juice and a splash of water.","Arrange arugula in a bowl.","Add roasted cauliflower and chickpeas.","Drizzle with tahini dressing and finish with parsley, pomegranate, and almonds."] },
  { name:"Green Goddess Shrimp Salad", cuisine:"California", ingredients:"Shrimp, avocado, cucumber, herbs", mood:"Creamy & Fresh", difficulty:"Easy", why:"Grilled shrimp and herb dressing make a polished green bowl.", mainBase:"Salad", image:"images/green-goddess-shrimp-salad.webp", description:"Green goddess shrimp salad layers grilled shrimp over butter lettuce, avocado, cucumber, snap peas, radish, and plenty of herbs. The creamy green dressing ties everything together with a fresh, garden-like flavor. It is light, bright, and still satisfying.",
    ingredientsList:["300g shrimp, peeled","4 cups butter lettuce","1 avocado, sliced","1 cucumber, sliced","1 cup snap peas","4 radishes, sliced","green goddess dressing","fresh dill and mint"],
    steps:["Season shrimp and grill or sear until pink and lightly charred.","Arrange lettuce, avocado, cucumber, snap peas, and radish in a bowl.","Place warm shrimp on top.","Drizzle with green goddess dressing.","Finish with fresh herbs before serving."] },
  // ---------------- DESSERT ----------------
  { name:"Chocolate Chip Cookies", cuisine:"American", ingredients:"Flour, butter, chocolate chips", mood:"Sweet & Joyful", difficulty:"Easy", why:"The classic treat that never fails to please a crowd.", mainBase:"Dessert", image:"images/chocolate-chip-cookies.png", description:"Butter is creamed with sugar until light and fluffy, then studded generously with chocolate chips before baking into cookies with crisp edges and soft, chewy centers. The smell alone as they bake is enough to bring everyone into the kitchen. This is the classic treat that never goes out of style, equally perfect for lunchboxes, bake sales, or a late-night snack.",
    ingredientsList:["2 1/4 cups flour","1 cup butter, softened","3/4 cup sugar","3/4 cup brown sugar","2 eggs","2 cups chocolate chips","1 tsp baking soda"],
    steps:["Preheat the oven to 190°C (375°F) and line baking sheets with parchment.","Cream the butter with both sugars until light and fluffy.","Beat in the eggs, then mix in the flour and baking soda until just combined.","Fold in the chocolate chips.","Scoop onto the baking sheets and bake for 9-11 minutes until the edges are golden."] },
  { name:"Tiramisu", cuisine:"Italian", ingredients:"Mascarpone, coffee, ladyfingers", mood:"Elegant & Dreamy", difficulty:"Medium", why:"A no-bake dessert that tastes like a café treat.", mainBase:"Dessert", image:"images/tiramisu.png", description:"Delicate ladyfinger biscuits are briefly dipped in strong coffee, then layered with a rich, airy mascarpone cream and dusted with cocoa powder. Since it needs to chill for a few hours before serving, the flavors have time to meld into something wonderfully cohesive and dreamy. This elegant, no-bake dessert tastes just like something from a fine Italian café, without ever needing to turn on the oven.",
    ingredientsList:["250g mascarpone cheese","2 eggs, separated","1/2 cup sugar","24 ladyfinger biscuits","1.5 cups strong brewed coffee, cooled","cocoa powder, for dusting"],
    steps:["Whisk egg yolks with sugar until pale, then fold in the mascarpone until smooth.","Whip the egg whites to stiff peaks and gently fold into the mascarpone mixture.","Quickly dip each ladyfinger into the cooled coffee and arrange in a single layer in a dish.","Spread half the mascarpone cream over the ladyfingers, then repeat with another layer.","Dust generously with cocoa powder and chill for at least 4 hours before serving."] },
  { name:"Molten Chocolate Cake", cuisine:"French", ingredients:"Chocolate, butter, egg", mood:"Decadent & Romantic", difficulty:"Medium", why:"A gooey molten center that makes every bite feel special.", mainBase:"Dessert", image:"images/molten-chocolate-cake.png", description:"Rich chocolate cake batter is baked just until the edges set while the center stays deliberately underbaked, creating a warm, gooey molten core that oozes out the moment you cut into it. Timing is everything here, so pulling it from the oven at just the right moment is key to that dramatic reveal. It's a decadent, romantic dessert that turns any evening into something special.",
    ingredientsList:["115g dark chocolate","115g butter","2 eggs plus 2 egg yolks","1/2 cup sugar","1/4 cup flour"],
    steps:["Preheat the oven to 220°C (425°F) and butter individual ramekins.","Melt the chocolate and butter together until smooth.","Whisk the eggs, egg yolks, and sugar until pale and thick.","Fold in the melted chocolate mixture, then gently fold in the flour.","Divide between ramekins and bake for 10-12 minutes until the edges are set but the center is still soft; invert onto plates and serve immediately."] },
  { name:"Apple Pie", cuisine:"American", ingredients:"Apple, cinnamon, pie crust", mood:"Nostalgic & Homely", difficulty:"Medium", why:"A timeless dessert perfect for family gatherings.", mainBase:"Dessert", image:"images/apple-pie.png", description:"Tender apple slices are tossed with warm cinnamon and a touch of sugar, then baked between flaky, buttery layers of pie crust until golden and bubbling. The smell of cinnamon and baked apples filling the house is practically a tradition in itself. This timeless, nostalgic dessert has earned its place as the centerpiece of countless family gatherings and holiday tables.",
    ingredientsList:["6 apples, peeled and sliced","3/4 cup sugar","1.5 tsp cinnamon","2 pie crusts (top and bottom)","2 tbsp butter, cubed","1 tbsp flour"],
    steps:["Preheat the oven to 200°C (400°F) and line a pie dish with one crust.","Toss the sliced apples with sugar, cinnamon, and flour.","Fill the crust with the apple mixture and dot with butter.","Cover with the second crust, sealing and crimping the edges, and cut a few vents on top.","Bake for 45-50 minutes until the crust is golden and the filling is bubbling."] },
  { name:"Mango Sticky Rice", cuisine:"Thai", ingredients:"Sticky rice, mango, coconut milk", mood:"Tropical & Sweet", difficulty:"Easy", why:"A sweet finish that transports you straight to Thailand.", mainBase:"Dessert", image:"images/mango-sticky-rice.png", description:"Glutinous sticky rice is steamed until tender, then soaked in sweetened coconut milk until it turns rich and slightly chewy. Served alongside thick slices of ripe, juicy mango and an extra drizzle of coconut cream, the combination of warm rice and cool fruit is a beloved Thai dessert. One bite and you'll feel like you're enjoying it fresh off a street cart in Bangkok.",
    ingredientsList:["1.5 cups glutinous sticky rice, soaked overnight","1 cup coconut milk","1/3 cup sugar","1/4 tsp salt","2 ripe mangoes, sliced"],
    steps:["Steam the soaked sticky rice for 20-25 minutes until tender.","Warm the coconut milk with sugar and salt until the sugar dissolves.","Pour most of the sweetened coconut milk over the hot rice and let it soak in for 10-15 minutes.","Slice the ripe mangoes just before serving.","Plate the sticky rice with mango slices and drizzle with the remaining coconut milk."] },
  { name:"Fluffy Pancakes", cuisine:"American", ingredients:"Flour, egg, milk, syrup", mood:"Sweet & Fluffy", difficulty:"Easy", why:"A weekend breakfast treat that doubles as dessert.", mainBase:"Dessert", image:"images/fluffy-pancakes.png", description:"A simple batter of flour, eggs, and milk is whisked just enough to keep the pancakes tender, then cooked in a hot pan until each one puffs up light and fluffy. Stacked high and finished with a generous pour of warm maple syrup, they feel indulgent enough to double as a dessert. It's a weekend breakfast tradition that the whole family looks forward to.",
    ingredientsList:["1.5 cups flour","2 tbsp sugar","2 tsp baking powder","1.25 cups milk","1 egg","3 tbsp melted butter","maple syrup, to serve"],
    steps:["Whisk together flour, sugar, and baking powder in a bowl.","In a separate bowl, whisk the milk, egg, and melted butter.","Pour the wet ingredients into the dry ingredients and stir just until combined (a few lumps are fine).","Heat a lightly greased skillet over medium heat and pour in batter for each pancake.","Cook until bubbles form on top, flip, and cook until golden; serve stacked with maple syrup."] },
  { name:"Classic Cheesecake", cuisine:"American", ingredients:"Cream cheese, sugar, graham crust", mood:"Rich & Creamy", difficulty:"Medium", why:"A crowd-pleaser that's easier to make than it looks.", mainBase:"Dessert", image:"images/classic-cheesecake.png", description:"A buttery graham cracker crust supports a thick, velvety filling of sweetened cream cheese baked low and slow until perfectly set but still creamy. Baking it gently and letting it cool gradually helps prevent cracks on top, giving it that clean, bakery-style finish. It looks like an impressive showstopper, but it's actually far more approachable to make at home than most people expect.",
    ingredientsList:["1.5 cups graham cracker crumbs","6 tbsp melted butter","900g cream cheese, softened","1 cup sugar","3 eggs","1 tsp vanilla extract"],
    steps:["Mix graham cracker crumbs with melted butter and press into the base of a springform pan.","Beat the cream cheese and sugar until smooth and creamy.","Add the eggs one at a time, beating gently after each addition, then stir in vanilla.","Pour the filling over the crust and bake at 160°C (325°F) for 55-60 minutes until the center is just set.","Cool gradually in the oven with the door ajar, then chill for at least 4 hours before slicing."] },
  { name:"Banana Pudding", cuisine:"American", ingredients:"Banana, vanilla pudding, cookies", mood:"Sweet & Nostalgic", difficulty:"Easy", why:"A layered treat that's always a hit at potlucks.", mainBase:"Dessert", image:"images/banana-pudding.png", description:"Layers of creamy vanilla pudding, fresh banana slices, and soft vanilla cookies are stacked together and chilled until the cookies soften into a cake-like texture. As it sits, the flavors meld together into something greater than the sum of its parts. This nostalgic, no-bake layered dessert is a guaranteed hit at potlucks, barbecues, and family gatherings alike.",
    ingredientsList:["3 cups prepared vanilla pudding","4 bananas, sliced","1 box vanilla wafer cookies","1 cup whipped cream"],
    steps:["Spread a thin layer of vanilla pudding in the bottom of a serving dish.","Add a layer of vanilla wafer cookies followed by a layer of sliced bananas.","Repeat the layers, ending with a layer of pudding on top.","Cover and chill for at least 4 hours until the cookies soften.","Top with whipped cream just before serving."] },
  { name:"Matcha Roll Cake", cuisine:"Japanese Inspired", ingredients:"Matcha, flour, egg, cream", mood:"Soft & Elegant", difficulty:"Medium", why:"A light sponge cake with a beautiful green tea swirl.", mainBase:"Dessert", image:"images/matcha-roll-cake.png", description:"Matcha roll cake pairs a soft green tea sponge with a cloud of lightly sweetened cream. The spiral looks impressive when sliced, but the flavors stay gentle and balanced. A few berries on the side add freshness and color without distracting from the matcha.",
    ingredientsList:["4 eggs","1/2 cup sugar","3/4 cup cake flour","1 tbsp matcha powder","1 cup whipped cream","2 tbsp powdered sugar","berries, to serve"],
    steps:["Whisk eggs and sugar until pale and airy.","Fold in sifted cake flour and matcha powder gently.","Spread batter on a lined sheet pan and bake at 180C (350F) for 10-12 minutes.","Cool, then spread with lightly sweetened whipped cream.","Roll carefully, chill, and slice before serving with berries."] },
  { name:"Berry Crumble", cuisine:"American", ingredients:"Mixed berries, oats, butter, sugar", mood:"Juicy & Cozy", difficulty:"Easy", why:"Bubbling berries and a golden oat topping make an easy crowd-pleaser.", mainBase:"Dessert", image:"images/berry-crumble.png", description:"Berry crumble is simple, generous, and full of cozy contrast. Juicy mixed berries bubble under a crisp oat topping, creating a dessert that feels homemade without much effort. It is best served warm with vanilla ice cream melting over the top.",
    ingredientsList:["4 cups mixed berries","1/2 cup sugar","1 tbsp lemon juice","1 tbsp cornstarch","1 cup rolled oats","1/2 cup flour","1/2 cup brown sugar","6 tbsp cold butter"],
    steps:["Toss berries with sugar, lemon juice, and cornstarch in a baking dish.","Mix oats, flour, brown sugar, and cold butter until crumbly.","Scatter the crumble topping over the berries.","Bake at 190C (375F) for 30-35 minutes until bubbling and golden.","Serve warm with vanilla ice cream."] },
  { name:"Creme Brulee", cuisine:"French", ingredients:"Cream, egg yolk, sugar, vanilla", mood:"Elegant & Silky", difficulty:"Medium", why:"A crackly caramel top hides a silky vanilla custard.", mainBase:"Dessert", image:"images/creme-brulee.webp", description:"Creme brulee is all about contrast: a glassy caramelized sugar shell over cool, silky vanilla custard. The ingredient list is short, but the result feels polished and restaurant-worthy. Crack the top with a spoon and the creamy custard underneath does the rest.",
    ingredientsList:["2 cups heavy cream","5 egg yolks","1/2 cup sugar","1 tsp vanilla extract","extra sugar for topping","berries, optional"],
    steps:["Warm cream with vanilla until steaming, then cool slightly.","Whisk egg yolks with sugar until smooth.","Slowly whisk warm cream into the yolks.","Bake in ramekins in a water bath until just set, then chill.","Sprinkle with sugar and torch until caramelized before serving."] },
  { name:"Vanilla Panna Cotta", cuisine:"Italian", ingredients:"Cream, vanilla, gelatin, berries", mood:"Silky & Light", difficulty:"Easy", why:"A creamy no-bake dessert that looks beautifully refined.", mainBase:"Dessert", image:"images/vanilla-panna-cotta.webp", description:"Vanilla panna cotta is a simple chilled cream dessert with a delicate wobble and a silky finish. Berry compote adds brightness and color against the gentle vanilla base. It is easy to prepare ahead and feels elegant without demanding much work.",
    ingredientsList:["2 cups cream","1/2 cup milk","1/3 cup sugar","2 tsp gelatin","1 tsp vanilla extract","1 cup berry compote"],
    steps:["Bloom gelatin in a little cold milk.","Warm cream, remaining milk, sugar, and vanilla until the sugar dissolves.","Stir in bloomed gelatin until fully melted.","Pour into molds or glasses and chill until set.","Serve with berry compote on top."] },
  { name:"Lemon Tart", cuisine:"French", ingredients:"Lemon, tart crust, egg, butter", mood:"Bright & Buttery", difficulty:"Medium", why:"Tangy lemon curd and crisp pastry make a clean, sunny dessert.", mainBase:"Dessert", image:"images/lemon-tart.webp", description:"A glossy lemon tart balances sharp citrus curd with a buttery, crisp pastry shell. The filling is smooth and bright, while the crust adds enough richness to keep the lemon from feeling too sharp. It is a cheerful dessert that cuts cleanly and looks beautiful on the table.",
    ingredientsList:["1 baked tart shell","3 eggs","3 lemons, juiced and zested","3/4 cup sugar","6 tbsp butter","powdered sugar, optional"],
    steps:["Whisk eggs, lemon juice, zest, and sugar in a heatproof bowl.","Cook gently over simmering water until thickened.","Whisk in butter until smooth and glossy.","Pour into the baked tart shell and chill until set.","Dust with powdered sugar or lemon zest before serving."] },
  { name:"Apple Crumble", cuisine:"British", ingredients:"Apple, oats, butter, cinnamon", mood:"Warm & Cozy", difficulty:"Easy", why:"Tender cinnamon apples and a golden oat topping are pure comfort.", mainBase:"Dessert", image:"images/apple-crumble.webp", description:"Apple crumble is simple, cozy, and deeply satisfying. Cinnamon-spiced apples bake until tender under a buttery oat topping that turns golden and crisp. Serve it warm with vanilla ice cream and it becomes the kind of dessert that disappears quickly.",
    ingredientsList:["5 apples, diced","1/3 cup sugar","1 tsp cinnamon","1 tbsp lemon juice","1 cup rolled oats","1/2 cup flour","1/2 cup brown sugar","6 tbsp cold butter"],
    steps:["Toss apples with sugar, cinnamon, and lemon juice in a baking dish.","Mix oats, flour, brown sugar, and cold butter into crumbs.","Scatter the crumble topping over the apples.","Bake at 190C (375F) until bubbling and golden.","Serve warm with vanilla ice cream."] },
  { name:"Fudgy Brownies", cuisine:"American", ingredients:"Chocolate, butter, cocoa, egg", mood:"Rich & Chocolatey", difficulty:"Easy", why:"Crackly tops and a dense center make them hard to resist.", mainBase:"Dessert", image:"images/fudgy-brownies.webp", description:"Fudgy brownies are dense, glossy, and deeply chocolatey with the classic crackly top. A little salt sharpens the chocolate flavor and keeps each square from tasting flat. They are simple to make, easy to share, and excellent slightly warm.",
    ingredientsList:["170g dark chocolate","1/2 cup butter","3/4 cup sugar","2 eggs","1/2 cup flour","1/4 cup cocoa powder","1/2 tsp salt"],
    steps:["Melt chocolate and butter together until smooth.","Whisk in sugar, then eggs one at a time.","Fold in flour, cocoa powder, and salt.","Spread into a lined pan.","Bake at 180C (350F) until the edges set but the center stays fudgy."] },
  { name:"Strawberry Mochi", cuisine:"Japanese", ingredients:"Mochi, strawberry, red bean, starch", mood:"Soft & Sweet", difficulty:"Medium", why:"Chewy mochi, fruit, and red bean make a delicate bite.", mainBase:"Dessert", image:"images/strawberry-mochi.webp", description:"Strawberry mochi wraps juicy strawberries and sweet red bean paste in a soft, chewy rice flour dough. The contrast between tender mochi and fresh fruit makes each bite feel playful and delicate. It is a lovely chilled dessert for tea time.",
    ingredientsList:["1 cup glutinous rice flour","3/4 cup water","1/4 cup sugar","8 strawberries","1 cup red bean paste","potato starch for dusting"],
    steps:["Mix rice flour, water, and sugar into a smooth batter.","Steam or microwave until the dough turns translucent and sticky.","Dust a surface generously with starch.","Wrap each strawberry with red bean paste, then mochi dough.","Pinch closed and chill briefly before serving."] },
  { name:"Baklava", cuisine:"Middle Eastern", ingredients:"Phyllo, pistachio, honey, butter", mood:"Flaky & Sweet", difficulty:"Medium", why:"Crisp pastry layers soak up honey syrup and toasted nuts.", mainBase:"Dessert", image:"images/baklava.webp", description:"Baklava layers buttered phyllo pastry with chopped nuts, then soaks everything in fragrant honey syrup. The top stays crisp and flaky while the center turns sticky and rich. It is sweet, celebratory, and perfect in small pieces with tea or coffee.",
    ingredientsList:["1 pack phyllo pastry","2 cups pistachios or walnuts, chopped","1 cup butter, melted","1 cup honey","1/2 cup sugar","1/2 cup water","1 tsp lemon juice"],
    steps:["Layer phyllo sheets in a pan, brushing each with melted butter.","Add chopped nuts between layers.","Cut into diamonds before baking.","Bake until deeply golden and crisp.","Pour warm honey syrup over the hot pastry and let it soak."] },
  { name:"Churros", cuisine:"Spanish", ingredients:"Flour, butter, cinnamon sugar, chocolate", mood:"Crisp & Fun", difficulty:"Medium", why:"Cinnamon sugar and chocolate sauce make every bite festive.", mainBase:"Dessert", image:"images/churros.webp", description:"Churros are crisp, ridged pastries rolled in cinnamon sugar while still warm. The dough is simple but fries into a golden shell with a tender center. Dip them in thick chocolate sauce and they become a joyful dessert for sharing.",
    ingredientsList:["1 cup water","4 tbsp butter","1 cup flour","2 eggs","1/2 cup sugar","1 tsp cinnamon","chocolate sauce"],
    steps:["Bring water and butter to a boil, then stir in flour to form a dough.","Beat in eggs once the dough cools slightly.","Pipe strips of dough into hot oil.","Fry until golden and crisp.","Roll in cinnamon sugar and serve with chocolate sauce."] },
  { name:"Pavlova", cuisine:"Australian", ingredients:"Meringue, cream, berries, passion fruit", mood:"Airy & Festive", difficulty:"Medium", why:"Crisp meringue, soft center, cream, and fruit feel celebratory.", mainBase:"Dessert", image:"images/pavlova.webp", description:"Pavlova has a crisp meringue shell with a soft, marshmallowy center, topped with whipped cream and fresh fruit. Passion fruit adds tangy brightness against the sweet base. It looks dramatic but tastes light, making it a beautiful finish for a gathering.",
    ingredientsList:["4 egg whites","1 cup sugar","1 tsp vinegar","1 tsp cornstarch","1 cup whipped cream","2 cups mixed berries","passion fruit pulp"],
    steps:["Whip egg whites until foamy, then gradually add sugar.","Beat until glossy and stiff, then fold in vinegar and cornstarch.","Shape into a nest on parchment.","Bake low and slow until crisp outside, then cool completely.","Top with whipped cream, berries, and passion fruit."] },
  { name:"Pecan Pie", cuisine:"American", ingredients:"Pecan, pie crust, syrup, egg", mood:"Nutty & Decadent", difficulty:"Medium", why:"Glossy pecans and caramel filling make a classic sweet slice.", mainBase:"Dessert", image:"images/pecan-pie.webp", description:"Pecan pie combines a flaky crust with glossy pecans and a rich caramel-like filling. The nuts toast as the pie bakes, giving each slice deep flavor and a satisfying crunch. It is classic, generous, and especially good with whipped cream.",
    ingredientsList:["1 pie crust","1.5 cups pecans","3 eggs","1 cup corn syrup or golden syrup","1/2 cup brown sugar","4 tbsp butter, melted","1 tsp vanilla"],
    steps:["Arrange pecans in the pie crust.","Whisk eggs, syrup, brown sugar, melted butter, and vanilla.","Pour the filling over the pecans.","Bake at 175C (350F) until set around the edges with a slight wobble in the center.","Cool completely before slicing."] },
  { name:"Banoffee Pie", cuisine:"British", ingredients:"Banana, caramel, cream, biscuit crust", mood:"Creamy & Indulgent", difficulty:"Easy", why:"Banana, caramel, and cream make a no-bake crowd-pleaser.", mainBase:"Dessert", image:"images/banoffee-pie.webp", description:"Banoffee pie layers a buttery biscuit crust with caramel, banana slices, whipped cream, and chocolate shavings. It is rich, creamy, and easy to make ahead because the fridge does most of the work. Every bite has soft banana, sweet caramel, and airy cream.",
    ingredientsList:["1 biscuit crust","1 cup caramel or dulce de leche","3 bananas, sliced","1.5 cups whipped cream","chocolate shavings"],
    steps:["Spread caramel over the biscuit crust.","Layer banana slices over the caramel.","Top with whipped cream.","Scatter chocolate shavings over the top.","Chill until ready to slice and serve."] },
  { name:"Affogato", cuisine:"Italian", ingredients:"Gelato, espresso, chocolate", mood:"Bittersweet & Simple", difficulty:"Easy", why:"Hot espresso over cold gelato is effortless and dramatic.", mainBase:"Dessert", image:"images/affogato.webp", description:"Affogato is the simplest kind of dessert magic: hot espresso poured over cold vanilla gelato. The coffee melts the gelato into a creamy bittersweet sauce while chocolate shavings add a little texture. It takes minutes but feels wonderfully special.",
    ingredientsList:["2 scoops vanilla gelato","2 shots hot espresso","dark chocolate shavings","small pinch of sea salt, optional"],
    steps:["Place gelato scoops in small glasses or bowls.","Brew fresh espresso just before serving.","Pour hot espresso over the gelato.","Add chocolate shavings and a tiny pinch of salt if desired.","Serve immediately while hot and cold contrast remains."] },
  { name:"Chocolate Eclairs", cuisine:"French", ingredients:"Choux pastry, pastry cream, chocolate glaze", mood:"Glossy & Classic", difficulty:"Medium", why:"Cream-filled pastry and shiny chocolate glaze feel bakery-perfect.", mainBase:"Dessert", image:"images/chocolate-eclairs.webp", description:"Chocolate eclairs are made from airy choux pastry filled with vanilla pastry cream and finished with a glossy chocolate glaze. The crisp shell and cool cream create a classic bakery texture. They take a little care, but the result feels completely worth it.",
    ingredientsList:["1 batch choux pastry","2 cups pastry cream","150g dark chocolate","1/2 cup cream","1 egg wash"],
    steps:["Pipe choux pastry into long strips on a lined baking sheet.","Brush with egg wash and bake until puffed and golden.","Cool completely, then fill with pastry cream.","Melt chocolate with cream to make a smooth glaze.","Dip the tops of the eclairs in glaze and let set."] },
  { name:"Creamy Rice Pudding", cuisine:"European", ingredients:"Rice, milk, cinnamon, raisins", mood:"Gentle & Comforting", difficulty:"Easy", why:"A soft, cinnamon-scented bowl that feels calm and nostalgic.", mainBase:"Dessert", image:"images/creamy-rice-pudding.webp", description:"Creamy rice pudding simmers rice slowly in milk until soft and spoonable. Cinnamon, vanilla, and raisins give it a familiar warmth, while the texture stays rich and comforting. It can be served warm or chilled depending on the mood.",
    ingredientsList:["1 cup short-grain rice","4 cups milk","1/3 cup sugar","1 tsp vanilla extract","1/2 tsp cinnamon","1/3 cup raisins","pinch of salt"],
    steps:["Combine rice, milk, sugar, and salt in a saucepan.","Simmer gently, stirring often, until the rice is tender and creamy.","Stir in vanilla, cinnamon, and raisins.","Cook a few minutes more until thickened.","Serve warm or chill for later."] },
  { name:"Lemon Posset", cuisine:"British", ingredients:"Cream, lemon, sugar, berries", mood:"Silky & Bright", difficulty:"Easy", why:"Just a few ingredients set into a smooth citrus cream.", mainBase:"Dessert", image:"images/lemon-posset.webp", description:"Lemon posset turns cream, sugar, and lemon into a silky chilled dessert with almost no effort. The citrus gently sets the cream while keeping the flavor bright and clean. Serve it in small glasses with berries or a shortbread cookie for a polished finish.",
    ingredientsList:["2 cups heavy cream","2/3 cup sugar","2 lemons, juiced and zested","berries","shortbread cookies"],
    steps:["Simmer cream and sugar for a few minutes until the sugar dissolves.","Remove from heat and stir in lemon juice and zest.","Pour into small glasses or cups.","Chill until softly set.","Serve with berries and shortbread cookies."] },
];
